function planetTypeFor(p){return PLANET_TYPES.find(t=>t.id===p?.planetType)||RETIRED_WORLD_TYPES.find(t=>t.id===p?.planetType)||PLANET_TYPES[0];}
function planetBasePopulation(p){return planetTypeFor(p).basePopulation;}
function rollPlanetType(previous){const choices=PLANET_TYPES.filter(p=>p.id!==previous);return choices[Math.min(choices.length-1,Math.floor(Math.random()*choices.length))];}
'use strict';
const HOUR=3600000, SAVE_KEY=window.isStaffWorkspace?'starfall-staff-workspace-v1':'starfall-round-v2', LEGACY_KEY='starfall-save';
const RES={metal:{label:'METAL',icon:'⬡'},crystal:{label:'CRYSTAL',icon:'◇'},eonium:{label:'EONIUM',icon:'⌬'}};
const WORKFORCE_LIMITS={mining:25,research:50,construction:35,shipwright:60,security:50};
const UI_THEMES=[['Neutral','Vesper Command'],['Classic','Classic'],['Terran','Helion Ascendancy'],['Cathaar','Velari Ember'],['Xandathrii','Nexari Swarm'],['Zikonian','Kryth Frost'],['Eitraides','Auralis Tide'],['LCARS','Stellar Federation'],['Borg','Assimilation Nexus'],['Stargate','Gatebound Legacy'],['DoctorWho','Temporal Voyager'],['Battlestar','Colonial Vanguard'],['AstraNexus','Astra Nexus'],['SilverWorld','Silver Registry'],['BorgWorld','Unimatrix Sovereign'],['UndineWorld','Fluidic Dominion'],['LegendaryWorld','Imperial Legend'],['UltimateWorld','Arrakis Ascendant'],['Unimatrix999World','Unimatrix999 Sovereign']];
function visibleWorldThemes(){return UI_THEMES.filter(([id])=>!['SilverWorld','BorgWorld','UndineWorld','LegendaryWorld','UltimateWorld','Unimatrix999World'].includes(id)||window.isGameAdmin||window.isStaffWorkspace||window.isPortalStaff||planetTypeFor(state).theme===id);}
const UI_THEME_VALUES=UI_THEMES.map(([id])=>id);
function themeLabel(id){return UI_THEMES.find(([value])=>value===id)?.[1]||id;}
const SHIP_CLASS_TARGET={Fi:'Fighter',Co:'Corvette',Fr:'Frigate',De:'Destroyer',Cr:'Cruiser',Bs:'Battleship'};
function shipFromRow(row){const [race,name,shipClass,t1,t2,t3,type,cloaked,initiative,guns,armour,damage,er,metal,crystal,eonium,ac,dc,eta]=row;const id=`${race.toLowerCase()}-${name.toLowerCase().replace(/[^a-z0-9]+/g,'-')}`;return [id,{id,race,name,icon:{Fighter:'✧',Corvette:'⌁',Frigate:'⬡',Destroyer:'◈',Cruiser:'◉',Battleship:'⬢'}[shipClass],class:shipClass,targetSlots:[t1,t2,t3].map(t=>t==='-'?'':SHIP_CLASS_TARGET[t]||t),target:[t1,t2,t3].filter(x=>x!=='-').map(x=>SHIP_CLASS_TARGET[x]||x),type,cloaked:cloaked==='Y',initiative,guns,armour,damage:damage==='-'?0:damage,populationDamage:['Cruiser','Battleship'].includes(shipClass)?0.1:null,populationDamageUnit:'percent',er,cost:{metal,crystal,eonium},ac,dc,eta,pod:type==='Pod'||type==='Steal',factory:['Fighter','Corvette'].includes(shipClass)?'lightFactory':['Frigate','Destroyer','Cruiser'].includes(shipClass)?'mediumFactory':'heavyFactory',research:{Fighter:'fighter',Corvette:'corvette',Frigate:'frigate',Destroyer:'destroyer',Cruiser:'destroyer',Battleship:'siege'}[shipClass]}];}
