function nfmt(n){return Math.max(0,Math.floor(n||0)).toLocaleString('en-US');}function signed(n){return (n>=0?'+':'')+nfmt(n);}function totalRoids(r){return Object.values(r||{}).reduce((a,b)=>a+(b||0),0);}function totalShips(o){return Object.values(o||{}).reduce((a,b)=>a+(b||0),0);}function notify(msg,error=false){const el=document.createElement('div');el.className='toast'+(error?' err':'');el.textContent=msg;document.getElementById('toasts').append(el);setTimeout(()=>el.remove(),3500);}function addNews(text,type='info',details=null){const home=state.galaxy?.find(p=>p.player),population=Math.max(0,state.population||0),context={actor:home?.ruler||'',planet:home?.name||'',coords:home?.coords||'',population,world:planetTypeFor(state).name,miningBonus:population*.001,workBonus:Math.floor(population/100),resources:{...state.resources},xp:state.xp||0};state.news.unshift({text,type,tick:state.tick,at:Date.now(),context,...(details?{details}: {})});}
