function factoryOwned(id){return Math.max(0,Math.floor(Number(state.buildings?.[id])||0));}
function assignedFactories(id){const owned=factoryOwned(id),value=Number(state.factoryAssignments?.[id]??owned);return Math.max(0,Math.min(owned,Math.floor(Number.isFinite(value)?value:owned)));}
function normalizeFactoryAssignments(){state.factoryAssignments=state.factoryAssignments||{};for(const id of Object.keys(FACTORY_WEIGHTS))state.factoryAssignments[id]=assignedFactories(id);for(const order of [state.production,...state.productionQueue].filter(Boolean)){if(!order.orderNumber)order.orderNumber=state.nextShipOrderNumber=(state.nextShipOrderNumber||0)+1;if(!order.factoryAssignments)order.factoryAssignments=copy(state.factoryAssignments);}}
function factoryThroughput(order=null){return Object.keys(FACTORY_WEIGHTS).reduce((sum,id)=>sum+(order?.factoryAssignments?Math.max(0,Math.min(factoryOwned(id),Math.floor(Number(order.factoryAssignments[id])||0))):assignedFactories(id))*FACTORY_WEIGHTS[id],0);}
function productionFactoryHTML(){const rows=Object.keys(FACTORY_WEIGHTS).map(id=>{const [name,ships]=FACTORY_LABELS[id],owned=factoryOwned(id),assigned=assignedFactories(id),weight=FACTORY_WEIGHTS[id];return `<div class="factory-assignment-row"><div class="factory-assignment-copy"><b>${name}</b><small>${ships}</small></div><label class="factory-assignment-input"><span>ASSIGNED</span><input type="number" inputmode="numeric" min="0" max="${owned}" step="1" value="${assigned}" data-factoryassign="${id}" aria-label="Number of ${name}s assigned to production"> <i>/ ${owned}</i></label><div class="factory-assignment-rate"><b>+${Math.round(weight*35)} PT</b><small>per tick</small></div></div>`}).join(''),assigned=Object.keys(FACTORY_WEIGHTS).reduce((sum,id)=>sum+assignedFactories(id),0),total=Object.keys(FACTORY_WEIGHTS).reduce((sum,id)=>sum+factoryOwned(id),0);return `<section class="panel factory-assignment-panel"><div class="ph"><div class="pt">FACTORY ASSIGNMENT</div><span class="meta"><b id="factoryOutputRate">${nfmt(productionRate(null))}</b> BUILD POINTS / TICK</span></div><div class="factory-assignment-note">Choose facilities for new orders. Apply to order # updates the active order; unassigned factories stay idle. A matching factory is still required to unlock each ship class.</div><div class="factory-assignment-grid">${rows}</div><div class="factory-assignment-footer"><span><b>${assigned} / ${total}</b> FACTORIES ASSIGNED · ${Math.max(0,total-assigned)} IDLE</span><button class="btn" type="button" data-factory-assign-all>ASSIGN ALL AVAILABLE</button>${state.production?`<button class="btn primary" type="button" data-factory-apply-order="${state.production.orderNumber}">APPLY TO ORDER #${state.production.orderNumber}</button>`:''}</div></section>`;}
function mineLimit(){return [100,200,300,500,750,1000,1250,1500,2000,2500,3000,3500,4500,5500,6500,8000,10000][Math.min(16,state.research.cargo||0)];}
function buildingLimit(){return [20,50,100,150,200,300,400][Math.min(6,state.research.construction||0)];}
function coreIncome(){return [1000,3500,7000,12500,20000][Math.min(4,state.research.core||0)];}
function governmentEconomyBonus(key){return ({Corporatism:{mining:24,research:-15,construction:-15},Democracy:{research:30},Nationalism:{mining:16,research:20,construction:-5},Socialism:{mining:10,research:10,construction:15},Totalitarianism:{research:-5,construction:25},Anarchy:{mining:-25,research:-25,construction:-25}}[currentGovernmentName()]||{})[key]||0;}
function fleetBaseTravelTime(ships,target,mission){const defence=mission==='Defence'||mission==='Fake Defence';if(defence&&galaxyOf(target.coords)===homeGalaxy())return 5;const heavy=Object.entries(ships).some(([id,n])=>n>0&&['Cruiser','Battleship'].includes(SHIPS[id]?.class)),medium=Object.entries(ships).some(([id,n])=>n>0&&['Frigate','Destroyer'].includes(SHIPS[id]?.class));const alliance=defence&&target.alliance===state.alliance.name?1:0,hub=isAllianceMember('A. Commander')&&hasAllianceEffect('transwarpHub')?1:0;return Math.max(1,12-Math.min(4,state.research.travel||0)+(heavy?2:medium?1:0)-alliance-hub);}
function fleetTravelTime(ships,target,mission){return Math.max(1,fleetBaseTravelTime(ships,target,mission)+(planetTypeFor(state).travelEtaBonus||0));}
function populationCapacity(){return planetBasePopulation(state)+Math.max(0,Math.floor(state.buildings.biodome||0))*50-Math.floor(Math.max(0,state.biodomeDamage||0)/20);}
function populationGrowthBonus(p=state){return Math.max(0,Math.min(5,Math.floor(p.research?.demography||0)))*20;}
function populationGrowthRate(p=state){return Math.max(0,Math.floor(p.buildings?.biodome||0))*(1+populationGrowthBonus(p)/100)*(1+planetTypeFor(p).growthPercent/100);}
function growColonyPopulation(p=state){const cap=planetBasePopulation(p)+Math.max(0,Math.floor(p.buildings?.biodome||0))*50-Math.floor(Math.max(0,p.biodomeDamage||0)/20),population=Math.max(0,Math.min(cap,Math.floor(p.population??planetBasePopulation(p))));if(population>=cap){p.population=population;p.populationGrowthCarry=0;return 0;}const budget=populationGrowthRate(p)+(Number(p.populationGrowthCarry)||0),gain=Math.min(cap-population,Math.floor(budget+1e-9));p.population=population+gain;p.populationGrowthCarry=p.population>=cap?0:Math.max(0,budget-gain);return gain;}
function populationIncomeBonus(){return Math.max(0,Math.min(populationCapacity(),state.population||0))*.001;}
function populationStrikeMultiplier(p=state.galaxy.find(x=>x.player)){return p?.strikeUntilTick>state.tick?0.9:1;}
function grossIncome(){const out={};const mining=workforceRate('mining')/100;for(const k of Object.keys(RES)){const refKey=k+'Refinery';const raw=coreIncome()+(state.roids[k]||0)*250+(state.buildings[refKey]||0)*1100;const finance=(state.buildings.financeCenter||0)*.005;out[k]=Math.round(raw*(1+mining+finance+populationIncomeBonus()/100+governmentEconomyBonus('mining')/100)*(state.config?.incomeMultiplier||1)*allianceIncomeMultiplier('A. Commander')*populationStrikeMultiplier());}return out;}function income(){const gross=grossIncome(),out={};for(const k of Object.keys(RES)){const taxed=isAllianceMember('A. Commander')&&state.userSettings.allianceTaxEnabled?Math.floor(gross[k]*Math.max(0,Math.min(5,Number(state.alliance.tax)||0))/100):0;out[k]=gross[k]-taxed;}return out;}
const TECH_TREE=[{id:'demography',name:'Population Development',max:5,step:[1200,1800,2600,3600,4800],levels:['Settlement Registry','Family Support','Medical Networks','Habitat Integration','Colonial Renewal'],desc:'Each level adds 20% to Biodome population growth. Five levels give +100%; housing remains +50 per dome.'},{id:'travel',name:'Spacetravel',max:4,step:[1600,1600,1600,1600],levels:['Jumpgate','Warpgate','Stargate','Hypergate'],desc:'Each level reduces travel time outside the home galaxy.'},{id:'construction',name:'Infrastructure',max:6,step:[1600,1600,0,2400,2400,2400],levels:['Infrastructure Upgrade','Improved Power Grid','Advanced Power Systems','Advanced Infrastructure','Expert Infrastructure','Infrastructure Revolution'],desc:'Raises facility capacity from 20 to 400.'},{id:'fighter',name:'Ships',max:3,step:[2400,2400,2400],levels:['Fighter Class Hulls','Frigate Class Hulls','Siege Weapons'],desc:'Unlocks light ships, medium ships, then heavy ships.'},{id:'scans',name:'Scans',max:7,step:[1600,800,2400,1200,1200,2400,0],levels:['Landing Scan','Development Scan','Unit Analysis','Decryption Algorithms','Warp Particle Detection','Jumpgate Probing','Advanced Unit Analysis'],desc:'Unlocks scan types on the Waves page.'},{id:'core',name:'Core Mining',max:4,step:[2400,2400,2400,0],levels:['Advanced Core Extraction','Expert Core Extraction','Deep Core Drilling','Magma Extraction'],desc:'Increases core resource extraction.'},{id:'covert',name:'Covert Ops',max:8,step:[1200,400,800,800,800,800,800,1600],levels:['Network Defection','Security Defection','Research Transferral','Warp Core Manipulation','Portable EMP Emitters','Structural Integrity','Bank-System Hacking','Subversive Techniques'],desc:'Unlocks agent operations in a future practice module.'},{id:'cargo',name:'Heavy Cargo Transfers',max:16,step:[1200,400,800,1200,1200,1600,800,0,0,0,0,0,2400,0,0,0],levels:['Heavy Cargo Transfers I','Heavy Cargo Transfers II','Heavy Cargo Transfers III','Heavy Cargo Transfers IV','Heavy Cargo Transfers V','Heavy Cargo Transfers VI','Heavy Cargo Transfers VII','Heavy Cargo Transfers VIII','Heavy Cargo Transfers IX','Heavy Cargo Transfers X','Heavy Cargo Transfers XI','Heavy Cargo Transfers XII','Heavy Cargo Transfers XIII','Heavy Cargo Transfers XIV','Heavy Cargo Transfers XV','Heavy Cargo Transfers XVI'],desc:'Raises efficient asteroid mining capacity up to 10,000.'},{id:'population',name:'Population Management',max:5,step:[800,400,600,600,600],levels:['Population Management I','Population Management II','Population Management III','Population Management IV','Population Management V'],desc:'Raises the available workforce pool from 50% to 100%. Department limits still apply.'}];
function researchCost(id,level){const t=TECH_TREE.find(x=>x.id===id);return t?.step[level-1]??TECHS[id]?.points??1000;}
function researchMax(id){return TECH_TREE.find(x=>x.id===id)?.max??4;}
function populationProductionBonus(){return Math.floor(Math.max(0,Math.min(populationCapacity(),state.population||0))/100);}
function researchRate(){const labs=state.buildings.researchLab||0;const total=Object.values(state.buildings).reduce((a,b)=>a+b,0)||1;const labBonus=Math.min(.20,(labs/total));return Math.round((12+labs*24)*(workforceRate('research')/20)*(1+labBonus+governmentEconomyBonus('research')/100)*(state.config?.researchMultiplier||1))+populationProductionBonus();}
function constructionRate(){return Math.max(1,Math.round((workforceRate('construction')/20)*100*(1+governmentEconomyBonus('construction')/100)))+populationProductionBonus();}
const GOVERNMENTS={None:{production:0,cost:0},Corporatism:{production:0,cost:0},Democracy:{production:0,cost:8},Nationalism:{production:-10,cost:0},Socialism:{production:20,cost:0},Totalitarianism:{production:-10,cost:6},Anarchy:{production:-20,cost:0}};
function currentGovernmentName(){return state.governmentPending?(state.tick<state.governmentRevolutionUntil?'Anarchy':state.governmentPending):(state.government||'None');}
function governmentProduction(){return GOVERNMENTS[currentGovernmentName()]||GOVERNMENTS.None;}
function productionBonusBreakdown(){const population=Math.max(0,Math.min(100,workforceRate('shipwright'))),government=governmentProduction().production;return {population,government,multiplier:Math.max(0,1+(population+government)/100)};}
function productionRate(order=state.production){const factories=factoryThroughput(order),bonus=productionBonusBreakdown();return Math.max(1,Math.floor((80+factories*35)*bonus.multiplier*(state.config?.productionMultiplier||1)));}
function shipProductionCost(id){const discount=governmentProduction().cost;return Object.fromEntries(Object.entries(SHIPS[id].cost).map(([r,n])=>[r,Math.ceil(n*(1-discount/100))]));}
function productionBonusHTML(){const bonus=productionBonusBreakdown();return '<div class="production-bonus-note"><b>LIVE ORDER BONUSES</b><span>Population / shipwrights: +'+bonus.population+'%</span><span>Government: '+esc(currentGovernmentName())+' · '+(bonus.government>=0?'+':'')+bonus.government+'%</span><span>Combined output: '+Math.round(bonus.multiplier*100)+'% of base</span><small>Changes apply immediately to running orders. Factory allocation uses Apply to order #. Paid resource costs stay fixed.</small><a href="/manual.html#governments">Government lookup →</a></div>';}
function governmentHTML(){return '<section class="panel" style="margin-top:14px"><div class="ph"><div class="pt">GOVERNMENT · ECONOMY & PRODUCTION</div><span class="meta">'+esc(currentGovernmentName())+'</span></div><div class="controls"><div class="field"><label for="governmentSelect">Planet government</label><select id="governmentSelect" '+(state.governmentPending&&state.tick<state.governmentRevolutionUntil?'disabled':'')+'>'+Object.keys(GOVERNMENTS).filter(n=>n!=='Anarchy').map(n=>'<option '+(n===(state.governmentPending||state.government||'None')?'selected':'')+'>'+n+'</option>').join('')+'</select></div><button class="btn primary" data-save-government>APPLY GOVERNMENT</button><a class="btn" href="/manual.html#governments">GOVERNMENT LOOKUP</a></div>'+productionBonusHTML()+'<div class="controls"><span class="tag">MINING '+governmentEconomyBonus('mining')+'%</span><span class="tag">RESEARCH '+governmentEconomyBonus('research')+'%</span><span class="tag">CONSTRUCTION '+governmentEconomyBonus('construction')+'%</span></div><div class="note" style="margin:12px">'+(state.governmentPending&&state.tick<state.governmentRevolutionUntil?'Revolution: '+(state.governmentRevolutionUntil-state.tick)+' ticks remaining. Production uses the Anarchy penalty until '+esc(state.governmentPending)+' takes over.':'First government formation is free within the first 168 ticks. Changing government starts a 72-tick revolution.')+'</div></section>';}
function saveGovernment(){const name=document.getElementById('governmentSelect')?.value;if(!GOVERNMENTS[name]||name==='Anarchy')return;if(state.governmentPending&&state.tick<state.governmentRevolutionUntil)return notify('Wait for the current revolution to finish.',true);const current=currentGovernmentName();if(name===current)return notify('That government is already active.');if(name==='None')return notify('Select one of the five government types.',true);if(current==='None'&&state.tick<=168){state.government=name;state.governmentPending=null;state.governmentRevolutionUntil=0;}else{if(!confirm('Changing government starts 72 ticks of revolution with the Anarchy production penalty. Continue?'))return;state.governmentPending=name;state.governmentRevolutionUntil=state.tick+72;}const home=state.galaxy.find(p=>p.player);if(home){home.government=state.government||'None';home.governmentPending=state.governmentPending||null;home.governmentRevolutionUntil=state.governmentRevolutionUntil||0;}addNews('Government selection: '+name+'. Production bonuses now follow '+currentGovernmentName()+'.','info');update();notify('Government settings applied.');}

function costAsteroids(start,qty){let n=0;for(let i=0;i<qty;i++){const x=start+i;n+=Math.ceil(2.5*(x*x+3*x+2));}return n;}
function buildingCost(id){const d=BUILDINGS[id],count=(state.buildings[id]||0)+state.constructionQueue.filter(x=>x.id===id).length+(state.construction?.id===id?1:0);const f=((count+1)**1.25/1000+1)*(count+1);return Object.fromEntries(Object.entries(d.cost).map(([k,v])=>[k,Math.ceil(v*f)]));}
function canAfford(c){return Object.entries(c).every(([k,v])=>(state.resources[k]||0)>=v);}function pay(c){Object.entries(c).forEach(([k,v])=>state.resources[k]-=v);}
function shipUnlocked(id){const d=SHIPS[id];if(!d)return false;const hull={Fighter:1,Corvette:1,Frigate:2,Destroyer:2,Cruiser:3,Battleship:3}[d.class]||1;return (state.research.fighter||0)>=hull&&(!d.pod||(state.research.cargo||0)>=1);}
function shipCostValue(id){const c=SHIPS[id]?.cost||{};return (c.metal||0)+(c.crystal||0)+(c.eonium||0);}
function playerValue(){const shipVal=Object.values(state.fleets).reduce((sum,f)=>sum+Object.entries(f).reduce((z,[id,count])=>z+shipCostValue(id)*count,0),0)+state.missions.reduce((sum,m)=>sum+Object.entries(m.ships).reduce((z,[id,count])=>z+shipCostValue(id)*count,0),0);const resVal=Object.values(state.resources).reduce((a,b)=>a+b,0)/150;const buildings=Object.values(state.buildings).reduce((a,b)=>a+b,0);return Math.round((shipVal+(state.shipSales||[]).reduce((a,o)=>a+shipCostValue(o.ship)*o.qty,0))/100+resVal+buildings*200+totalRoids(state.roids)*200);}
function playerScore(){return playerValue()+state.xp;}
function npcValue(p){if(p.directoryReadOnly&&Number.isFinite(p.publicValue))return p.publicValue;const fleetVal=Object.entries(p.ships||{}).reduce((z,[id,count])=>z+(SHIPS[id]?.cost.metal+SHIPS[id]?.cost.crystal+SHIPS[id]?.cost.eonium||0)*count/100,0);return Math.round(fleetVal+Object.values(p.resources||{}).reduce((a,b)=>a+b,0)/150+(p.structures||0)*200+totalRoids(p.roids)*200);}
function planetScore(p){if(p.directoryReadOnly&&Number.isFinite(p.publicScore))return p.publicScore;return p.player?playerScore():npcValue(p)+(p.xp||0);}
function resourceHTML(){const inc=income();return Object.entries(RES).map(([id,r])=>`<div class="res"><div class="res-head"><span>${r.label}</span><span class="res-icon">${r.icon}</span></div><div class="res-val">${nfmt(state.resources[id])}</div><div class="res-rate">${signed(inc[id])} / TICK</div></div>`).join('');}
function activeOrderHTML(){const parts=[];if(state.construction)parts.push(`<div class="summary-line"><div><b>${BUILDINGS[state.construction.id].name}</b><small>CONSTRUCTION · ${Math.max(1,Math.ceil(state.construction.remaining/constructionRate()))} TICKS</small></div><span class="tag">${Math.round(100-state.construction.remaining/state.construction.total*100)}%</span></div>`);if(state.researchActive)parts.push(`<div class="summary-line"><div><b>${TECH_TREE.find(t=>t.id===state.researchActive)?.levels[(state.research[state.researchActive]||0)]||TECHS[state.researchActive].name}</b><small>RESEARCH · ${(state.researchProgress[state.researchActive]||0)} / ${researchCost(state.researchActive,(state.research[state.researchActive]||0)+1)}</small></div><span class="tag blue">${Math.floor((state.researchProgress[state.researchActive]||0)/researchCost(state.researchActive,(state.research[state.researchActive]||0)+1)*100)}%</span></div>`);if(state.production)parts.push(`<div class="summary-line"><div><b>${esc(productionOrderLabel(state.production))}</b><small>SHIP ORDER · ${Math.max(1,Math.ceil(state.production.remaining/productionRate()))} TICKS</small></div><span class="tag gold">BUILDING</span></div>`);if(!parts.length)parts.push('<div class="empty">No active projects. Start construction, research, or production.</div>');return parts.join('');}
