function leaderboardHTML(){const rows=state.galaxy.map(p=>({name:p.name,alliance:p.alliance,score:planetScore(p),you:!!p.player})).sort((a,b)=>b.score-a.score);return rows.map((r,i)=>`<div class="summary-line"><div><b>${i+1}. ${r.name}${r.you?' · YOU':''}</b><small>${r.alliance}</small></div><b>${nfmt(r.score)}</b></div>`).join('');}
function populationHTML(){const labels={mining:['Miners','Increase resource yield from core, asteroids, and refineries.'],research:['Scientists','Increase research points generated each tick.'],construction:['Builders','Reduce construction time.'],shipwright:['Shipwrights','Increase ship production speed.'],security:['Security','Improve planetary alert and defensive readiness.']};return Object.entries(state.workforce).map(([k,v])=>`<div class="pop-row"><div><strong>${labels[k][0]}</strong><small>${labels[k][1]}</small></div><input type="range" min="0" max="${WORKFORCE_LIMITS[k]}" value="${v}" data-workforce="${k}"><output id="out-${k}">${v}% <small>Max ${WORKFORCE_LIMITS[k]}%</small></output></div>`).join('');}
function workforceEffectsHTML(){return `<div class="summary-line"><div><b>Mining bonus</b><small>Mining allocation plus Finance Centres</small></div><b>+${Math.round((workforceRate('mining')+(state.buildings.financeCenter||0)*.5)*10)/10}%</b></div><div class="summary-line"><div><b>Research</b><small>Lab output at current scientist allocation · +${populationProductionBonus()} population RP</small></div><b>${researchRate()} / tick</b></div><div class="summary-line"><div><b>Construction</b><small>Project work each tick · +${populationProductionBonus()} population CU</small></div><b>${constructionRate()} / tick</b></div><div class="summary-line"><div><b>Ship production</b><small>Shipwright workforce plus assigned factories</small></div><b>${productionRate()} / tick</b></div><div class="summary-line"><div><b>Security readiness</b><small>Security workforce assignment</small></div><b>${workforceRate('security')}%</b></div>`;}
function gameTickMs(){return Math.max(60000,Number(state.config?.tickHours||1)*HOUR);}
function countdown(){const ms=Math.max(0,state.nextTickAt-Date.now());const h=String(Math.floor(ms/3600000)).padStart(2,'0'),m=String(Math.floor(ms%3600000/60000)).padStart(2,'0'),s=String(Math.floor(ms%60000/1000)).padStart(2,'0');return `${h}:${m}:${s}`;}
function startConstruction(id){if(state.construction&&state.constructionQueue.length>=1)return notify('One active project and one queued project are allowed.',true);const cost=buildingCost(id);if(!canAfford(cost))return notify('Not enough resources for that facility.',true);const nTotal=Object.values(state.buildings).reduce((a,b)=>a+b,0)+state.constructionQueue.length+(state.construction?1:0);if(nTotal>=buildingLimit())return notify('Construction cap reached. Research Construction Systems to raise it.',true);pay(cost);const d=BUILDINGS[id],ticks=Math.max(1,Math.ceil(d.ticks*100/workforceRate('construction')));const o={id,total:d.cu,remaining:d.cu,cost,ticks};if(!state.construction)state.construction=o;else state.constructionQueue.push(o);addNews(`${d.name} construction order placed. Resources committed.`);update();notify(`${d.name} added to construction.`);refreshPageAfterOrder();}
function cancelBuild(which){let o;if(which==='active'){o=state.construction;state.construction=null;}else{o=state.constructionQueue.pop();}if(!o)return;for(const [k,v] of Object.entries(o.cost))state.resources[k]+=Math.floor(v*.75);if(!state.construction&&state.constructionQueue.length)state.construction=state.constructionQueue.shift();addNews(`${BUILDINGS[o.id].name} cancelled. 75% of its cost was refunded.`,'warn');update();}
function startResearch(id){if(state.researchActive===id)return;if(!TECH_TREE.some(t=>t.id===id))return;if((state.research[id]||0)>=researchMax(id))return notify('This research branch is at its maximum level.',true);state.researchActive=id;if(state.researchBank){state.researchProgress[id]=(state.researchProgress[id]||0)+state.researchBank;state.researchBank=0;if(state.researchProgress[id]>=researchCost(id,(state.research[id]||0)+1))completeResearch();}addNews(`Research started: ${TECH_TREE.find(t=>t.id===id)?.name||id}. Existing progress is retained.`);update();refreshPageAfterOrder();}
function cancelResearch(){if(!state.researchActive)return;const d=TECH_TREE.find(t=>t.id===state.researchActive);addNews(`${d?.name||state.researchActive} paused. ${state.researchProgress[state.researchActive]||0} points retained.`);state.researchActive=null;update();}
function orderShips(id){const d=SHIPS[id];if(!shipUnlocked(id))return notify('Complete the required hull research first.',true);if(!(state.buildings[d.factory]||0))return notify('Build the required factory first.',true);if(state.production&&state.productionQueue.length>=1)return notify('One active and one queued ship order are allowed.',true);const unitCost=shipProductionCost(id);const requested=Math.max(1,Math.min(20000,Math.floor(Number(document.getElementById('qty-'+id).value)||1)));const affordable=Math.min(requested,...Object.entries(unitCost).filter(([,v])=>v>0).map(([k,v])=>Math.floor((state.resources[k]||0)/v)));if(affordable<1)return notify('Not enough resources to order one ship.',true);const qty=affordable,cost=Object.fromEntries(Object.entries(unitCost).map(([k,v])=>[k,v*qty]));pay(cost);const value=Object.values(cost).reduce((n,v)=>n+v,0),o={id,qty,total:value,remaining:value,cost,orderNumber:state.nextShipOrderNumber=(state.nextShipOrderNumber||0)+1,factoryAssignments:copy(state.factoryAssignments||{}),destinationFleet:selectedProductionFleet(id)};if(!state.production)state.production=o;else state.productionQueue.push(o);addNews(`${qty} ${d.name}${qty===1?'':'s'} ordered${qty<requested?` (${requested-qty} unaffordable)` : ''} for production.`);update();notify(qty<requested?`Ordered ${qty}; resource limits reduced the request from ${requested}.`:'Ship order placed.');refreshPageAfterOrder();}
function fleetTransferOptions(){return '<optgroup label="Ship groups">'+[['all','All Ships'],['Fighter','Fighters'],['Corvette','Corvettes'],['Frigate','Frigates'],['Destroyer','Destroyers'],['Cruiser','Cruisers'],['Battleship','Battleships']].map(([id,label])=>'<option value="group:'+id+'">'+label+'</option>').join('')+'</optgroup><optgroup label="Individual ships">'+Object.entries(SHIPS).filter(([id,d])=>d.race===state.race||Object.values(state.fleets).some(f=>(f[id]||0)>0)).map(([id,d])=>'<option value="'+id+'">'+esc(d.name)+'</option>').join('')+'</optgroup>';}
function transferShips(){const id=document.getElementById('transferShip').value,from=document.getElementById('transferFrom').value,to=document.getElementById('transferTo').value,qty=Math.max(1,Math.trunc(Number(document.getElementById('transferAmount').value)||1));if(from===to)return notify('Choose two different fleets.',true);if(from==='f4'&&!mayAlliance('launchBay'))return notify('Only alliance launch controllers can withdraw ships from the Alliance Fleet.',true);if(!state.fleets[from]||!state.fleets[to])return notify('Choose valid fleets.',true);if(state.missions.some(m=>m.fleet===from||m.fleet===to))return notify('Ships can only move between docked fleets. Recall and wait for a deployed fleet to return.',true);const group=id.startsWith('group:'),className=id.slice(6),ids=group?Object.keys(SHIPS).filter(key=>(className==='all'||SHIPS[key].class===className)&&(state.fleets[from][key]||0)>0):[id];if(!ids.length||(!group&&(state.fleets[from][id]||0)<qty))return notify('That fleet does not have enough ships.',true);let moved=0;for(const key of ids){if(!SHIPS[key])continue;const amount=id==='group:all'?(state.fleets[from][key]||0):group?Math.min(qty,state.fleets[from][key]||0):qty;state.fleets[from][key]-=amount;state.fleets[to][key]=(state.fleets[to][key]||0)+amount;moved+=amount;}if(!moved)return notify('No matching ships in this fleet.',true);addNews(moved+' ships transferred from '+fleetLabel(from)+' to '+fleetLabel(to)+'.');update();notify(moved+' ships transferred.'+(id==='group:all'?' All ships moved from the selected source fleet.':' Class amounts apply per matching ship type.'));}

function launchMission(allianceLaunch=false){const selectedFleet=document.getElementById('missionFleet').value,fid=/^[1-3]$/.test(selectedFleet)?'f'+selectedFleet:selectedFleet,targetId=document.getElementById('missionTarget').value,mission=document.getElementById('missionType').value,p=state.galaxy.find(x=>x.id===targetId)||state.structurePlanets.find(x=>x.id===targetId),fleet=state.fleets[fid];if(!p)return notify('Choose a valid mission target.',true);if(fid==='f4'&&(!allianceLaunch||(allianceLaunch!=='central'&&!mayAlliance('launchBay'))))return notify('Alliance Fleet launches only from Alliance Launch Bay with defence permission.',true);if(state.missions.some(m=>m.fleet===fid))return notify('That fleet already has an active or scheduled mission.',true);if(!fleet||!['f1','f2','f3','f4'].includes(fid))return notify('Choose Fleet 1, 2 or 3 before launch.',true);const total=totalShips(fleet);if(!total)return notify('Move ships into this fleet before launch.',true);if(mission==='Attack'&&!p.structurePlanet&&state.tick<=(state.config?.protectionTicks??24))return notify(`Planet protection is active for ${(state.config?.protectionTicks??24)+1-state.tick} more ticks.`,true);if(mission==='Attack'&&p.structurePlanet&&!state.alliance.wars.includes(p.alliance))return notify('Structure planets cannot be attacked unless your alliance is at war with their owner.',true);if(mission==='Attack'&&!p.structurePlanet&&p.alliance===state.alliance.name&&!state.alliance.wars.includes(p.alliance))return notify('Your alliance is not at war with this planet.',true);const composition=copy(fleet);for(const k of Object.keys(fleet))fleet[k]=0;const travelLevel=state.research.travel||0,hubBonus=isAllianceMember('A. Commander')&&hasAllianceEffect('transwarpHub')?1:0;const eta=fleetTravelTime(composition,p,mission);const delay=Number(document.getElementById('missionDelay')?.value||0);if(!Number.isInteger(delay)||delay<0||delay>12){for(const k of Object.keys(composition))fleet[k]=composition[k];return notify('Launch delay must be 0–12 ticks.',true);}state.missions.push({id:Math.random().toString(36).slice(2),fleet:fid,name:fleetLabel(fid),targetId,targetName:p.name,mission,eta,travelEta:eta,launchTick:state.tick+delay,phase:delay?'scheduled':'outbound',ships:composition});queueMovementReport(state.missions[state.missions.length-1],'launch');addNews(`${fleetLabel(fid)} launched on a ${mission.toLowerCase()} mission to ${p.name}. ETA ${eta} ticks.`,'warn');update();notify(`${fleetLabel(fid)} launched. ETA ${eta} ticks.`);}
function recallMission(id){const m=state.missions.find(x=>x.id===id);if(!m)return;if(m.fleet==='f4'&&!mayAlliance('launchBay'))return notify('Alliance defence permission is required to recall this fleet.',true);if(m.phase==='scheduled'){for(const key of Object.keys(m.ships))state.fleets[m.fleet][key]=(state.fleets[m.fleet][key]||0)+m.ships[key];state.missions=state.missions.filter(x=>x.id!==id);addNews(m.name+' scheduled launch cancelled.','info');update();return;}if(m.phase==='outbound'){m.phase='returning';m.eta=1;addNews(`${m.name} recalled before reaching ${m.targetName}.`,'warn');}else notify('Fleet is already returning.',true);update();}
function cloneFleet(f){const c={};for(const id of Object.keys(SHIPS))c[id]=f[id]||0;return c;}
function fireInitiative(shooters,target,damageBonus=1){const damage={};for(const [sid,count] of Object.entries(shooters)){if(!count)continue;const d=SHIPS[sid];let cls=d.target.find(c=>Object.entries(target).some(([tid,n])=>n>0&&SHIPS[tid].class===c));if(!cls)continue;const ids=Object.keys(target).filter(tid=>target[tid]>0&&SHIPS[tid].class===cls);if(!ids.length)continue;const total=ids.reduce((a,id)=>a+target[id],0);let hit=d.damage*(d.guns||1)*count*damageBonus;for(const tid of ids){const share=hit*(target[tid]/total);damage[tid]=(damage[tid]||0)+share;}}return damage;}
function applyDamage(target,damage,armourBonus=1){let lost=0;for(const [id,dmg] of Object.entries(damage)){const dead=Math.min(target[id]||0,Math.floor(dmg/(SHIPS[id].armour*armourBonus)));if(dead){target[id]-=dead;lost+=dead;}}return lost;}
function resolveCombat(attacking,defending,attackerAlliance=state.alliance.name,defenderAlliance='Unaffiliated',population=0,biodomes=0,biodomeDamage=0,populationBase=1000){const arrivedA=cloneFleet(attacking),arrivedD=cloneFleet(defending),a=cloneFleet(attacking),d=cloneFleet(defending);let aLost=0,dLost=0;const attackerBonus=attackerAlliance===state.alliance.name&&hasAllianceEffect('ancientWeapons')?1.02:1,defenderBonus=defenderAlliance===state.alliance.name&&hasAllianceEffect('ancientWeapons')?1.02:1;const initiatives=[...new Set(Object.values(SHIPS).map(x=>x.initiative))].sort((x,y)=>x-y);for(const init of initiatives){const as={},ds={};for(const [id,n] of Object.entries(a))if(n&&SHIPS[id].initiative===init)as[id]=n;for(const [id,n] of Object.entries(d))if(n&&SHIPS[id].initiative===init)ds[id]=n;const ad=fireInitiative(as,d,attackerBonus),dd=fireInitiative(ds,a,defenderBonus);aLost+=applyDamage(a,dd,attackerBonus);dLost+=applyDamage(d,ad,defenderBonus);}const populationBefore=Math.max(0,Math.floor(Number(population)||0)),populationDamagePercent=Object.entries(a).reduce((sum,[id,n])=>sum+(['Cruiser','Battleship'].includes(SHIPS[id].class)?n*Math.max(0,Math.min(100,Number(SHIPS[id].populationDamage??0.1))):0),0),populationDamage=Math.floor(populationBefore*Math.min(100,populationDamagePercent)/100),habitat=resolveBiodomeDamage(a,biodomes,biodomeDamage,populationBefore,populationBase),populationLost=Math.min(populationBefore,populationDamage+habitat.populationLost);return {attacker:a,defender:d,aLost,dLost,arrivedA,arrivedD,populationBefore,populationLost,populationDamagePercent:Math.min(100,populationDamagePercent),populationAfter:populationBefore-populationLost,habitat};}
function resolveAttack(m){const structure=state.structurePlanets.find(x=>x.id===m.targetId);if(m.targetId?.startsWith('structure-')&&!structure){m.phase='returning';m.eta=1;addNews(`The structure target for ${m.name} no longer exists; fleet returning.`,'warn');return;}if(structure){if(!state.alliance.wars.includes(structure.alliance)){m.phase='returning';m.eta=1;addNews(`Attack on ${structure.name} aborted: your alliance is at peace with ${structure.alliance}.`,'warn');return;}const assault=resolveCombat(m.ships,structure.ships||{},state.alliance.name,structure.alliance);recordBattleNews(m,structure,assault);m.ships=assault.attacker;if(totalShips(m.ships)>0){state.structurePlanets=state.structurePlanets.filter(x=>x.id!==structure.id);state.alliance.structures.active=state.alliance.structures.active.filter(x=>x.id!==structure.id);addNews(`${structure.name} was destroyed by an alliance attack.`,'warn');}else addNews(`${structure.name} repelled the attack.`,'warn');m.phase='returning';m.eta=1;return;}const p=state.galaxy.find(x=>x.id===m.targetId);if(!p)return;const fight=resolveCombat(m.ships,p.ships,state.alliance.name,p.alliance||'Unaffiliated',p.population??p.publicPopulation??planetBasePopulation(p),p.buildings?.biodome||0,p.biodomeDamage||0,planetBasePopulation(p));if(p.buildings)p.buildings.biodome=fight.habitat.after;p.biodomeDamage=fight.habitat.damageAfter;p.population=fight.populationAfter;p.publicPopulation=p.population;recordBattleNews(m,p,fight);m.ships=fight.attacker;p.ships=fight.defender;const pods=Object.entries(m.ships).reduce((a,[id,n])=>a+(SHIPS[id].pod?n:0),0);let stolen=0;if(pods){const war=allianceWarBonus(p.alliance),limit=Math.floor(totalRoids(p.roids)*Math.max(0,.25+war.capture/100));stolen=Math.min(limit,Math.floor(pods*6*Math.max(0,1+war.capture/100)));let left=stolen;for(const k of ['metal','crystal','eonium']){const share=Math.min(p.roids[k],Math.floor(stolen*(p.roids[k]/Math.max(1,totalRoids(p.roids)))));const take=k==='eonium'?left:share;p.roids[k]-=take;state.roids[k]+=take;left-=take;}if(left>0){for(const k of ['metal','crystal','eonium']){const take=Math.min(p.roids[k],left);p.roids[k]-=take;state.roids[k]+=take;left-=take;if(!left)break;}}stolen-=left;}
queueMovementReport(m,'result',{captured:stolen,attackerLost:fight.aLost,defenderLost:fight.dLost});const win=totalShips(m.ships)>0&&fight.dLost>0;if(win){const earned=Math.max(30,Math.round(stolen*5*(1+allianceWarBonus(p.alliance).xp/100)+fight.dLost*4));state.xp+=earned;addNews(`${m.name} won the battle at ${p.name}: ${fight.dLost} enemy ships lost, ${stolen} asteroids captured, +${earned} XP.`,'good');}else{addNews(`${m.name} fought at ${p.name}: ${fight.aLost} ships lost, ${fight.dLost} enemy ships lost, ${stolen} asteroids captured.`,'warn');}m.phase='returning';m.eta=1;}
function arriveMission(m){if(m.mission==='Attack'){resolveAttack(m);return;}if(m.mission==='Defence'){if(m.callId){const call=state.alliance.calls.find(c=>c.id===m.callId);if(call){state.alliance.calls=state.alliance.calls.filter(c=>c.id!==call.id);allianceLog(`${m.name} arrived and secured ${call.planet}; the defence call was resolved.`);addNews(`${m.name} reinforced ${call.planet}. The defence call is resolved; fleet returning home.`,'good');}else addNews(`${m.name} arrived at ${m.targetName}; no active defence call remained.`,'info');}else addNews(`${m.name} arrived to defend ${m.targetName}. No hostile fleet was present; returning home.`,'info');}m.phase='returning';m.eta=1;}
function completeResearch(){const id=state.researchActive,req=researchCost(id,(state.research[id]||0)+1),overflow=Math.max(0,(state.researchProgress[id]||0)-req);state.research[id]=(state.research[id]||0)+1;state.researchProgress[id]=0;state.researchActive=null;state.researchBank=(state.researchBank||0)+overflow;addNews(`Research complete: ${(TECH_TREE.find(t=>t.id===id)?.levels[(state.research[id]||1)-1]||TECHS[id].name)} advanced to level ${state.research[id]}. ${overflow?`${overflow} surplus RP banked.`:''}`,'good');}
function tickOnce(source='practice'){state.tick++;expireAllianceWars();state.lastTickAt=Date.now();settleShipSales();tickCovert();state.waves.scans=(state.waves.scans||[]).filter(sc=>state.tick-(sc.tick||state.tick)<=336);processAllianceStructures();const gross=grossIncome(),got=income();for(const k of Object.keys(got)){state.resources[k]+=got[k];state.alliance.fund[k]=(state.alliance.fund[k]||0)+(gross[k]-got[k]);}growColonyPopulation(state);if(typeof processPopulationTaxTick==='function'&&!state.centralPlayerId)processPopulationTaxTick();if(state.researchActive){const id=state.researchActive;state.researchProgress[id]=(state.researchProgress[id]||0)+researchRate();if(state.researchProgress[id]>=researchCost(id,(state.research[id]||0)+1))completeResearch();}
if(state.construction){state.construction.remaining-=constructionRate();if(state.construction.remaining<=0){const id=state.construction.id;state.buildings[id]=(state.buildings[id]||0)+1;addNews(`${BUILDINGS[id].name} completed and is operational.`,'good');state.construction=state.constructionQueue.shift()||null;}}
if(state.production){state.production.remaining-=productionRate();if(state.production.remaining<=0){const o=state.production;completeProductionOrder(o);state.production=state.productionQueue.shift()||null;}}
for(const m of [...state.missions]){if(m.phase==='scheduled'){if(state.tick<m.launchTick)continue;m.phase='outbound';addNews(m.name+' scheduled launch commenced.','info');}if(m.phase==='outbound'){m.eta--;if(m.mission==='Fake Defence'&&m.eta<=1){m.phase='returning';m.eta=Math.max(1,(m.travelEta||2)-1);addNews(m.name+' fake defence recalled automatically before arrival.','info');}else if(m.eta<=0)arriveMission(m);}else{m.eta--;if(m.eta<=0){for(const id of Object.keys(SHIPS))state.fleets[m.fleet][id]=(state.fleets[m.fleet][id]||0)+(m.ships[id]||0);addNews(`${m.name} returned to Vesper-3.`,'good');state.missions=state.missions.filter(x=>x.id!==m.id);}}}
for(const p of state.galaxy){if(p.player)continue;for(const k of Object.keys(p.resources)){const grossNpc=Math.round((1000+(p.roids?.[k]||0)*250)*1.05*allianceIncomeMultiplier(p.ruler)),taxed=p.alliance===state.alliance.name?Math.floor(grossNpc*Math.max(0,Math.min(5,Number(state.alliance.tax)||0))/100):0;p.resources[k]+=grossNpc-taxed;if(p.alliance===state.alliance.name)state.alliance.fund[k]=(state.alliance.fund[k]||0)+taxed;}if(state.tick%5===0)p.xp+=4;}
if(state.tick===(state.config?.protectionTicks??24)+1)addNews('Planetary protection has expired. Attacks can now be launched against open planets.','warn');for(const d of [...(state.alliance.pendingDonations||[])])if(d.tick<=state.tick){state.alliance.fund[d.resource]+=d.amount;state.alliance.pendingDonations=state.alliance.pendingDonations.filter(x=>x!==d);addNews(`${nfmt(d.amount)} ${RES[d.resource].label} donation cleared into alliance fund.`,'good');}for(const c of state.alliance.calls||[])c.eta=Math.max(0,c.eta-1),c.age=(c.age||0)+1;if(state.tick%200===0)state.politics.exileCount=0;if(state.tick>=state.roundLength)addNews(`Round ${String(state.tick).padStart(3,'0')} complete. Final standings are now locked.`,'good');if(source==='practice')state.nextTickAt=Date.now()+gameTickMs();save();update();}
function simulateTick(){if(state.tick>=state.roundLength)return notify('The round is complete. Reset to start another practice round.',true);tickOnce('practice');notify(`Tick ${String(state.tick).padStart(3,'0')} resolved.`);}
function inspectPlanet(id){const p=state.galaxy.find(x=>x.id===id);if(!p)return;const protectedPlanet=state.tick<=(state.config?.protectionTicks??24);const canAttack=!p.player&&!protectedPlanet&&p.alliance!=='Vesper Pact';showModal(`<div class="modal-head"><h3>${p.name} · PLANET INTEL</h3><button class="x" data-close>×</button></div><div class="modal-body"><p>${p.ruler} · ${p.race} · ${p.alliance}</p><p>World type: ${esc(planetTypeFor(p).name)} · habitability ${planetTypeFor(p).habitability}% · growth modifier ${planetTypeFor(p).growthPercent>=0?'+':''}${planetTypeFor(p).growthPercent}%. Starting population ${nfmt(planetBasePopulation(p))}.</p><p>Coordinates ${displayCoords(p.coords)}; value ${nfmt(npcValue(p))}; score ${nfmt(planetScore(p))}; ${totalRoids(p.roids)} asteroids. Population ${nfmt(universePopulation(p))}; population bonus +${(universePopulation(p)*.001).toFixed(3)}% mining and +${Math.floor(universePopulation(p)/100)} CU/RP per tick. Fleet strength: ${totalShips(p.ships)} ships.</p><p>${protectedPlanet?'Protected until tick 25.':p.alliance==='Vesper Pact'?'Alliance member. Attack unavailable.':'Open target. An Attack mission requires an available fleet slot.'}</p></div><div class="modal-foot"><button class="btn" data-close>CLOSE</button>${canAttack?'<button class="btn primary" data-prepareattack="'+id+'">PREPARE ATTACK</button>':''}</div>`);}
function showModal(html){document.getElementById('modalContent').innerHTML=html;document.getElementById('modal').classList.add('open');}function closeModal(){document.getElementById('modal').classList.remove('open');}
function showGuide(){showModal(`<div class="modal-head"><h3>GALAXY OPERATIONS · FIELD GUIDE</h3><button class="x" data-close>×</button></div><div class="modal-body"><p><b>Fleet operations:</b> Personal fleet names, 0–12 tick prelaunch, Fake Defence recall and Ship Analysis are under Fleets. The permanent fourth Alliance Fleet is controlled through Alliance → Launch Bay. Officer readiness cards show reported idle ship types under Defence.</p><p><b>Production vendor:</b> Sell Base ships with 12-tick settlement and the displayed practice buyback rate. Cancelled sales return after a new 12-tick trip.</p><p><b>Portal:</b> Theme cycling, support tickets and preferences live under User Profile. The Rules page is linked from the footer.</p><p><a class="btn" href="/manual.html#launch-bay">UPDATED FULL MANUAL →</a></p><p><b>Ticks:</b> The practice round resolves automatically every hour. “Simulate tick” resolves one immediately for testing. A tick advances income, research, construction, ship production, and fleet travel.</p><p><b>Mining:</b> Your planet starts with core income of 1,000 metal, crystal, and eonium each tick. Each asteroid adds 250 of its resource. Asteroid initiation costs resources of the same type and becomes more expensive with each one.</p><p><b>Projects:</b> Construction runs one project plus one queued project. Research runs one technology branch at a time; switching preserves progress. Ships need the matching factory and hull research, and completed ships enter Base.</p><p><b>Population:</b> Allocate all five departments to total 100%. More miners increase income; scientists, builders, and shipwrights speed their own systems.</p><p><b>Fleets & combat:</b> Transfer Base ships into Fleet 1–3, then launch Attack, Defence, or Fake Defence missions. Fleets land after their ETA. Combat resolves by initiative; surviving podships can capture up to 25% of a defender’s asteroids.</p><p><b>Galaxy & score:</b> The local practice galaxy has seven simulated neighbors. Your score combines planet value and experience. Protection lasts through tick 24.</p><p>This is an original, single-browser practice simulation. It does not connect to the live Planetarion universe or other players.</p></div><div class="modal-foot"><button class="btn primary" data-close>UNDERSTOOD</button></div>`);}
function prepareAttack(id){closeModal();document.getElementById('missionTarget').value=id;document.getElementById('missionType').value='Attack';document.querySelector('[data-page="fleets"]').click();notify('Choose a fleet slot and launch when ready.');}
function updateCountdown(){processTickerAutoStart();refreshTickerStatusBox();if(window.isStaffWorkspace){refreshMilitaryClock();return;}refreshMilitaryClock();document.getElementById('countdown').textContent=countdown();if(!state.config.tickerStopped&&!state.config.tickerPaused&&Date.now()>=state.nextTickAt&&state.tick<state.roundLength){let loops=0;while(Date.now()>=state.nextTickAt&&loops<24&&state.tick<state.roundLength){tickOnce('clock');state.nextTickAt+=gameTickMs();loops++;}save();document.getElementById('countdown').textContent=countdown();}}

function esc(t){return String(t??'').replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));}
function allianceLog(msg){addNews('Alliance: '+msg,'info');state.news[0].category='ALLIANCE';state.alliance.log.unshift({tick:state.tick,msg});state.alliance.log=state.alliance.log.slice(0,30);}
function allianceShell(html){return html;}
function normalizeMemberRole(role){const r=String(role||'Member').toLowerCase().replace(/[^a-z]/g,'');return r==='highcommander'||r==='hc'?'HC':r==='commander'||r==='officer'?'Officer':r==='scanner'?'Scanner':r==='recruit'?'Recruit':'Member';}
function allianceMembersHTML(){const members=[...state.alliance.members].sort((a,b)=>['Owner','HC','Officer','Scanner','Member','Recruit'].indexOf(a.rank)-['Owner','HC','Officer','Scanner','Member','Recruit'].indexOf(b.rank));const counts=Object.fromEntries(['Recruit','Member','Scanner','Officer','HC','Owner'].map(r=>[r,members.filter(m=>m.rank===r).length]));const canManage=mayAlliance('roles'),ownerAuthority=currentAllianceRank()==='Owner';return `<div class="member-role-summary">${['Owner','HC','Officer','Scanner','Member','Recruit'].map(r=>`<div class="member-role-count"><span class="rank-badge rank-${r.toLowerCase()}">${r}</span><b>${counts[r]}</b></div>`).join('')}</div><section class="panel"><div class="ph"><div class="pt">MEMBER LIST · ${members.length} / 40</div><span class="meta">ROLE MANAGEMENT ${canManage?'· HIGH COMMAND':'· VIEW ONLY'}</span></div><div class="table-wrap"><table class="table member-table"><thead><tr><th>Member</th><th>Coordinates</th><th>Planet score</th><th>Role</th><th>Status</th>${canManage?'<th>Manage</th>':''}</tr></thead><tbody>${members.map(m=>{const isSelf=isOwnAllianceMember(m),score=isSelf?playerScore():planetScore(state.galaxy.find(p=>p.name===m.planet)||{});return `<tr><td><b>${esc(m.name)}</b><small>${esc(m.planet)}</small></td><td>${esc(m.coords||'—')}</td><td>${nfmt(score)}</td><td><span class="rank-badge rank-${m.rank.toLowerCase()}">${m.rank}</span></td><td><span class="tag ${m.online?'green':''}">${m.online?'ONLINE':'OFFLINE'}</span></td>${canManage?`<td><select class="member-role-select" data-member-role="${esc(m.id)}" aria-label="Role for ${esc(m.name)}" ${m.rank==='Owner'&&!ownerAuthority?'disabled':''}>${ALLIANCE_RANKS.map(rank=>'<option value="'+rank+'" '+(m.rank===rank?'selected':'')+' '+(rank==='Owner'&&!ownerAuthority?'disabled':'')+'>'+rank+'</option>').join('')}</select></td>`:''}</tr>`;}).join('')}</tbody></table></div><div class="note" style="margin:10px">Accepted applicants join as Recruits. Owners or authorised command ranks can promote or demote members, including assigning Scanner rank; the HC position stays with the current High Commander in this practice round.</div></section><section class="panel" style="margin-top:12px"><div class="ph"><div class="pt">RECRUITMENT · ${state.alliance.applicants.length} PENDING</div><span class="meta">APPLICATIONS ${state.alliance.applicationsOpen?'OPEN':'CLOSED'}</span></div>${state.alliance.applicants.length?state.alliance.applicants.map((a,i)=>`<div class="def-row"><div><strong>${esc(a.name)} · ${esc(a.planet)}</strong><small>${esc(displayCoords(a.coords||''))} · <span class="rank-badge rank-recruit">Recruit</span> · pending alliance application</small></div><div class="copy-actions"><button class="btn primary" data-alliance="accept" data-applicant="${esc(a.id||i)}" ${members.length>=40?'disabled':''}>ACCEPT AS RECRUIT</button><button class="btn warn" data-alliance="decline" data-applicant="${esc(a.id||i)}">DECLINE</button></div></div>`).join(''):'<div class="empty">No pending recruitment applications.</div>'}<div class="controls"><button class="btn" data-alliance="toggleapps">${state.alliance.applicationsOpen?'CLOSE RECRUITMENT':'OPEN RECRUITMENT'}</button><span class="meta">${members.length} / 40 MEMBERS</span></div><div class="note" style="margin:0 10px 10px">${esc(state.alliance.applicantMessage||'New applicants begin as Recruits. Promote them from the member list as they contribute.')}</div></section>`;}
const STRUCTURE_DEFS={transwarpHub:{name:'Transwarp Hub',share:.30,duration:12,durationUnit:'hours',cooldown:12,icon:'⤳',desc:'Reduces alliance travel time by 1 tick for 12 hours, then self-destructs.'},dysonSphere:{name:'Dyson Sphere',share:.10,duration:8,cooldown:12,icon:'☼',desc:'Raises alliance income by 2% for 8 ticks, then self-destructs.'},ancientWeapons:{name:'Ancient Weapons',share:.40,duration:4,cooldown:12,icon:'⚔',desc:'Raises alliance ship combat stats by 2% for 4 ticks, then self-destructs.'},voyagerIV:{name:'Voyager IV',share:.20,duration:0,cooldown:0,icon:'✦',desc:'Grants 5 Wave Amplifiers to every alliance member. Repeatable.'},solarFlares:{name:'Solar Flares',share:.20,duration:0,cooldown:0,icon:'☀',desc:'Grants 5 Wave Distorters to every alliance member. Repeatable.'}};
function isAllianceHC(){return ['Owner','HC'].includes(currentAllianceRank())&&isAllianceMember('A. Commander');}
function isAllianceMember(name){return name==='A. Commander'?state.alliance.members.some(isOwnAllianceMember):state.alliance.members.some(m=>m.name===name);}
function allianceHoursToTicks(hours){return Math.max(1,Math.ceil(hours/Math.max(.1,Number(state.config?.tickHours)||1)));}
function allianceAnarchyActive(){return (state.alliance.fortress.anarchyUntilTick||0)>0&&state.tick<=(state.alliance.fortress.anarchyUntilTick||0);}
function hasAllianceEffect(id){return state.alliance.structures.active.some(x=>x.type===id&&state.tick<x.expiresAt);}
function allianceIncomeMultiplier(name){if(!isAllianceMember(name))return 1;const fort=isStrongholdResident(name)?0.0025:0,dyson=hasAllianceEffect('dysonSphere')?0.02:0,anarchy=allianceAnarchyActive()?0.02:0;return 1+fort+dyson-anarchy;}
function allianceDailyTaxIncome(){const tax=Math.max(0,Math.min(5,Number(state.alliance.tax)||0))/100,daily={metal:0,crystal:0,eonium:0};if(!tax)return daily;const current=grossIncome();if(isAllianceMember('A. Commander')&&state.userSettings.allianceTaxEnabled)for(const k of Object.keys(RES))daily[k]+=Math.floor(current[k]*tax)*24;for(const m of state.alliance.members){if(isOwnAllianceMember(m))continue;const p=state.galaxy.find(x=>x.ruler===m.name||x.name===m.planet);if(!p)continue;for(const k of Object.keys(RES)){const gross=Math.round((1000+(p.roids?.[k]||0)*250)*1.05*allianceIncomeMultiplier(m.name));daily[k]+=Math.floor(gross*tax)*24;}}return daily;}
function structureCost(id){const d=STRUCTURE_DEFS[id],daily=allianceDailyTaxIncome();return Object.fromEntries(Object.keys(RES).map(k=>[k,d&&daily[k]>0?Math.ceil(daily[k]*d.share):0]));}
function availableStructureSlots(){const galaxy=state.alliance.fortress.strongholdGalaxy||'07:04',prefix=galaxy+':',occupied=new Set(state.structurePlanets.filter(x=>String(x.coords||'').startsWith(prefix)).map(x=>Number(x.slot)));return [11,12,13,14,15].filter(n=>!occupied.has(n));}
function allianceLogAction(message,type='info'){state.alliance.log.unshift({tick:state.tick,msg:message});state.alliance.log=state.alliance.log.slice(0,30);addNews(message,type);state.news[0].category='ALLIANCE';}
function distributeAllianceBuilding(key,count,strongholdOnly=false){for(const m of state.alliance.members){if(strongholdOnly&&!isStrongholdResident(m.name))continue;if(isOwnAllianceMember(m)){state.buildings[key]=(state.buildings[key]||0)+count;continue;}const p=state.galaxy.find(x=>x.ruler===m.name||x.name===m.planet);if(p)p[key==='waveAmplifier'?'waveAmplifiers':'waveDistorters']=(p[key==='waveAmplifier'?'waveAmplifiers':'waveDistorters']||0)+count;}}
function grantDailyDistorters(){const fort=state.alliance.fortress;if(!fort.strongholdGalaxy)return;fort.lastDistorterTick=fort.lastDistorterTick||state.tick;const interval=allianceHoursToTicks(24);while(state.tick-fort.lastDistorterTick>=interval){distributeAllianceBuilding('waveDistorter',1,true);fort.lastDistorterTick+=interval;allianceLogAction('Stronghold bonus: alliance members in the stronghold galaxy received 1 free Wave Distorter.','good');}}
function processAllianceStructures(){completeAllianceStructureBuilds();const active=state.alliance.structures.active;for(const x of [...active])if(state.tick>=x.expiresAt){state.alliance.structures.active=state.alliance.structures.active.filter(y=>y.id!==x.id);state.structurePlanets=state.structurePlanets.filter(y=>y.id!==x.id);allianceLogAction(`${STRUCTURE_DEFS[x.type].name} at structure slot ${x.slot} self-destructed.`,'warn');}if(allianceAnarchyActive()===false&&state.alliance.fortress.anarchyUntilTick&&!state.alliance.fortress.anarchyEnded){state.alliance.fortress.anarchyEnded=true;allianceLogAction('Anarchy ended. Alliance member income has returned to normal.','good');}grantDailyDistorters();}
function allianceHomeHTML(){if(typeof allianceEconomyOverviewHTML==='function')return allianceEconomyOverviewHTML();const score=state.alliance.members.reduce((n,m)=>n+(isOwnAllianceMember(m)?playerScore():((state.galaxy.find(p=>p.name===m.planet)?.xp||0)+npcValue(state.galaxy.find(p=>p.name===m.planet)||{}))),0);return `<div class="alliance-kpis"><div class="alliance-kpi"><small>MEMBERS</small><b>${state.alliance.members.length} / 40</b></div><div class="alliance-kpi"><small>ALLIANCE SCORE</small><b>${nfmt(score)}</b></div><div class="alliance-kpi"><small>FUND VALUE</small><b>${nfmt(totalRoids(state.alliance.fund))}</b></div><div class="alliance-kpi"><small>DEFENCE CALLS</small><b>${state.alliance.calls.length}</b></div></div><div class="alliance-grid"><section class="panel"><div class="ph"><div class="pt">COMMANDER'S MESSAGE</div><span class="meta">VISIBLE TO ALL MEMBERS</span></div><div class="compose"><textarea id="allianceMessage">${esc(state.alliance.message||'Vesper Pact stands together. Share scans and call defence early.')}</textarea><button class="btn primary" data-alliance="message">POST MESSAGE</button></div></section><section class="panel"><div class="ph"><div class="pt">ALLIANCE ACTIVITY</div><span class="meta">LATEST ACTIONS</span></div><div class="summary-list">${state.alliance.log.slice(0,4).map(l=>`<div class="summary-line"><span>${esc(l.msg)}</span><small>T${l.tick}</small></div>`).join('')||'<div class="empty">Alliance operations will appear here.</div>'}</div></section></div><div class="note">Alliance tools are simulated for this local practice round. High Command can manage membership, calls for defence, fund settings, and diplomacy.</div>`;}
function allianceDefenceHTML(){const allies=state.alliance.members.filter(m=>!isOwnAllianceMember(m));const calls=[...state.alliance.calls].sort((a,b)=>a.eta-b.eta);return `<div class="alliance-grid"><section class="panel"><div class="ph"><div class="pt">CALL FOR DEFENCE</div><span class="meta">ALERT ALL ALLIANCE MEMBERS</span></div><div class="controls"><div class="field"><label>Planet under threat</label><select id="callTarget">${allies.map(a=>`<option value="${a.planet}">${a.planet} · ${displayCoords(a.coords)}</option>`).join('')}</select></div><div class="field"><label>Hostile ETA</label><input id="callEta" type="number" min="1" max="24" value="3"></div><div class="field"><label>Attacker / notes</label><input id="callNotes" value="Hostile fleet spotted" style="width:190px"></div><button class="btn primary" data-alliance="call">SEND DEFENCE CALL</button></div></section><section class="panel"><div class="ph"><div class="pt">RESPONSE FLEET</div><span class="meta">DISPATCH FROM YOUR FLEET SLOTS</span></div><div class="controls"><div class="field"><label>Fleet</label><select id="defenceFleet"><option value="f1">Fleet 1</option><option value="f2">Fleet 2</option><option value="f3">Fleet 3</option></select></div><div class="field"><label>Call</label><select id="defenceCall">${calls.map(c=>`<option value="${c.id}">${c.planet} · ETA ${c.eta}</option>`).join('')||'<option value="">No open calls</option>'}</select></div><button class="btn" data-alliance="respond" ${calls.length?'':'disabled'}>DISPATCH DEFENCE</button></div></section></div><section class="panel"><div class="ph"><div class="pt">INCOMING THREATS · SORTED BY ETA</div><span class="meta">SCAN FRESHNESS · P / D / A / U</span></div>${calls.length?calls.map(c=>`<div class="def-row"><div><strong>${esc(c.planet)} <span class="meta">${esc(displayCoords(c.coords))}</span> · ETA ${c.eta}</strong><small>${esc(c.notes)} · ${c.attackerCount||'Unknown'} hostile ships · <span class="scan">P ${c.age<=1?'FRESH':'RECENT'}</span><span class="scan ${c.age>12?'stale':''}">D ${c.age<=1?'FRESH':'STALE'}</span><span class="scan ${c.age>12?'stale':''}">A ${c.age<=1?'FRESH':'STALE'}</span><span class="scan ${c.age>12?'stale':''}">U ${c.age<=1?'FRESH':'STALE'}</span></small></div><div class="copy-actions"><button class="btn" data-openbcalc="${c.id}">OPEN BCALC</button><button class="btn" data-alliance="dismiss" data-call="${c.id}">CLOSE CALL</button></div></div>`).join(''):'<div class="empty">No incoming calls. Threat reports will appear here grouped by arrival time.</div>'}</section><div class="note" style="margin-top:12px">Defence calls group incoming fleet reports by ETA and include scan freshness markers. Use the in-game calculator to model a response, then dispatch a fleet from this screen.</div>`;}
function shipInputs(side,f){return Object.entries(SHIPS).map(([id,d])=>`<label data-ship-class="${d.class}"><span>${d.icon||"◈"} ${esc(d.name)}<small>${esc(d.class)}</small></span><input type="number" min="0" max="999999" data-cship="${side}" data-ship="${id}" value="${f[id]||0}"></label>`).join('');}
function bcalcHTML(){const saved=window.bcalc||{a:normalizeFleet({raptor:40,warden:14,lance:6,bastion:0,pod:24,titan:0}),d:normalizeFleet({raptor:20,warden:8,lance:2,bastion:2,pod:12,titan:0})};const result=window.bcalcResult;return `<div class="note">WORLD · ${esc(planetTypeFor(state).name)} · Fleet travel ${planetTypeFor(state).travelEtaBonus||0} tick · Earth salvage preview ${planetTypeFor(state).salvageBonusPercent||0}% · Simulations never award resources.</div><div class="bcalc-legend">${["Fighter","Corvette","Frigate","Destroyer","Cruiser","Battleship"].map(c=>`<span data-ship-class="${c}">${c}</span>`).join("")}</div><div class="alliance-grid bcalc-panels"><section class="panel"><div class="ph"><div class="pt">PASTE REPORT · PARSE SHIP COUNTS</div><span class="meta">ACCEPTS “SHIP: 123” LINES</span></div><div class="compose"><label class="meta">ATTACKER REPORT</label><textarea class="parse-area" id="parseA" placeholder="Paste a fleet report here…"></textarea><label class="meta">DEFENDER REPORT</label><textarea class="parse-area" id="parseD" placeholder="Paste a planet or fleet scan here…"></textarea><div class="copy-actions"><button class="btn" data-parse="a">PARSE ATTACKER</button><button class="btn" data-parse="d">PARSE DEFENDER</button><button class="btn" data-copycalc="report">COPY INPUT REPORT</button></div></div></section><section class="panel"><div class="ph"><div class="pt">BATTLE REPORT</div><span class="meta">INITIATIVE RESOLUTION</span></div><div class="bcalc-side"><div class="field scanlink-import"><label for="scanLinkInput">Import a shared scan link</label><textarea id="scanLinkInput" class="parse-area" placeholder="Paste a Starfall scan link or ship report…"></textarea><div class="scanlink-actions"><select id="scanImportSide" aria-label="Import scan as"><option value="d">Import as defender</option><option value="a">Import as attacker</option></select><button class="btn" data-importscanlink>IMPORT TO CALCULATOR</button></div></div><div class="field"><label>Report title</label><input id="calcTitle" value="Vesper Reach engagement" style="width:100%"></div><div class="controls"><label class="field">Defender population<input id="calcPopulation" type="number" min="0" max="1000000000" value="${saved.population??1000}"></label><label class="field">Defender Biodomes<input id="calcBiodomes" type="number" min="0" value="${saved.biodomes??0}"></label><label class="field">Existing Biodome damage (HP / 1000)<input id="calcBiodomeDamage" type="number" min="0" max="999" value="${saved.biodomeDamage??0}"></label></div><button class="btn primary" data-calculate>CALCULATE BATTLE</button><div id="calcResult" class="calc-result">${result||'Enter ship counts, paste a report to parse, then calculate.'}</div><div class="copy-actions"><button class="btn" data-copycalc="attacker">COPY ATTACKER</button><button class="btn" data-copycalc="defender">COPY DEFENDER</button><button class="btn" data-copycalc="result">COPY RESULT</button></div></div></section></div>${bcalcSheetHTML(saved)}<div class="note" style="margin-top:12px">This in-game calculator uses Starfall's initiative and damage rules. Parsed or copied reports are local practice data; no live Planetarion battle link is required.</div>`;}
function allianceMemberGalaxies(){const galaxies=new Set();for(const member of state.alliance.members||[]){const match=String(member.coords||member.galaxy||'').match(/^\s*(\d{1,3})\s*:\s*(\d{1,3})(?::|$)/);if(match)galaxies.add(`${padCoord(Number(match[1]))}:${padCoord(Number(match[2]))}`);}return [...galaxies].sort((a,b)=>{const [ax,ay]=a.split(':').map(Number),[bx,by]=b.split(':').map(Number);return ax-bx||ay-by;});}
function allianceFortressHTML(){const f=state.alliance.fortress,memberGalaxies=allianceMemberGalaxies(),selectedGalaxy=memberGalaxies.includes(f.strongholdGalaxy)?f.strongholdGalaxy:'',changed=!!f.strongholdGalaxy,remaining=Math.max(0,(f.anarchyUntilTick||0)-state.tick+1),remainingHours=remaining*(Number(state.config?.tickHours)||1),editable=mayAlliance('fortress'),interval=allianceHoursToTicks(24),daily=changed?Math.max(0,interval-(state.tick-(f.lastDistorterTick||state.tick))):interval;return `<div class="alliance-grid"><section class="panel"><div class="ph"><div class="pt">ALLIANCE STRONGHOLD</div><span class="meta">${changed?`GALAXY ${esc(f.strongholdGalaxy)}`:'SET BEFORE ROUND TICKS BEGIN'}</span></div><div class="fortress-body"><p>Choose the galaxy that will host the alliance fortress. The current Alliance HC controls its location.</p><div class="controls"><div class="field"><label for="fortressGalaxy">Stronghold galaxy · member galaxies only</label><select id="fortressGalaxy" ${editable&&memberGalaxies.length?'':'disabled'}><option value="" disabled ${selectedGalaxy?'':'selected'}>${memberGalaxies.length?'Choose a member galaxy':'No galaxies contain alliance members'}</option>${memberGalaxies.map(g=>`<option value="${esc(g)}" ${g===selectedGalaxy?'selected':''}>${esc(g)}</option>`).join('')}</select></div><button class="btn primary" data-alliance="setFortress" ${editable&&memberGalaxies.length?'':'disabled'}>${changed?'SET / MOVE STRONGHOLD':'ESTABLISH STRONGHOLD'}</button></div>${!changed?'<div class="note">Choose the location before the first tick to avoid anarchy.</div>':''}${changed&&!selectedGalaxy?'<div class="note">The current stronghold galaxy has no alliance members. Select a galaxy that does before moving it.</div>':''}</div></section><section class="panel"><div class="ph"><div class="pt">FORTRESS BENEFITS</div><span class="meta">MEMBERS IN STRONGHOLD GALAXY</span></div><div class="summary-list"><div class="summary-line"><span>Passive resource income bonus</span><b>${changed?'0.25%':'INACTIVE'}</b></div><div class="summary-line"><span>Free Wave Distorter</span><b>${changed?`EVERY ${interval} TICKS · NEXT IN ${daily} TICKS · 24H CYCLE`:'INACTIVE'}</b></div><div class="summary-line"><span>Stronghold galaxy</span><b>${changed?esc(f.strongholdGalaxy):'NOT SET'}</b></div></div>${remaining?`<div class="note" style="margin:0 12px 12px;border-left-color:var(--red)"><b>ANARCHY MODE</b> · Alliance members receive 2% less income for ${remaining} more ticks after the stronghold move.</div>`:''}</section></div><div class="note">Moving the stronghold after tick 1 starts Anarchy Mode for 24 ticks. Changing it before the first tick is free. Every 24 hours, alliance members in the stronghold galaxy receive 1 free Wave Distorter. The passive 0.25% income bonus also applies only to those members.</div>`;}
function allianceStructuresHTML(){const a=state.alliance,active=a.structures.active,queue=a.structures.buildQueue||[],slots=availableStructureSlots(),daily=allianceDailyTaxIncome(),other=state.structurePlanets.filter(x=>x.alliance!==a.name),hc=mayAlliance('structures');return `<div class="page-illustration alliance-structures-illustration" role="img" aria-label="Alliance megastructures orbiting a planet"><span><small>ALLIANCE MEGASTRUCTURES</small><b>Build beyond the frontier</b></span></div><section class="panel"><div class="ph"><div class="pt">STRUCTURE PLANETS · SLOTS 11–15</div><span class="meta">${slots.length} FREE SLOTS · ${hc?'HIGH COMMAND':'VIEW ONLY'}</span></div><div class="structure-slots">${[11,12,13,14,15].map(slot=>{const p=state.structurePlanets.find(x=>x.alliance===a.name&&String(x.coords||'').startsWith((a.fortress.strongholdGalaxy||'07:04')+':')&&Number(x.slot)===slot);return `<div class="structure-slot"><small>PLANET SLOT ${slot}</small>${p?`<i class="structure-planet">${esc(p.name)}</i><span class="tag gold">${esc(STRUCTURE_DEFS[p.type]?.name||'STRUCTURE')}</span>${p.building?structureBuildProgress(p):'<small>SELF-DESTRUCTS AT T'+p.expiresAt+'</small>'}`:'<b>EMPTY</b>'}</div>`}).join('')}</div><div class="note" style="margin:0 12px 12px">Alliance structures occupy structure_planet slots 11–15 and appear in italics. Hostile structures can only be launched at while your alliance is at war with their owner.</div></section><div class="structure-cards">${Object.entries(STRUCTURE_DEFS).map(([id,d])=>{const cost=structureCost(id),cd=a.structures.cooldowns[id]||0,ready=state.tick>=cd,hasSlot=slots.length>0,hasStronghold=!!a.fortress.strongholdGalaxy,affordable=a.tax>0&&Object.entries(cost).every(([k,v])=>(a.fund[k]||0)>=v),operating=active.some(x=>x.type===id)||queue.some(x=>x.type===id);return `<section class="panel structure-card"><div class="ph"><div class="pt">${structureGlyph(id)}${d.name}</div><span class="meta">${d.cooldown?`COOLDOWN ${d.cooldown} TICKS`:'REPEATABLE'}</span></div><img class="alliance-structure-art" src="/assets/structures/${id}.svg" alt="${esc(d.name)} illustration" loading="lazy"><p>${d.desc}</p><div class="structure-cost"><b>COST · ${Math.round(d.share*100)}% OF DAILY ALLIANCE TAX</b><span>${Object.entries(RES).map(([k,r])=>`${r.icon} ${r.label} ${nfmt(cost[k])}`).join(' · ')}</span><small>Daily tax income: ${Object.entries(RES).map(([k,r])=>`${r.label} ${nfmt(daily[k])}`).join(' · ')}</small></div><div class="controls"><div class="field"><label for="structureSlot-${id}">Placement slot</label><select id="structureSlot-${id}" ${hasSlot?'':'disabled'}>${slots.map(n=>`<option value="${n}">Slot ${n}</option>`).join('')||'<option>No empty slots</option>'}</select></div><button class="btn primary" data-alliance="buildStructure" data-structure="${id}" ${hc&&hasSlot&&hasStronghold&&ready&&affordable&&!operating?'':'disabled'}>${operating?(queue.some(x=>x.type===id)?'BUILDING · 3 TICKS':'ALREADY ACTIVE'):!hc?'HC ONLY':!hasStronghold?'SET STRONGHOLD':!hasSlot?'NO FREE SLOT':!ready?`READY AT T${cd}`:!a.tax?'SET ALLIANCE TAX':!affordable?'FUND SHORTFALL':'BUILD · 3 TICKS'}</button></div></section>`}).join('')}</div><section class="panel" style="margin-top:12px"><div class="ph"><div class="pt">OTHER ALLIANCE STRUCTURES</div><span class="meta">WAR STATUS CONTROLS TARGETING</span></div><div class="summary-list">${other.length?other.map(p=>{const atWar=a.wars.includes(p.alliance);return `<div class="summary-line"><span><i class="structure-planet">${esc(p.name)}</i><small>${esc(p.typeName||STRUCTURE_DEFS[p.type]?.name||'Structure')} · slot ${p.slot} · ${esc(p.alliance)} · ${esc(displayCoords(p.coords))}</small></span>${atWar?'<button class="btn" data-goto="fleets">LAUNCH ATTACK</button>':'<span class="tag gold">LAUNCH LOCKED · AT PEACE</span>'}</div>`}).join(''):'<div class="empty">No other alliance structure planets are visible in this local galaxy.</div>'}</div></section><section class="panel" style="margin-top:12px"><div class="ph"><div class="pt">STRUCTURE LOG</div><span class="meta">LATEST CONSTRUCTIONS</span></div><div class="summary-list">${a.structures.history.slice(0,12).map(x=>`<div class="summary-line"><span><i class="structure-planet">${esc(x.name)}</i> · ${esc(x.message)}</span><small>T${x.tick}</small></div>`).join('')||'<div class="empty">No alliance structures built yet.</div>'}</div></section>`;}
function allianceOtherHTML(){if(allianceTab==='forums')return '<section class="panel alliance-forum-panel"><div class="ph"><div class="pt">ALLIANCE FORUMS</div><span class="meta">MEMBERS ONLY · ACHIEVEMENT LINKED</span></div><div id="allianceForumContent" class="settings-body"></div></section>';if(allianceTab==='launchbay')return allianceLaunchBayHTML();if(allianceTab==='fortress')return allianceFortressHTML();if(allianceTab==='structures')return allianceStructuresHTML();if(allianceTab==='fund')return allianceFundHTML();if(allianceTab==='ranks')return allianceRanksHTML();if(allianceTab==='intel')return allianceIntelHTML();if(allianceTab==='relations')return `<div class="alliance-grid"><section class="panel"><div class="ph"><div class="pt">DIPLOMATIC RELATIONS</div><span class="meta">OPEN GALAXY CONTACTS</span></div><div class="summary-list">${[...new Set(state.galaxy.map(p=>p.alliance).filter(n=>n&&n!==state.alliance.name))].map(n=>`<div class="summary-line"><b>${esc(n)}</b><span class="tag ${state.alliance.wars.includes(n)?'red':'blue'}">${state.alliance.wars.includes(n)?'AT WAR':'NEUTRAL'}</span><button class="btn ${state.alliance.wars.includes(n)?'warn':''}" data-alliance="toggleWar" data-war="${esc(n)}" ${mayAlliance('war')?'':'disabled'}>${state.alliance.wars.includes(n)?'MAKE PEACE':'DECLARE WAR'}</button></div>`).join('')}</div></section><section class="panel"><div class="ph"><div class="pt">ACTION LOG</div><span class="meta">HIGH COMMAND</span></div><div class="summary-list">${state.alliance.log.map(x=>`<div class="summary-line"><span>${esc(x.msg)}</span><small>T${x.tick}</small></div>`).join('')||'<div class="empty">No alliance actions recorded.</div>'}</div></section></div>`;return allianceDefenceHTML();}
function renderAlliance(){if(typeof prepareAllianceWelcome==='function')prepareAllianceWelcome();const restorePanel=document.querySelector(".alliance-restore-panel");if(restorePanel)restorePanel.hidden=state.alliance?.name!=="Unaffiliated"&&isAllianceMember("A. Commander");renderCreatedAllianceStats();document.querySelectorAll('[data-atab="intel"]').forEach(button=>button.hidden=!mayAlliance('intel'));const rankLabel=document.getElementById('allianceRankLabel');if(rankLabel)rankLabel.textContent=currentAllianceRank()==='HC'?'HIGH COMMANDER':currentAllianceRank().toUpperCase();for(const p of state.galaxy.filter(p=>p.dummy&&p.alliance===state.alliance.name))syncEditedAllianceMember(p);const title=document.getElementById('alliancePageName');if(title)title.textContent=state.alliance.name==='Unaffiliated'?'Alliance Registration':state.alliance.name;const el=document.getElementById('allianceContent');if(!el)return;if(state.alliance.name==='Unaffiliated'&&typeof allianceWelcomeHTML==='function'){el.innerHTML=allianceWelcomeHTML();const role=document.getElementById('allianceRankLabel');if(role)role.textContent='UNAFFILIATED';loadKnownAlliances();return;}document.querySelectorAll('[data-atab]').forEach(b=>b.classList.toggle('active',b.dataset.atab===allianceTab));let out=allianceTab==='attack'?'<section class="panel"><div class="ph"><div class="pt">ALLIANCE ATTACK OPERATIONS</div></div><div class="settings-body" id="allianceAttackBoard">Loading attack board…</div></section>':allianceTab==='home'?allianceHomeHTML():allianceTab==='members'?allianceMembersHTML():allianceTab==='bcalc'?bcalcHTML():allianceTab==='settings'?allianceSettingsHTML():allianceOtherHTML();el.innerHTML=out;if(allianceTab==='attack')loadAllianceAttackBoard();if(currentAllianceRank()!=='Owner'){ownerPasskeyMemory='';ownerPasskeyAlliance='';}if(allianceTab==='settings')loadOwnerSettings();if(allianceTab==='forums'&&document.querySelector('#page-alliance.active')&&typeof renderForums==='function'){forumScope='alliance';renderForums();}if(['defence','launchbay'].includes(allianceTab)){if(mayAlliance('fleetStatus'))el.innerHTML+=allianceReadinessHTML();}}
function galaxyFundMetrics(){const active=state.galaxy.filter(p=>!p.exiled&&(!state.centralPlayerId||galaxyOf(p.coords)===homeGalaxy()));const strongest=active.reduce((best,p)=>!best||planetScore(p)>planetScore(best)?p:best,null);const strongestScore=strongest?planetScore(strongest):0;const threshold=strongestScore/2;const eligible=active.filter(p=>!p.player&&p.ruler&&planetScore(p)<threshold);return {strongest,strongestScore,threshold,eligible};}
function renderGalaxyFund(){const el=document.getElementById('galaxyFundContent');if(!el)return;const fund=state.galaxyFund,metrics=galaxyFundMetrics(),minister=state.politics.ministers.economics||'',canPay=minister===(state.centralPlayerId?state.galaxy.find(p=>p.player)?.ruler:'A. Commander');el.innerHTML='<section class="panel spaceport-fund-module" aria-labelledby="spaceportFundHeading"><div class="ph"><div class="pt" id="spaceportFundHeading">GALAXY FUND</div><span class="meta">SPACEPORT TREASURY</span></div>'+galaxyTreasuryBriefingHTML()+`<div class="alliance-kpis">${Object.entries(RES).map(([id,r])=>`<div class="alliance-kpi"><small>${r.icon} ${r.label} RESERVE</small><b>${nfmt(fund[id]||0)}</b></div>`).join('')}<div class="alliance-kpi"><small>ELIGIBLE PLANETS</small><b>${metrics.eligible.length}</b></div></div><div class="alliance-grid"><section class="panel"><div class="ph"><div class="pt">CONTRIBUTE TO THE FUND</div><span class="meta">OPEN TO ALL PLAYERS</span></div><p class="fund-copy">Any planet can donate resources into the shared Galaxy Fund. Donations are deducted from your available planetary stock immediately.</p><div class="controls"><div class="field"><label for="gfundDepositResource">Resource</label><select id="gfundDepositResource">${Object.entries(RES).map(([id,r])=>`<option value="${id}">${r.label} · available ${nfmt(state.resources[id]||0)}</option>`).join('')}</select></div><div class="field"><label for="gfundDepositAmount">Amount</label><input id="gfundDepositAmount" type="number" min="1" step="1" value="500"></div><button class="btn primary" data-gfund="deposit">DEPOSIT RESOURCES</button></div></section><section class="panel"><div class="ph"><div class="pt">DISTRIBUTE GALAXY AID</div><span class="meta">ECONOMICS MINISTER ONLY</span></div><div class="fund-copy">Strongest planet: <b>${metrics.strongest?esc(metrics.strongest.name):'None'} · ${nfmt(metrics.strongestScore)}</b><br>Eligibility: planet score strictly below <b>${nfmt(metrics.threshold)}</b> (50% of strongest score). Checked again when aid is sent.</div>${canPay?`<div class="controls"><div class="field"><label for="gfundTarget">Recipient planet</label><select id="gfundTarget">${metrics.eligible.map(p=>`<option value="${esc(p.id)}">${esc(p.name)} · ${esc(p.ruler)} · score ${nfmt(planetScore(p))}</option>`).join('')}</select></div><div class="field"><label for="gfundPayoutResource">Resource</label><select id="gfundPayoutResource">${Object.entries(RES).map(([id,r])=>`<option value="${id}">${r.label} · reserve ${nfmt(fund[id]||0)}</option>`).join('')}</select></div><div class="field"><label for="gfundPayoutAmount">Amount</label><input id="gfundPayoutAmount" type="number" min="1" step="1" value="500"></div><button class="btn primary" data-gfund="payout" ${metrics.eligible.length?'':'disabled'}>SEND AID</button></div>${metrics.eligible.length?'':'<div class="empty">No planets currently meet the score requirement.</div>'}`:`<div class="fund-copy"><span class="tag red">PAYOUTS LOCKED</span><p>Current Economics Minister: <b>${esc(minister||'Unassigned')}</b>. Only the appointed minister can distribute reserves. Assign the Economics Minister in Politics.</p></div>`}</section></div><section class="panel"><div class="ph"><div class="pt">FUND TRANSACTION LOG</div><span class="meta">NEWEST FIRST</span></div><div class="summary-list">${fund.log.length?fund.log.slice(0,30).map(x=>`<div class="summary-line"><span>${esc(x.text)}</span><small>T${String(x.tick).padStart(3,'0')}</small></div>`).join(''):'<div class="empty">No Galaxy Fund transactions recorded.</div>'}</div></section><div class="note" style="margin-top:12px">The payout limit is recalculated from current planet scores for every transaction. Planets at exactly half the strongest score are not eligible.</div></section>`;}
function galaxyFundAction(action){if(state.centralPlayerId&&typeof centralGalaxyFundAction==='function')return centralGalaxyFundAction(action);const amount=Number(document.getElementById(action==='deposit'?'gfundDepositAmount':'gfundPayoutAmount')?.value),resource=document.getElementById(action==='deposit'?'gfundDepositResource':'gfundPayoutResource')?.value;if(!Number.isSafeInteger(amount)||amount<1||!RES[resource])return notify('Enter a positive whole-number amount and choose a resource.',true);const fund=state.galaxyFund;if(action==='deposit'){if((state.resources[resource]||0)<amount)return notify('Not enough available resources to deposit that amount.',true);state.resources[resource]-=amount;fund[resource]=(fund[resource]||0)+amount;const text=`A. Commander deposited ${nfmt(amount)} ${RES[resource].label} into the Galaxy Fund.`;fund.log.unshift({text,tick:state.tick});addNews(text,'good');update();notify('Donation added to the Galaxy Fund.');return;}if(state.politics.ministers.economics!=='A. Commander')return notify('Only the appointed Economics Minister can distribute Galaxy Fund aid.',true);const metrics=galaxyFundMetrics(),target=metrics.eligible.find(p=>p.id===document.getElementById('gfundTarget')?.value);if(!target)return notify('That planet is not currently eligible for Galaxy Fund aid.',true);if((fund[resource]||0)<amount)return notify('The Galaxy Fund does not have enough of that resource.',true);fund[resource]-=amount;if(target.player)state.resources[resource]=(state.resources[resource]||0)+amount;else{target.resources=target.resources||{};target.resources[resource]=(target.resources[resource]||0)+amount;}const text=`A. Commander sent ${nfmt(amount)} ${RES[resource].label} from the Galaxy Fund to ${target.name} (${target.ruler}, score ${nfmt(planetScore(target))}).`;fund.log.unshift({text,tick:state.tick});addNews(text,'good');update();notify(`Aid sent to ${target.name}.`);}
function renderPolitics(){const el=document.getElementById('politicsContent');if(!el)return;const planets=state.galaxy.filter(p=>!p.player);const ministerNames=Object.values(state.politics.ministers);el.innerHTML=politicsBriefingHTML()+(typeof populationTaxHTML==='function'?populationTaxHTML():'')+`<div class="politics-cards"><section class="politics-card"><h3>GALACTIC COMMANDER ELECTION</h3><p>The planet with the most votes wins this practice galaxy's GC position.</p><select id="gcVote">${state.politics.votes?Object.keys(state.politics.votes).map(n=>`<option>${esc(n)}</option>`).join(''):''}${planets.map(p=>`<option>${esc(p.ruler)}</option>`).join('')}</select><button class="btn primary" data-politics="vote">CAST / CHANGE VOTE</button><p>Current GC: <b>${esc(state.politics.gc)}</b> · votes ${Object.entries(state.politics.votes).map(([n,v])=>`${esc(n)} ${v}`).join(' · ')}</p></section><section class="politics-card"><h3>GALAXY IDENTITY & MESSAGE</h3><label>Galaxy name</label><input id="galaxyName" value="${esc(state.politics.banner)}"><label>Message from commanders</label><textarea id="politicsMessage" rows="3">${esc(state.politics.message)}</textarea><button class="btn primary" data-politics="message">UPDATE IDENTITY & MESSAGE</button><p>Message tags supported: [b], [i], [u], [trusted].</p></section><section class="politics-card"><h3>MINISTERIAL APPOINTMENTS</h3><p>GC appoints Communication, Development, War, Economics, and Scanner ministers. The Scanner's wave costs default to the Galaxy Fund and can be switched on the Waves page.</p>${['communication','development','war','economics','scanner'].map(role=>`<label>${role.toUpperCase()}</label><select data-minister="${role}">${[...new Set([...Object.values(state.politics.ministers),...state.galaxy.map(p=>p.ruler)])].map(x=>`<option ${state.politics.ministers[role]===x?'selected':''}>${esc(x)}</option>`).join('')}${planets.map(p=>`<option ${state.politics.ministers[role]===p.ruler?'selected':''}>${esc(p.ruler)}</option>`).join('')}</select>`).join('')}<button class="btn" data-politics="ministers">SAVE MINISTERS</button></section><section class="politics-card"><h3>GALAXY POLICIES</h3><div class="policy-grid">${planets.map(p=>`<div class="policy"><b>${esc(p.name)}</b><select data-trust="${p.id}"><option value="wanted" ${(state.politics.trust[p.id]||'wanted')==='wanted'?'selected':''}>Wanted</option><option value="trusted" ${state.politics.trust[p.id]==='trusted'?'selected':''}>Trusted</option><option value="unwanted" ${state.politics.trust[p.id]==='unwanted'?'selected':''}>Unwanted</option></select></div>`).join('')}</div><label><input type="checkbox" id="autoExile" ${state.politics.autoExile?'checked':''}> Enable simulated auto exile for unwanted inactive planets</label><button class="btn" data-politics="policies">SAVE POLICIES</button></section><section class="politics-card"><h3>GALAXY FUND PERMISSIONS</h3><p>Minister of Development controls which resources may be donated through the galaxy fund.</p>${Object.entries(RES).map(([id,r])=>`<label><input type="checkbox" data-fundallow="${id}" ${state.politics.allowedFund[id]?'checked':''}> Allow ${r.label} trades and donations</label>`).join('')}<button class="btn" data-politics="fund">SAVE FUND SETTINGS</button></section><section class="politics-card"><h3>EXILE VOTES</h3><p>Requires agreement from two ministers. Cost scales with target score. Up to two exiles per 200 ticks; local simulation marks the target exiled.</p><select id="exileTarget">${planets.map(p=>`<option value="${p.id}">${p.name} · score ${nfmt(planetScore(p))}</option>`).join('')}</select><input id="exileReason" placeholder="Reason for vote"><button class="btn warn" data-politics="exile">START EXILE VOTE</button><div>${state.politics.votesToExile.map(v=>`<div class="vote-item"><b>${esc(v.planet)}</b><small>${esc(v.reason)} · ${v.approvals.length}/2 minister approvals · ${v.status}</small>${v.status==='pending'?`<button class="btn" data-approveexile="${v.id}">MINISTER APPROVE</button>`:''}</div>`).join('')||'<p>No current exile votes.</p>'}</div><small>Exiled this 200-tick window: ${state.politics.exileCount}/2</small></section></div>`;}
const SCAN_TYPES=[['planet','Planet Scan',1000,'Planet value, resources, asteroids, guards and production mix.'],['landing','Landing Scan',2000,'ETA 1 fleets attacking or defending the target.'],['development','Development Scan',3000,'Construction and planet development status.'],['unit','Unit Scan',4000,'Ship composition with up to 20% distortion.'],['news','News Scan',5000,'Intercepted news, delayed by three ticks.'],['incoming','Incoming Scan',6000,'Fleet composition travelling toward your planet.'],['jumpgate','Jumpgate Probe',7000,'Friendly and hostile fleets travelling to the target.'],['advanced','Advanced Unit Scan',8000,'Exact ship composition, including cloaked units.']];
const WAVE_CORE_PATHS={planet:'<circle cx="18" cy="18" r="7"/><path d="M4 18s5-9 14-9 14 9 14 9-5 9-14 9S4 18 4 18Z"/>',landing:'<path d="M18 5v19m-7-7 7 7 7-7M7 28h22"/><circle cx="18" cy="8" r="3"/>',development:'<path d="M7 28V13l8 5v-8l8 8V7h6v21zM11 23h3m4 0h3m4 0h3"/>',unit:'<path d="m18 5 11 6v14l-11 6-11-6V11z"/><circle cx="18" cy="18" r="5"/><path d="M18 8v5m0 10v5m-10-10h5m10 0h5"/>',news:'<path d="M8 6h16l5 5v18H8zM24 6v6h5"/><path d="M12 17h13m-13 5h13m-13 4h8"/>',incoming:'<path d="M7 8h8m0 0-4-4m4 4-4 4m-4 12h18m0 0-5-5m5 5-5 5M7 17h10"/>',jumpgate:'<circle cx="18" cy="18" r="12"/><circle cx="18" cy="18" r="6"/><path d="M18 2v5m0 22v5M2 18h5m22 0h5"/>',advanced:'<path d="M4 18s5-10 14-10 14 10 14 10-5 10-14 10S4 18 4 18Z"/><circle cx="18" cy="18" r="6"/><path d="m15 18 2 2 4-5"/>',};
const WAVE_RACE_FRAMES={Terran:'<path d="M10 4h17l5 5v18l-5 5H10l-5-5V9zM9 10h5m9 16h5"/>',Cathaar:'<path d="M18 3 31 17 18 33 5 17zM18 9v16"/>',Xandathrii:'<path d="M10 4h16l8 13-8 13H10L2 17zM9 12l9-6 9 6v10l-9 6-9-6z"/>',Zikonian:'<path d="m18 3 13 7-3 16-12 7L5 22 7 9zM18 3v13l13-6M18 16l-2 17"/>',Eitraides:'<path d="M4 12c7-8 21-8 28 0M4 18c7-8 21-8 28 0M4 24c7-8 21-8 28 0"/>',};
function waveScanIcon(id){const race=RACE_SKINS.includes(state.race)?state.race:'Terran';return `<span class="wave-symbol race-${race.toLowerCase()}" data-race="${race}" data-scan="${id}" aria-hidden="true"><svg viewBox="0 0 36 36" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><g class="wave-race-frame">${WAVE_RACE_FRAMES[race]}</g><g class="wave-scan-core" stroke-width="1.8">${WAVE_CORE_PATHS[id]||WAVE_CORE_PATHS.planet}</g></svg></span>`;}
function scanCost(base){const amps=state.buildings.waveAmplifier||0;return Math.ceil(base*(1-Math.min(.75,Math.max(0,amps-1)*.003)));}
function makeScanLink(sc){const payload={kind:'starfall-scan',name:sc.name,targetName:sc.targetName,coords:sc.coords,text:sc.text,tick:sc.tick};const token=btoa(unescape(encodeURIComponent(JSON.stringify(payload)))).replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');return location.href.split('#')[0]+'#scan='+token;}function readScanLink(value){const input=String(value||'').trim(),m=input.match(/(?:#|[?&])scan=([A-Za-z0-9_-]+)/);if(m){try{const token=m[1].replace(/-/g,'+').replace(/_/g,'/'),json=decodeURIComponent(escape(atob(token)));const data=JSON.parse(json);if(data.kind==='starfall-scan'&&data.text)return data;}catch(e){}}return {kind:'text',text:input};}
function parseShipReport(text){const out=Object.fromEntries(Object.keys(SHIPS).map(id=>[id,0]));for(const [id,d] of Object.entries(SHIPS)){const names=[id,d.name].map(x=>x.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'));const re=new RegExp('(?:'+names.join('|')+')\\s*[:=x\\-]?\\s*([0-9][0-9,]*)','i');const m=text.match(re);if(m)out[id]=Number(m[1].replace(/,/g,''));}return out;}
function scanData(id,type){const p=state.galaxy.find(x=>x.id===id);if(!p)return 'Target unavailable';if(type==='planet')return `Ruler: ${p.ruler}\\nPlanet: ${p.name}\\nCoords: ${displayCoords(p.coords)}\\nValue: ${nfmt(npcValue(p))} · Score: ${nfmt(planetScore(p))}\\nAsteroids: ${totalRoids(p.roids)}\\nResources: ${Object.entries(p.resources).map(([k,v])=>`${k} ${nfmt(v)}`).join(' · ')}\\nProduction mix: Metal ${p.roids.metal>6?'High':'Medium'} · Crystal ${p.roids.crystal>6?'High':'Medium'} · Eonium ${p.roids.eonium>6?'High':'Medium'}`;if(type==='landing')return `ETA 1 inbound fleets: ${state.missions.filter(m=>m.targetId===id&&m.eta<=1).length}\\nNo live shared universe connection.`;if(type==='development')return `Structures: ${p.structures}\\nFacility estimate: ${p.structures} developed sites\\nDevelopment status: ${p.structures>7?'Advanced':'Growing'}`;if(['unit','advanced','incoming','jumpgate'].includes(type)){let f=p.ships||{};if(type==='incoming')f=Object.fromEntries(Object.keys(SHIPS).map(k=>[k,0]));return `Ship composition${type==='unit'?' (approx. ±20%)':''}:\\n${Object.entries(f).map(([k,v])=>`${SHIPS[k].name}: ${type==='unit'?Math.max(0,Math.round(v*(.8+Math.random()*.4))):v}`).join('\\n')}\\nIncoming fleets are simulated locally.`;}if(type==='news')return `News scan · ${p.name}\\nDelayed transmissions through tick ${Math.max(0,state.tick-3)}\\nNo intercepted battle reports in this practice snapshot.`;return '';}
function scannerFundingSource(){if(!isCurrentScanner())return 'personal';const saved=state.waves.fundSources?.['A. Commander'];if(['personal','alliance','galaxy'].includes(saved))return saved;return state.politics?.ministers?.scanner==='A. Commander'?'galaxy':'alliance';}
function scanFundingMenu(){if(!isCurrentScanner())return '';const current=scannerFundingSource(),sources=[['personal','Personal funds',state.resources],['alliance','Alliance fund',state.alliance.fund],['galaxy','Galaxy fund',state.galaxyFund||{}]];return `<details class="scan-funding-menu"><summary title="Choose scan funding" aria-label="Choose scan funding">+</summary><div class="scan-funding-pop" role="group" aria-label="Scan funding source"><b>SCAN FUNDING</b>${sources.map(([id,label,pool])=>`<label><input type="radio" name="scanFunding" data-scan-funding="${id}" ${current===id?'checked':''}><span>${label}</span><small>${Object.entries(RES).map(([r,d])=>`${d.icon} ${nfmt(pool?.[r]||0)}`).join(' · ')}</small></label>`).join('')}</div></details>`;}
function scanFundBalance(source,key){return source==='personal'?(state.resources[key]||0):source==='alliance'?(state.alliance.fund[key]||0):((state.galaxyFund||{})[key]||0);}
function canAffordScan(bill,source=scannerFundingSource()){return Object.entries(bill).every(([key,value])=>scanFundBalance(source,key)>=value);}
function payScan(bill,source=scannerFundingSource()){if(source==='galaxy')state.galaxyFund=state.galaxyFund||{metal:0,crystal:0,eonium:0,log:[]};for(const [key,value] of Object.entries(bill)){if(source==='personal')state.resources[key]-=value;else if(source==='alliance')state.alliance.fund[key]-=value;else state.galaxyFund[key]-=value;}}
function scanFundLabel(source=scannerFundingSource()){return {personal:'personal funds',alliance:'Alliance Fund',galaxy:'Galaxy Fund'}[source]||'personal funds';}
function renderWaves(){const el=document.getElementById('wavesContent');if(!el)return;const canScan=(state.buildings.waveAmplifier||0)>0,targets=state.galaxy.filter(p=>!p.player&&!p.exiled&&galaxyOf(p.coords)===homeGalaxy()),coords=state.waves.targetCoords||{x:'07',y:'04',z:'01'},costIcons={metal:'⬡',crystal:'◇',eonium:'⌬'};el.innerHTML=`<div class="waves-layout"><div class="waves-main"><div class="note">Wave Amplifiers unlock scans and improve penetration. The first amplifier enables scans; each additional amplifier reduces scan costs by 0.3% (maximum 75%). Current amplifiers: ${state.buildings.waveAmplifier||0}.</div>${mayGalaxyScan()?`<section class="panel" style="margin-bottom:12px"><div class="ph"><div class="pt">MINISTER OF WAR · GALAXY SCAN</div><span class="meta">${targets.length} AVAILABLE PLANETS</span></div><div class="controls"><fieldset class="galaxy-scan-radio"><legend>Scan type</legend>${[["all","All scans"],...SCAN_TYPES].map(([id,name])=>`<label><input type="radio" name="galaxyScanType" value="${id}" ${(state.waves.galaxyScanType||"planet")===id?"checked":""}>${name}</label>`).join('')}<small>All scans runs every unlocked type. Normal costs apply.</small></fieldset><button class="btn primary" data-galaxyscan>SCAN ENTIRE GALAXY</button></div></section>`:''}<section class="panel wave-target-panel"><div class="ph"><div class="pt">SCAN COORDINATES</div><span class="meta">CUSTOM COORDINATES · X : Y : Z</span></div><div class="wave-target-controls"><div class="wave-coords"><span>Coords:</span><label><input type="number" min="1" max="100" aria-label="Galaxy X coordinate" data-wave-coord="x" value="${esc(coords.x)}"><small>X</small></label><b>:</b><label><input type="number" min="1" max="100" aria-label="Galaxy Y coordinate" data-wave-coord="y" value="${esc(coords.y)}"><small>Y</small></label><b>:</b><label><input type="number" min="1" max="999" aria-label="Planet Z coordinate" data-wave-coord="z" value="${esc(coords.z)}"><small>Z</small></label></div><label class="tag wave-anon"><input type="checkbox" id="anonymousScan" ${state.waves.anonymous?'checked':''}> Anonymous share</label></div><div class="scan-custom-controls"><div class="field"><label for="customScanCoordinates">Custom coordinates · Galaxy:slot</label><input id="customScanCoordinates" placeholder="2:7"><small>2:7 uses galaxy 2 in your home sector. Full X:Y:Z coordinates also work.</small></div><button class="btn" data-apply-scan-coordinates="custom">USE COORDINATES</button><div class="field"><label for="pasteScanCoordinates">Paste coordinates</label><textarea id="pasteScanCoordinates" class="parse-area" placeholder="Paste 2:7 or 07:04:01"></textarea></div><button class="btn" data-apply-scan-coordinates="paste">USE PASTED COORDINATES</button><p id="scanCoordinateFeedback" role="status" aria-live="polite"></p></div></section><section class="panel wave-scans-panel"><div class="ph"><div class="pt">AVAILABLE SCANS</div><span class="meta">SELECT A SCAN TO LAUNCH</span>${scanFundingMenu()}</div><div class="wave-scan-list">${SCAN_TYPES.map(([id,name,cost,desc])=>{const req={planet:0,landing:1,development:2,unit:3,news:4,incoming:5,jumpgate:6,advanced:7}[id]||0,unlocked=(state.research.scans||0)>=req,ready=canScan&&unlocked;return `<article class="wave-scan-row">${waveScanIcon(id)}<div class="wave-scan-copy"><h3>${name}</h3><p>${desc}</p><div class="wave-cost"><span>Cost</span>${Object.entries(RES).map(([r,d])=>`<span class="wave-cost-item"><i>${costIcons[r]}</i>${nfmt(scanCost(cost))}</span>`).join('')}</div></div><button class="btn ${ready?'primary':''}" data-scan="${id}" ${ready?'':'disabled'}>${!canScan?'BUILD A WAVE AMPLIFIER':!unlocked?`RESEARCH SCAN LEVEL ${req}`:'LAUNCH'}</button></article>`;}).join('')}</div></section><section class="panel" style="margin-top:12px"><div class="ph"><div class="pt">SAVED SCANS · TWO-WEEK ARCHIVE</div><span class="meta">LOCAL COPY · SHAREABLE TEXT</span></div>${state.waves.scans.length?state.waves.scans.map(sc=>`<div class="scan-report"><strong>${sc.name} · ${sc.targetName} ${sc.anonymous?'· COORDINATES HIDDEN':'· '+sc.coords}</strong><small>${esc(sc.text).replace(/\n/g,'<br>')}<br>Saved at tick ${sc.tick} · ${Math.max(0,336-(state.tick-sc.tick))} ticks archive life</small><div class="copy-actions"><button class="btn" data-copyscan="${sc.id}">COPY SCAN</button><button class="btn" data-sharescan="${sc.id}" ${state.userSettings.allianceScansEnabled?'':'disabled'}>COPY SCAN LINK</button><button class="btn" data-coords="${sc.id}">${sc.anonymous?'COORDS HIDDEN':'TOGGLE COORDS'}</button><button class="btn warn" data-deletescan="${sc.id}">DELETE</button></div></div>`).join(''):'<div class="empty">No scans saved yet. Build a Wave Amplifier to start scanning.</div>'}</section></div><aside class="waves-side"><section class="panel wave-side-panel"><div class="ph"><div class="pt">COMMAND STATUS</div><span class="meta">ROUND ${String(state.tick).padStart(3,'0')}</span></div><div class="wave-side-name"><b>A. Commander</b><small>Vesper-3 · ${esc(state.race||'Terran')}</small></div><div class="wave-side-section"><span>TICK</span><b>${state.tick}</b></div><div class="wave-side-section"><span>RESOURCES</span>${Object.entries(RES).map(([id,d])=>`<div><i>${costIcons[id]}</i>${d.label}<b>${nfmt(state.resources[id])}</b></div>`).join('')}</div><div class="wave-side-section"><span>PLANET</span><div>Asteroids<b>${nfmt(totalRoids(state.roids))}</b></div><div>Value<b>${nfmt(playerValue())}</b></div><div>Experience<b>${nfmt(state.xp)} XP</b></div></div><div class="wave-side-section"><span>ORDERS</span><div>Construction<b>${state.construction?esc(BUILDINGS[state.construction.id]?.name||'Active'):'Nothing'}</b></div><div>Research<b>${state.researchActive?esc(TECH_TREE.find(x=>x.id===state.researchActive)?.name||'Active'):'Nothing'}</b></div><div>Production<b>${state.production?`${nfmt(state.production.remaining)} remaining`:'No orders'}</b></div></div></section></aside></div>`;}


function isCurrentScanner(){return mayAlliance('scans')||state.politics?.ministers?.scanner==='A. Commander';}
function mayGalaxyScan(){return state.politics?.ministers?.war==='A. Commander'||isCurrentScanner();}
function runGalaxyScan(){if(!state.userSettings.allianceScansEnabled)return notify('Enable Alliance Scans in Planet Settings before launching a galaxy scan.',true);if(!(state.buildings.waveAmplifier>0))return notify('Build a Wave Amplifier first.',true);if(!mayGalaxyScan())return notify('Only your Minister of War, Alliance HC, or an alliance member marked Scanner can run galaxy scans.',true);const type=document.querySelector('input[name="galaxyScanType"]:checked')?.value||state.waves.galaxyScanType||'planet',requirements={planet:0,landing:1,development:2,unit:3,news:4,incoming:5,jumpgate:6,advanced:7},level=state.research.scans||0;if(type!=='all'&&!SCAN_TYPES.some(t=>t[0]===type))return notify('Choose a scan type.',true);if(type!=='all'&&level<requirements[type])return notify('Research Scan level '+requirements[type]+' first.',true);const types=SCAN_TYPES.filter(t=>type==='all'?level>=requirements[t[0]]:t[0]===type),targets=state.galaxy.filter(p=>!p.player&&!p.exiled&&galaxyOf(p.coords)===homeGalaxy());if(!targets.length)return notify('No planets available for this galaxy sweep.',true);const total=types.reduce((sum,t)=>sum+scanCost(t[2]),0)*targets.length,bill={metal:total,crystal:total,eonium:total},source=scannerFundingSource();if(!canAffordScan(bill,source))return notify('The '+scanFundLabel(source)+' cannot cover this galaxy sweep ('+nfmt(total)+' of each resource).',true);payScan(bill,source);for(const p of targets)for(const [id,name] of types)state.waves.scans.unshift({id:Math.random().toString(36).slice(2),type:id,name,targetName:p.name,coords:p.coords,anonymous:state.waves.anonymous,text:scanData(p.id,id),tick:state.tick,savedAt:Date.now()});state.waves.scans=state.waves.scans.slice(0,500);state.waves.galaxyScanType=type;const count=targets.length*types.length;addNews((type==='all'?'All unlocked scans':types[0][1])+' galaxy sweep completed across '+targets.length+' planets using '+scanFundLabel(source)+'.','good');update();notify('Saved '+count+' scans.');}

function runScan(type){const req={landing:1,development:2,unit:3,news:4,incoming:5,jumpgate:6,advanced:7}[type]||0;if((state.research.scans||0)<req)return notify(`Research Scan level ${req} to unlock this scan.`,true);const base=SCAN_TYPES.find(x=>x[0]===type);const c=state.waves.targetCoords||{},coord=[c.x,c.y,c.z].map(v=>String(v||'').padStart(2,'0')).join(':'),p=state.galaxy.find(x=>x.coords===coord);if(!base)return;if(!(state.buildings.waveAmplifier>0))return notify('Build a Wave Amplifier first.',true);if(!p)return notify(`No planet exists at ${coord} in this practice galaxy.`,true);const cost=scanCost(base[2]),bill={metal:cost,crystal:cost,eonium:cost};const source=scannerFundingSource();if(!canAffordScan(bill,source))return notify(`The ${scanFundLabel(source)} cannot cover this scan.`,true);if(type==='landing'&&!state.missions.some(m=>m.targetId===p.id&&m.eta<=1))return notify('Landing Scans require a fleet at ETA 1.',true);if(type==='incoming'&&!state.missions.some(m=>m.targetId==='home'))return notify('Incoming Scans require an enemy fleet travelling toward you.',true);payScan(bill,source);const text=scanData(p.id,type),obj={id:Math.random().toString(36).slice(2),type,name:base[1],targetName:p.name,coords:p.coords,anonymous:document.getElementById('anonymousScan').checked,text,tick:state.tick};obj.savedAt=Date.now();state.waves.scans.unshift(obj);state.waves.scans=state.waves.scans.slice(0,30);addNews(`${base[1]} completed for ${p.name} using ${scanFundLabel(source)}.`,'good');update();notify(`${base[1]} saved to Waves.`);}
function updateShipPreview(id){const input=document.getElementById('qty-'+id),el=document.getElementById('shipcost-'+id);if(!input||!el)return;const qty=Math.max(1,Math.min(20000,Math.floor(Number(input.value)||1))),cost=Object.fromEntries(Object.entries(shipProductionCost(id)).map(([k,v])=>[k,v*qty]));el.innerHTML=`${qty} ${SHIPS[id].name}${qty===1?'':'s'} · ${constructionCostText(cost)}<br><b>${canAfford(cost)?'AFFORDABLE':'SHORT ON RESOURCES'}</b> · EST. ${Math.max(1,Math.ceil(Object.values(cost).reduce((n,v)=>n+v,0)/productionRate(null)))} TICKS`;}
function bcalcCopy(kind){const get=(side)=>Object.fromEntries(Object.keys(SHIPS).map(id=>[id,Number(document.querySelector(`[data-cship="${side}"][data-ship="${id}"]`)?.value||0)]));const a=get('a'),d=get('d');if(kind==='attacker')return Object.entries(a).filter(([,n])=>n).map(([id,n])=>`${SHIPS[id].name}: ${n}`).join('\\n')||'No ships';if(kind==='defender')return Object.entries(d).filter(([,n])=>n).map(([id,n])=>`${SHIPS[id].name}: ${n}`).join('\\n')||'No ships';if(kind==='report')return `ATTACKER\\n${Object.entries(a).map(([id,n])=>`${SHIPS[id].name}: ${n}`).join('\\n')}\\n\\nDEFENDER\\n${Object.entries(d).map(([id,n])=>`${SHIPS[id].name}: ${n}`).join('\\n')}`;return document.getElementById('calcResult').innerText;}
function copyText(s){if(navigator.clipboard?.writeText)navigator.clipboard.writeText(s).then(()=>notify('Copied to clipboard.')).catch(()=>notify('Clipboard unavailable; select and copy the text.',true));else notify('Clipboard unavailable in this browser.',true);}
function calculateBattle(){const a=Object.fromEntries(Object.keys(SHIPS).map(id=>[id,Number(document.querySelector(`[data-cship="a"][data-ship="${id}"]`)?.value||0)])),d=Object.fromEntries(Object.keys(SHIPS).map(id=>[id,Number(document.querySelector(`[data-cship="d"][data-ship="${id}"]`)?.value||0)]));if(![...Object.values(a),...Object.values(d)].every(n=>Number.isSafeInteger(n)&&n>=0&&n<=1000000000))return notify('Use whole ship counts from 0 to 1,000,000,000.',true);const population=Math.max(0,Math.floor(Number(document.getElementById('calcPopulation')?.value??1000))),x=resolveCombat(a,d,undefined,undefined,population,Math.max(0,Math.floor(Number(document.getElementById('calcBiodomes')?.value)||0)),Math.max(0,Math.min(999,Number(document.getElementById('calcBiodomeDamage')?.value)||0))),winner=totalShips(x.attacker)>totalShips(x.defender)?'ATTACKER ADVANTAGE':totalShips(x.defender)>totalShips(x.attacker)?'DEFENDER ADVANTAGE':'MUTUAL / NO CLEAR WINNER';window.bcalc=a?{a,d,population,biodomes:x.habitat.before,biodomeDamage:x.habitat.damageBefore}:null;window.bcalcResult=`<b>${winner}</b><br>Starting ships · attacker ${totalShips(a)} / defender ${totalShips(d)}<br>Ships lost · attacker ${x.aLost} / defender ${x.dLost}<br>Survivors · attacker ${totalShips(x.attacker)} / defender ${totalShips(x.defender)}<br><br>ATTACKER SURVIVORS: ${Object.entries(x.attacker).filter(([,n])=>n).map(([id,n])=>`${SHIPS[id].name} ${n}`).join(' · ')||'none'}<br>DEFENDER SURVIVORS: ${Object.entries(x.defender).filter(([,n])=>n).map(([id,n])=>`${SHIPS[id].name} ${n}`).join(' · ')||'none'}`;const report=recordSimulatedCalculatorReport(x,document.getElementById('calcTitle')?.value||'Calculator engagement');window.bcalcResult+='<h3>SIMULATED NEWS REPORT</h3>'+battleNewsHTML(report);renderAlliance();}
function allianceAction(action,button){if(state.centralPlayerId&&['accept','decline'].includes(action)&&typeof centralRecruitmentDecision==='function')return centralRecruitmentDecision(action,button);const key=ALLIANCE_ACTION_PERMISSIONS[action];if(key&&!mayAlliance(key))return notify('Your rank cannot use this alliance action.',true);if(action==='exchange')return exchangeAllianceResources();const a=state.alliance;if(action==='setFortress'){if(!mayAlliance('fortress'))return notify('Your rank cannot set the stronghold.',true);const coords=(document.getElementById('fortressGalaxy')?.value||'').trim(),allowedGalaxies=allianceMemberGalaxies();if(!allowedGalaxies.includes(coords))return notify('Choose a galaxy that currently contains alliance members.',true);const normalizedCoords=coords;const old=a.fortress.strongholdGalaxy;if(old===normalizedCoords)return notify('The alliance stronghold is already in that galaxy.');a.fortress.strongholdGalaxy=normalizedCoords;if(!a.fortress.lastDistorterTick)a.fortress.lastDistorterTick=state.tick;if(state.tick>1){a.fortress.anarchyUntilTick=state.tick+allianceHoursToTicks(24)-1;a.fortress.anarchyEnded=false;allianceLogAction(`Stronghold moved from ${old||'unset'} to ${normalizedCoords}. Anarchy Mode: alliance member income reduced by 2% for 24 hours.`,'warn');notify('Stronghold moved. Anarchy Mode is active for 24 hours.',true);}else{allianceLogAction(`Alliance stronghold set to ${normalizedCoords} before the first tick.`,'good');notify('Alliance stronghold established.');}return update();}if(action==='buildStructure'){return queueAllianceStructure(button.dataset.structure,Number(document.getElementById('structureSlot-'+button.dataset.structure)?.value));}if(action==='toggleWar'){if(!mayAlliance('war'))return notify('Your rank cannot change war status.',true);const enemy=button.dataset.war;if(!enemy||enemy===a.name)return;return declareAllianceDiplomacy(enemy,a.wars.includes(enemy)?'peace':'war');}if(action==='message'){a.message=document.getElementById('allianceMessage').value;allianceLog('Commander message updated.');}if(action==='toggleapps')a.applicationsOpen=!a.applicationsOpen;if(action==='accept'&&a.applicants.length){if(a.members.length>=40)return notify('Alliance member limit reached.',true);const i=a.applicants.findIndex(x=>x.id===button.dataset.applicant),x=a.applicants.splice(i<0?0:i,1)[0];a.members.push({id:`member-${Date.now()}`,name:x.name,planet:x.planet,coords:x.coords,rank:'Recruit',online:false});const p=state.galaxy.find(q=>q.name===x.planet);if(p)p.alliance=a.name;allianceLog(`${x.planet} accepted as a Recruit into ${a.name}.`);}if(action==='decline'&&a.applicants.length){const i=a.applicants.findIndex(x=>x.id===button.dataset.applicant),x=a.applicants.splice(i<0?0:i,1)[0];allianceLog(`${x.planet} application declined.`);}if(action==='call'){const p=state.galaxy.find(x=>x.name===document.getElementById('callTarget').value),eta=Math.max(1,Math.min(24,Number(document.getElementById('callEta').value)||1)),c={id:Math.random().toString(36).slice(2),planet:p?.name||'Morrow Wake',coords:p?.coords||'07:04:02',eta,notes:document.getElementById('callNotes').value||'Hostile fleet sighted',attackerCount:'Unknown',age:0};a.calls.push(c);allianceLog(`Defence called for ${c.planet}, hostile ETA ${eta}.`);notify('Alliance defence call sent.');}if(action==='dismiss'){a.calls=a.calls.filter(c=>c.id!==button.dataset.call);allianceLog('A defence call was closed.');}if(action==='donate')return donateAllianceFund();if(action==='tax'){a.tax=Math.max(0,Math.min(5,Number(document.getElementById('allianceTax').value)||0));allianceLog(`Automatic alliance tax set to ${a.tax}%.`);}update();}
function respondDefence(){const fid=document.getElementById('defenceFleet').value,c=state.alliance.calls.find(x=>x.id===document.getElementById('defenceCall').value);if(!c)return notify('Choose an open defence call.',true);const f=state.fleets[fid];if(!totalShips(f))return notify('Selected fleet has no ships.',true);const composition=copy(f);for(const k of Object.keys(f))f[k]=0;state.missions.push({id:Math.random().toString(36).slice(2),fleet:fid,name:fleetLabel(fid),targetId:'alliance:'+c.id,targetName:c.planet,mission:'Defence',eta:Math.min(4,Math.max(1,c.eta)),phase:'outbound',ships:composition,callId:c.id});allianceLog(`${fleetLabel(fid)} dispatched to defend ${c.planet}.`);update();notify('Defence fleet dispatched.');}
function politicsAction(action){if(state.centralPlayerId&&['vote','ministers'].includes(action)&&typeof centralPoliticsAction==='function')return centralPoliticsAction(action);const p=state.politics;if(action==='vote'){const name=document.getElementById('gcVote').value;p.votes=p.votes||{};p.votes[name]=(p.votes[name]||0)+1;p.gc=Object.entries(p.votes).sort((a,b)=>b[1]-a[1])[0][0];addNews(`Galaxy vote cast for ${name}. Current Galactic Commander: ${p.gc}.`,'good');}if(action==='message'){p.banner=document.getElementById('galaxyName').value.slice(0,32)||'Vesper Reach';p.message=document.getElementById('politicsMessage').value.slice(0,500);addNews('Galaxy identity and commanders message updated.');}if(action==='ministers'){p.ministers={};document.querySelectorAll('[data-minister]').forEach(e=>p.ministers[e.dataset.minister]=e.value);addNews('Galaxy minister appointments updated.');}if(action==='policies'){document.querySelectorAll('[data-trust]').forEach(e=>p.trust[e.dataset.trust]=e.value);p.autoExile=document.getElementById('autoExile').checked;addNews('Galaxy wanted, trusted, and auto-exile settings updated.');}if(action==='fund'){document.querySelectorAll('[data-fundallow]').forEach(e=>p.allowedFund[e.dataset.fundallow]=e.checked);addNews('Galaxy fund permissions updated.');}if(action==='exile'){if(p.exileCount>=2)return notify('Two members have already been exiled in this 200-tick window.',true);const target=state.galaxy.find(x=>x.id===document.getElementById('exileTarget').value);if(!target)return;const cost=Math.ceil(planetScore(target)/10*(p.exileCount+2)/2);const bill={metal:cost,crystal:cost,eonium:cost};if(!Object.entries(bill).every(([k,v])=>(state.alliance.fund[k]||0)>=v))return notify(`Galaxy fund requires ${nfmt(cost)} of each resource for this exile vote.`,true);Object.entries(bill).forEach(([k,v])=>state.alliance.fund[k]-=v);p.votesToExile.push({id:Math.random().toString(36).slice(2),planet:target.name,target:target.id,reason:document.getElementById('exileReason').value||'No reason supplied',approvals:[],status:'pending',cost});addNews(`Exile vote opened for ${target.name}.`,'warn');}update();}
function approveExile(id){const v=state.politics.votesToExile.find(x=>x.id===id);if(!v||v.status!=='pending')return;const signer=Object.values(state.politics.ministers).find(n=>!v.approvals.includes(n));if(!signer)return notify('Each minister has already voted.',true);v.approvals.push(signer);if(v.approvals.length>=2){v.status='approved';state.politics.exileCount++;state.politics.exiles.push(v.target);const exiledPlanet=state.galaxy.find(p=>p.id===v.target);if(exiledPlanet)exiledPlanet.exiled=true;addNews(`${v.planet} was exiled from the practice galaxy. Reason: ${v.reason}`,'warn');}update();}
function wavesAction(type){if(type==='scan')return;}


function renderAdmin(){if(!window.isGameAdmin&&window.isPortalStaff&&new URLSearchParams(location.search).get('staff_tool')==='bank')adminTab='spacingBank';if(!window.isGameAdmin&&!(adminTab==='spacingBank'&&window.isPortalStaff)&&!(adminTab==='multihunters'&&window.canMultihunt)){const root=document.getElementById('adminContent');if(root)root.innerHTML='<p>Administrator access required.</p>';return;}
 if(adminTab==='alliances'){renderAdminAllianceCenter();return;}if(adminTab==='multihunters'){renderMultihunters();return;}
 const centerNav=adminSubpageNav([['control','Round & ticker'],['planets','Planet Editor'],['ships','Stats Editor'],['tools','Planet tools'],['havoc','Havoc'],['spacingBank','Spacing Bank']],['round','state'].includes(adminTab)?'control':adminTab,'data-admin-tab');
 if(!['round','state','control'].includes(adminTab)){renderAdminSection();const el=document.getElementById('adminContent');el.innerHTML=centerNav+el.innerHTML.replace(/<div class="admin-planet-tools-nav controls">[\s\S]*?<\/div>/,'');document.getElementById('adminPageHeading').textContent='Admin Controlcenter · '+({planets:'Planet Editor',ships:'Stats Editor',tools:'Planet tools',havoc:'Havoc'})[adminTab];return;}
 const el=document.getElementById('adminContent');if(!el)return;
 adminTab='round';renderAdminSection();const setup=el.innerHTML.replace(/<div class="admin-planet-tools-nav controls">[\s\S]*?<\/div>/,'').replace(/<button[^>]*data-planet-tools=[^>]*>[\s\S]*?<\/button>/g,'').replace(/<button[^>]*data-admin="(?:advance|resetplanets)"[^>]*>[\s\S]*?<\/button>/g,'');
 adminTab='state';renderAdminSection();const runtime=el.innerHTML.replace(/<div class="admin-planet-tools-nav controls">[\s\S]*?<\/div>/,'').replace(/<label class="field">Minutes per tick<input[^>]*>[\s\S]*?<\/label>/,'').replace(/<button[^>]*data-ticker="speed"[^>]*>[\s\S]*?<\/button>/,'');
 adminTab='control';document.getElementById('adminPageHeading').textContent='Admin Controlcenter';document.getElementById('adminPageDescription').textContent='Configure the round, manage the ticker and inspect saved state from one command center.';
 el.innerHTML=centerNav+'<section class="admin-controlcenter admin-round-unified" id="admin-round-control"><h2>Round settings, ticker & recovery</h2><p class="note">Save the configuration below, then manage the same ticker and saved state. Tick speed is configured once in Round configuration.</p>'+setup+runtime+(typeof distributionControlsHTML==='function'?distributionControlsHTML():'')+'</section>';
}
function renderAdminSection(){const header=document.getElementById('adminPageHeading'),description=document.getElementById('adminPageDescription'),labels={round:'Current Round Setup',planets:'Planet Editor',ships:'Stats Editor',state:'Round State'};if(header)header.textContent=labels[adminTab]||'Current Round Setup';if(description)description.textContent=({round:'Configure the current round and gameplay settings.',planets:'Edit planet identities, resources, fleets and alliance assignments.',ships:'Edit ship statistics and balance settings.',state:'Control the ticker, scheduled starts and round reset.'})[adminTab];const el=document.getElementById('adminContent');if(!el)return;const selected=state.galaxy.find(p=>p.id===(state.adminSelected||'home'))||state.galaxy[0],cfg=state.config;const tabs=[['round','Round setup'],['planets','Planets'],['ships','Ship stats'],['state','Round state']];let content='';if(adminTab==='spacingBank'){content='<div id="spacingBankAdmin">Retrieving bank register…</div>';setTimeout(()=>window.renderSpacingBankAdmin?.(),0);}if(adminTab==='round'){content=`<section class="panel"><div class="ph"><div class="pt">ROUND CONFIGURATION</div><span class="meta">SAVE TO APPLY</span></div><div class="admin-form"><div class="field"><label>Round name</label><input id="admRoundName" value="${esc(cfg.roundName)}"></div><div class="field"><label>Player race / ship set</label><select id="admRaceSet">${['Terran','Cathaar','Xandathrii','Zikonian','Eitraides'].map(r=>`<option ${state.race===r?'selected':''}>${r}</option>`).join('')}</select></div><div class="field"><label>Round length (ticks)</label><input id="admRoundLength" type="number" min="1" max="10000" value="${state.roundLength}"></div><div class="field"><label>Tick interval (hours)</label><input id="admTickHours" type="number" min="0.02" max="24" step="0.25" value="${cfg.tickHours}"></div><div class="field"><label>Protection period (ticks)</label><input id="admProtection" type="number" min="0" max="1000" value="${cfg.protectionTicks}"></div><div class="field"><label>Income multiplier</label><input id="admIncome" type="number" min="0" max="100" step="0.1" value="${cfg.incomeMultiplier}"></div><div class="field"><label>Research multiplier</label><input id="admResearch" type="number" min="0" max="100" step="0.1" value="${cfg.researchMultiplier}"></div><div class="field"><label>Production multiplier</label><input id="admProduction" type="number" min="0" max="100" step="0.1" value="${cfg.productionMultiplier}"></div><div class="field"><label>Current tick</label><input id="admTick" type="number" min="1" max="10000" value="${state.tick}"></div></div><div class="admin-actions"><button class="btn primary" data-admin="settings">SAVE ROUND SETTINGS</button><span id="roundSettingsSaveStatus" role="status" aria-live="polite">${state.adminRoundSavedAt?'✓ Settings saved · '+new Date(state.adminRoundSavedAt).toLocaleTimeString():''}</span><button class="btn" data-planet-tools="research">UNLOCK ALL RESEARCH FOR THIS PLANET</button><button class="btn" data-planet-tools="construction">ADD ONE OF EACH CONSTRUCTION</button><button class="btn" data-admin="advance">ADVANCE ONE TICK</button><button class="btn warn" data-admin="resetplanets">RESET DEFAULT PLANETS</button></div></section>`;}else if(adminTab==='planets'){content=adminPlanetEditorHTML(selected);}else if(adminTab==='ships'){const race=state.adminShipRaceFilter||state.race||'Terran',rows=Object.entries(SHIPS).filter(([,d])=>race==='All'||d.race===race);const abbr=Object.fromEntries(Object.entries(SHIP_CLASS_TARGET).map(([k,v])=>[v,k]));content=`<section class="panel"><div class="ph"><div class="pt">SHIP STAT CONFIGURATION · ${rows.length} SHIPS</div><span class="meta">CHANGES APPLY TO PRODUCTION, COMBAT, FLEETS & CALCULATOR</span></div><div class="controls"><div class="field"><label>Race filter</label><select id="admShipRaceFilter">${['Terran','Cathaar','Xandathrii','Zikonian','Eitraides','All'].map(r=>`<option ${race===r?'selected':''}>${r}</option>`).join('')}</select></div><button class="btn primary" data-admin="saveships">SAVE SHIP STATS</button><button class="btn" data-admin="resetships">RESTORE OFFICIAL STATS</button></div>${shipRaceLegendHTML()}<div class="note" style="margin:0 12px 12px">Edit values and save to apply immediately. Guns multiply damage; armour, initiative, target classes, role, costs, and ETA are used by the local simulation. E/R, A/C, D/C, cloak, and role are recorded for the ship roster and round setup.</div><div class="table-wrap"><table class="table ship-admin-table"><thead><tr><th>Ship</th><th>Race</th><th>Class</th><th>T1</th><th>T2</th><th>T3</th><th>Type</th><th>Cloak</th><th>Init</th><th>Guns</th><th>Arm</th><th>Dmg</th><th>Pop dmg%</th><th>E/R</th><th>Metal</th><th>Crystal</th><th>Eonium</th><th>A/C</th><th>D/C</th><th>ETA</th></tr></thead><tbody>${rows.map(([id,d])=>{const targets=[...(d.targetSlots||d.target)];return `<tr data-ship-race="${esc(d.race)}"><td><input data-shipstat="${id}" data-field="name" value="${esc(d.name)}"></td><td><span class="race-code-badge" data-ship-race="${esc(d.race)}">${esc(d.race)}</span></td><td><select data-shipstat="${id}" data-field="class">${['Fighter','Corvette','Frigate','Destroyer','Cruiser','Battleship'].map(x=>`<option ${d.class===x?'selected':''}>${x}</option>`).join('')}</select></td>${[0,1,2].map(i=>`<td><select data-shipstat="${id}" data-field="target${i}"><option value="">—</option>${Object.values(SHIP_CLASS_TARGET).map(x=>`<option value="${abbr[x]}" ${targets[i]===x?'selected':''}>${abbr[x]}</option>`).join('')}</select></td>`).join('')}<td><select data-shipstat="${id}" data-field="type">${['Norm','EMP','Pod','Struc','Steal'].map(x=>`<option ${d.type===x?'selected':''}>${x}</option>`).join('')}</select></td><td><input type="checkbox" data-shipstat="${id}" data-field="cloaked" ${d.cloaked?'checked':''}></td>${[['initiative',d.initiative],['guns',d.guns],['armour',d.armour],['damage',d.damage],['populationDamage',['Cruiser','Battleship'].includes(d.class)?(d.populationDamage??0.1):''],['er',d.er],['metal',d.cost.metal],['crystal',d.cost.crystal],['eonium',d.cost.eonium],['ac',d.ac],['dc',d.dc],['eta',d.eta]].map(([field,val])=>`<td><input type="number" min="0" step="${field==='populationDamage'?'0.01':'1'}" ${field==='populationDamage'?'max="100"':''} data-shipstat="${id}" data-field="${field}" value="${val}" ${field==='populationDamage'&&!['Cruiser','Battleship'].includes(d.class)?'disabled':''}></td>`).join('')}</tr>`}).join('')}</tbody></table></div></section>`;}else if(adminTab==='tools'){content=adminPlanetToolsHTML();}else if(adminTab==='havoc'){content=adminHavocHTML();}else{content=`<section class="panel"><div class="ph"><div class="pt">ADVANCED ROUND STATE · JSON</div><span class="meta">EDIT EVERY FIELD, THEN APPLY</span></div><div class="admin-form" style="display:block"><textarea id="adminJson" spellcheck="false" placeholder="Load the current snapshot to edit the complete round state."></textarea></div><div class="admin-actions"><button class="btn" data-admin="snapshot">LOAD CURRENT SNAPSHOT</button><button class="btn" data-admin="copyjson">COPY JSON</button><button class="btn primary" data-admin="applyjson">APPLY JSON STATE</button></div><div class="note" style="margin:12px">Admin changes affect this browser's local practice round. Export the snapshot before major edits so you can restore it if needed.</div></section>`;}if(adminTab==='state')content=tickerControlsHTML()+content;if(adminTab==='state')content+='<section class="panel round-state-reset" style="margin-top:14px"><div class="ph"><div class="pt">RESET ROUND</div><span class="meta">GAME ADMIN ONLY</span></div><div class="note" style="margin:12px">Deletes and regenerates all planets, alliances, intel, scans, quests and game news. Accounts and passwords remain. You must confirm before the reset runs.</div><div class="admin-actions"><button class="btn warn" data-open-round-reset>RESET ROUND</button></div></section>';el.innerHTML='<div class="admin-planet-tools-nav controls"><button class="btn" data-admin-tab="round">ROUND SETUP</button><button class="btn" data-admin-tab="tools">PLANET TOOLS</button><button class="btn" data-admin-tab="havoc">HAVOC</button></div>'+content;if(adminTab==='planets')el.innerHTML=adminGalaxyBrowserHTML()+el.innerHTML;}

function saveAdminSettings(){const num=id=>Number(document.getElementById(id).value);state.config.roundName=document.getElementById('admRoundName').value.trim()||'The Vesper Reach';state.race=document.getElementById('admRaceSet').value;const home=state.galaxy.find(p=>p.player);if(home)home.race=state.race;state.roundLength=Math.max(1,num('admRoundLength')||672);state.config.tickHours=Math.max(.02,Math.min(24,num('admTickHours')||1));state.config.protectionTicks=Math.max(0,num('admProtection')||0);state.config.incomeMultiplier=Math.max(0,num('admIncome'));state.config.researchMultiplier=Math.max(0,num('admResearch'));state.config.productionMultiplier=Math.max(0,num('admProduction'));state.tick=Math.max(1,Math.min(state.roundLength,num('admTick')||state.tick));state.protectionTicks=state.config.protectionTicks;state.nextTickAt=Date.now()+gameTickMs();state.adminRoundSavedAt=Date.now();addNews('Administrator updated round rules.','warn');update();const status=document.getElementById('roundSettingsSaveStatus');if(status)status.textContent='✓ Round settings saved · '+new Date(state.adminRoundSavedAt).toLocaleTimeString();notify('Round settings saved.');}
function saveAdminPlanet(){const p=state.galaxy.find(x=>x.id===state.adminSelected);if(!p)return;const previous=copy(p);const coords=chosenAdminCoordinates();if(!coords)return notify('Choose a sector and galaxy from 01–100 and a planet slot from 01–10.',true);if(state.galaxy.some(other=>other.id!==p.id&&other.coords===coords))return notify('That planet slot is already occupied. Choose an empty slot.',true);const v=id=>Math.max(0,Number(document.getElementById(id).value)||0);p.name=document.getElementById('admName').value.trim()||p.name;p.ruler=document.getElementById('admRuler').value.trim()||p.ruler;if(!p.player)p.race=document.getElementById('admRace').value.trim()||'Terran';p.alliance=document.getElementById('admAlliance').value.trim()||'Unaffiliated';movePlanet(p,coords);if(p.player){const [x,y]=coords.split(':').map(Number);state.browserCoords={x,y};}p.exiled=document.getElementById('admExiled').value==='true';p.roids=p.roids||{};p.resources=p.resources||{};p.ships=p.ships||{};for(const id of Object.keys(RES)){p.roids[id]=v('admRoid-'+id);p.resources[id]=v('admRes-'+id);}for(const [id,d] of Object.entries(SHIPS))if(d.race===(p.player?state.race:p.race))p.ships[id]=v('admShip-'+id);p.structures=v('admStructures');if(p.player){state.xp=v('admXp');state.resources={...p.resources};state.roids={...p.roids};for(const id of Object.keys(SHIPS)){state.fleets.base[id]=p.ships[id];state.ships[id]=p.ships[id];}}else p.xp=v('admXp');syncEditedAllianceMember(p,previous);addNews(`Administrator edited ${p.name}.`,'warn');update();if(typeof syncPlanetDirectory==='function')syncPlanetDirectory();notify('Planet saved.');}
function saveAdminShipStats(){const inputs=[...document.querySelectorAll('[data-shipstat]')],changed=new Set(inputs.map(x=>x.dataset.shipstat));const classKey={Fighter:'fighter',Corvette:'corvette',Frigate:'frigate',Destroyer:'destroyer',Cruiser:'destroyer',Battleship:'siege'};const typeToPod=type=>type==='Pod'||type==='Steal';for(const id of changed){const d=SHIPS[id];if(!d)continue;const vals=Object.fromEntries(inputs.filter(x=>x.dataset.shipstat===id).map(x=>[x.dataset.field,x.type==='checkbox'?x.checked:x.value]));for(const field of ['initiative','guns','armour','damage','er','ac','dc','eta','metal','crystal','eonium'])vals[field]=Math.max(0,Number(vals[field])||0);d.name=String(vals.name||d.name).trim().slice(0,36)||d.name;d.class=vals.class||d.class;d.targetSlots=[0,1,2].map(i=>SHIP_CLASS_TARGET[vals['target'+i]]||'');d.target=d.targetSlots.filter(Boolean);d.type=vals.type||d.type;d.pod=typeToPod(d.type);d.cloaked=!!vals.cloaked;d.initiative=vals.initiative;d.guns=Math.max(1,vals.guns);d.armour=vals.armour;d.damage=vals.damage;d.populationDamage=['Cruiser','Battleship'].includes(d.class)?Math.max(0,Math.min(100,Number(vals.populationDamage)||0)):null;d.populationDamageUnit='percent';d.er=vals.er;d.ac=vals.ac;d.dc=vals.dc;d.eta=Math.max(1,vals.eta);d.cost={metal:vals.metal,crystal:vals.crystal,eonium:vals.eonium};d.research=classKey[d.class];d.factory=['Fighter','Corvette'].includes(d.class)?'lightFactory':['Frigate','Destroyer','Cruiser'].includes(d.class)?'mediumFactory':'heavyFactory';state.shipStatOverrides[id]=JSON.parse(JSON.stringify(d));}state.adminShipRaceFilter=document.getElementById('admShipRaceFilter').value;update();notify(`Saved ${changed.size} ship definitions. New production orders and combat use these stats.`);}
function adminAction(action){if(action==='saveships')return saveAdminShipStats();if(action==='resetships'){state.shipStatOverrides={};loadOfficialShipStats();return update();}if(action==='settings')return saveAdminSettings();if(action==='selectPlanet'){state.adminSelected=document.getElementById('adminPlanetSelect').value;return renderAdmin();}if(action==='saveplanet')return saveAdminPlanet();if(action==='advance'){tickOnce('practice');return notify(`Admin advanced to tick ${state.tick}.`);}if(action==='adddummy')return addAdminDummyMember();if(action==='addplanet'){if(state.galaxy.length>=40)return notify('Planet capacity reached (40).',true);const i=state.galaxy.length+1,id='custom'+Date.now(),type=rollAvailableLocalWorld();state.galaxy.push({id,planetType:type.id,population:type.basePopulation,publicPopulation:type.basePopulation,name:type.canonicalName||'New Planet '+i,ruler:'Unassigned',race:'Terran',alliance:'Unaffiliated',coords:`${homeGalaxy()}:${String(i).padStart(2,'0')}`,roids:{metal:0,crystal:0,eonium:0},resources:{metal:0,crystal:0,eonium:0},ships:Object.fromEntries(Object.keys(SHIPS).map(x=>[x,0])),xp:0,structures:0});state.adminSelected=id;return update();}if(action==='deleteplanet'){if(state.adminSelected==='home')return notify('The home planet must remain in the practice universe.',true);state.galaxy=state.galaxy.filter(p=>p.id!==state.adminSelected);state.adminSelected='home';return update();}if(action==='resetplanets'){state.galaxy=copy(PLANETS);state.galaxy.forEach(p=>{if(p.ships)p.ships=normalizeFleet(p.ships);});state.adminSelected='home';return update();}if(action==='snapshot'){document.getElementById('adminJson').value=JSON.stringify(state,null,2);return;}if(action==='copyjson')return copyText(document.getElementById('adminJson').value||JSON.stringify(state,null,2));if(action==='applyjson'){try{const imported=JSON.parse(document.getElementById('adminJson').value);if(!imported||!Array.isArray(imported.galaxy)||!imported.galaxy.length||imported.galaxy.length>40||!imported.resources||!imported.roids||!imported.buildings||!imported.research||!imported.fleets||!imported.workforce||!imported.config||!imported.alliance||!imported.politics||!imported.waves)throw new Error('Snapshot is missing required round fields or exceeds the 40-planet limit.');for(const k of Object.keys(RES))if(!Number.isFinite(Number(imported.resources[k]))||!Number.isFinite(Number(imported.roids[k])))throw new Error(`Invalid ${k} value.`);state=imported;state.userSettings={skinRace:'Neutral',keepMenuUnfolded:false,allianceTaxEnabled:false,allianceScansEnabled:false,shareScansToAll:false,autoClaimQuests:false,...(state.userSettings||{})};state.userSettings.keepMenuUnfolded=!!state.userSettings.keepMenuUnfolded;if(!UI_THEME_VALUES.includes(state.userSettings.skinRace))state.userSettings.skinRace='Neutral';state.alliance.fortress={strongholdGalaxy:'',lastDistorterTick:0,anarchyUntilTick:0,anarchyEnded:false,...(state.alliance.fortress||{})};state.alliance.structures={active:[],cooldowns:{},history:[],...(state.alliance.structures||{})};state.alliance.structures.active=state.alliance.structures.active||[];state.alliance.structures.cooldowns=state.alliance.structures.cooldowns||{};state.alliance.structures.history=state.alliance.structures.history||[];state.alliance.wars=state.alliance.wars||[];state.structurePlanets=state.structurePlanets||[];state.adminSelected='home';applyShipStatOverrides();update();notify('Complete round state applied.');}catch(err){notify(`JSON not applied: ${err.message}`,true);}return;}}

function navigate(page){if(!window.isStaffWorkspace&&!window.useLegacyStaffView&&['admin','adminAlliances','adminMultihunters','adminControl','adminRound','adminPlanets','adminShips','adminState','support'].includes(page)){location.href='/staff.html#'+(page==='adminAlliances'?'alliances':page==='adminMultihunters'?'multihunters':page==='support'?'tickets':'control');return;}const adminPages={adminAlliances:'alliances',adminMultihunters:'multihunters',adminControl:'control',adminRound:'control',adminPlanets:'planets',adminShips:'ships',adminState:'control'};let navPage=['adminRound','adminState','adminPlanets','adminShips'].includes(page)?'adminControl':page;if(adminPages[page]){adminTab=adminPages[page];page='admin';renderAdmin();}else if(page==='admin'){navPage=Object.keys(adminPages).find(k=>adminPages[k]===adminTab)||'adminRound';renderAdmin();}if(page==='galaxy'&&!state.galaxyBrowserVisited){const home=state.galaxy.find(p=>p.player)||state.galaxy[0];const [x,y]=home.coords.split(':').map(Number);state.browserCoords={x,y};state.galaxyBrowserVisited=true;renderGalaxyBrowser();}if(page==='miday'&&typeof buildMidayPage==='function'){buildMidayPage();loadMidayScans();}document.querySelectorAll('.page').forEach(x=>x.classList.toggle('active',x.id==='page-'+page));document.querySelectorAll('button[data-page]').forEach(x=>x.classList.toggle('active',x.dataset.page===navPage));const active=document.querySelector(`button[data-page="${page}"]`);const crumb=document.getElementById('crumb');if(crumb)crumb.textContent=({adminControl:'ADMIN CONTROLCENTER',adminRound:'ADMIN CONTROLCENTER',adminPlanets:'PLANETS',adminShips:'SHIP STATS',adminState:'ROUND STATE'})[navPage]||page.toUpperCase();if(page==='galaxyForums'&&typeof renderForums==='function'){forumScope='galaxy';forumThread='';renderForums();refreshForumQuestCounts();}if(page==='forums'&&typeof renderForums==='function'){forumScope='community';forumThread='';renderForums();}window.scrollTo({top:0,behavior:'smooth'});}

document.addEventListener('click',e=>{if(e.target.closest('[data-galaxy-origin]')){state.browserCoords={x:1,y:1};renderGalaxyBrowser();save();}const step=e.target.closest('[data-galaxy-step]');if(step){const delta=Number(step.dataset.galaxyStep)||0;state.browserCoords=state.browserCoords||{x:7,y:4};state.browserCoords.x=Math.max(1,Math.min(100,state.browserCoords.x+delta));renderGalaxyBrowser();save();}const qscan=e.target.closest('[data-quickscan]');if(qscan){const target=qscan.dataset.target;if(!state.galaxy.some(p=>p.id===target)){notify('Scans are available for planets in your current galaxy only.',true);return;}const p=state.galaxy.find(x=>x.id===target);state.waves.targetCoords=Object.fromEntries(['x','y','z'].map((k,i)=>[k,p.coords.split(':')[i]||'01']));navigate('waves');renderWaves();save();runScan(qscan.dataset.quickscan);}});
document.getElementById('galaxyCoordinateForm').addEventListener('submit',e=>{e.preventDefault();const raw=document.getElementById('galaxyCoordinateInput').value.trim(),m=raw.match(/^(\d{1,3})\s*[: ,]\s*(\d{1,3})$/);if(!m)return notify('Enter galaxy coordinates as X:Y, for example 07:04.',true);const x=Number(m[1]),y=Number(m[2]);if(x<1||x>100||y<1||y>100)return notify('Galaxy coordinates must be between 01 and 100.',true);state.browserCoords={x,y};save();renderGalaxyBrowser();});
document.addEventListener('click',e=>{const b=e.target.closest('#nav [data-page],#developmentBanner [data-page]');if(b)navigate(b.dataset.page);});document.addEventListener('click',e=>{
const b=e.target.closest('[data-goto]');if(b)navigate(b.dataset.goto);
const mine=e.target.closest('[data-mine]');if(mine){const id=mine.dataset.mine,input=document.getElementById('mine-'+id),qty=Math.max(1,Math.floor(Number(input.value)||1)),cur=state.roids[id]||0;if(cur+qty>mineLimit())return notify('Mining capacity reached. Research Cargo Transfers to increase it.',true);const cost=costAsteroids(cur,qty);if(state.resources[id]<cost)return notify(`Need ${nfmt(cost)} ${RES[id].label} to initiate ${qty} asteroid${qty===1?'':'s'}.`,true);state.resources[id]-=cost;state.roids[id]+=qty;addNews(`${qty} ${RES[id].label.toLowerCase()} asteroid${qty===1?'':'s'} initiated.`,'good');update();notify('Asteroid mining initiated.');refreshPageAfterOrder();}
const build=e.target.closest('[data-build]');if(build)startConstruction(build.dataset.build);
const cancelBuildBtn=e.target.closest('[data-cancelbuild]');if(cancelBuildBtn)cancelBuild(cancelBuildBtn.dataset.cancelbuild);
const tech=e.target.closest('[data-research]');if(tech)startResearch(tech.dataset.research);
const cancelTech=e.target.closest('[data-cancelresearch]');if(cancelTech)cancelResearch();
const fillShip=e.target.closest('[data-ship-target]');if(fillShip){const id=fillShip.dataset.shipTarget,target=Number(fillShip.dataset.targetTotal)||0,input=document.getElementById('qty-'+id),needed=target-shipTotal(id);if(input&&needed>0){input.value=Math.min(20000,needed);updateShipPreview(id);}else if(needed<=0)notify('Your current fleets already meet that target.',true);}const order=e.target.closest('[data-shiporder]');if(order)orderShips(order.dataset.shiporder);
const rec=e.target.closest('[data-cancelproduction]');if(rec){const o=rec.dataset.cancelproduction==='queue'?state.productionQueue.pop():state.production; if(rec.dataset.cancelproduction==='active'){state.production=null;if(state.productionQueue.length)state.production=state.productionQueue.shift();}if(o){for(const [k,v] of Object.entries(o.cost))state.resources[k]+=Math.floor(v*.5);addNews('Ship production cancelled. Half of its resource cost was refunded.','warn');update();}}
const recall=e.target.closest('[data-recall]');if(recall)recallMission(recall.dataset.recall);
const inspect=e.target.closest('[data-inspect]');if(inspect)inspectPlanet(inspect.dataset.inspect);
const prep=e.target.closest('[data-prepareattack]');if(prep)prepareAttack(prep.dataset.prepareattack);
if(e.target.closest('[data-close]'))closeModal();
});
document.getElementById('tickButton').addEventListener('click',simulateTick);document.getElementById('guideButton').addEventListener('click',showGuide);document.getElementById('saveBehavior').addEventListener('click',()=>{state.fleetBehavior=document.getElementById('baseBehavior').value;addNews(`Base fleet behaviour set to ${state.fleetBehavior==='hide'?'Run and Hide':'Stay Home and Fight'}.`);update();notify('Fleet behaviour saved.');});document.getElementById('transferButton').addEventListener('click',transferShips);document.getElementById('launchButton').addEventListener('click',launchMission);document.getElementById('assignButton').addEventListener('click',()=>{const vals={};document.querySelectorAll('[data-workforce]').forEach(x=>vals[x.dataset.workforce]=Number(x.value));const total=Object.values(vals).reduce((a,b)=>a+b,0);if(!validWorkforceAssignments(vals))return notify(`Use whole percentages within each department limit. Total allocation cannot exceed ${workforceAllocationLimit()}%.`,true);state.workforce=vals;addNews('Population assignments updated. Workforce bonuses apply to the next tick.','good');update();notify('Workforce assigned.');});document.getElementById('populationSliders').addEventListener('input',e=>{if(e.target.matches('[data-workforce]')){document.getElementById('out-'+e.target.dataset.workforce).textContent=e.target.value+'%';const total=[...document.querySelectorAll('[data-workforce]')].reduce((a,x)=>a+Number(x.value),0);document.getElementById('allocationTotal').textContent=total+'% assigned · '+Math.max(0,workforceAllocationLimit()-total)+'% available (pool '+workforceAllocationLimit()+'%)';document.getElementById('allocationTotal').style.color=total<=workforceAllocationLimit()?'var(--green)':'var(--orange)';}});document.getElementById('modal').addEventListener('click',e=>{if(e.target.id==='modal')closeModal();});document.getElementById('resetButton').addEventListener('click',()=>showModal(`<div class="modal-head"><h3>ARE YOU SURE? RESET ROUND</h3><button class="x" data-close>×</button></div><div class="modal-body"><p>Game-admin reset: removes every planet, dummy and placeholder, and clears the round. Accounts and reserved Owner keys remain. All players register a new charter with a different assigned world; the ticker starts stopped. Type RESET to confirm.<input id="gameResetConfirmation" placeholder="RESET"></p></div><div class="modal-foot"><button class="btn" data-close>CANCEL</button><button class="btn warn" id="confirmReset">RESET ROUND</button></div>`));document.addEventListener('click',async e=>{if(e.target.id==='confirmReset'){if(!window.isGameAdmin)return notify('Only game admins can reset the shared round.',true);try{await portalRequest('reset',{confirmation:document.getElementById('gameResetConfirmation')?.value});localStorage.removeItem(SAVE_KEY);localStorage.removeItem(LEGACY_KEY);location.reload();}catch(error){notify(error.message,true);}}});

document.addEventListener('click',e=>{const tab=e.target.closest('[data-atab]');if(tab){allianceTab=tab.dataset.atab;renderAlliance();}const act=e.target.closest('[data-alliance]');if(act){if(act.dataset.alliance==='respond')respondDefence();else allianceAction(act.dataset.alliance,act);}const open=e.target.closest('[data-openbcalc]');if(open){const c=state.alliance.calls.find(x=>x.id===open.dataset.openbcalc);if(c)window.bcalcResult=`<b>DEFENCE CALL</b><br>${esc(c.planet)} · ETA ${c.eta}<br>${esc(c.notes)}<br>Threat fleet count: ${c.attackerCount}`;allianceTab='bcalc';renderAlliance();}const parse=e.target.closest('[data-parse]');if(parse){const side=parse.dataset.parse,text=document.getElementById(side==='a'?'parseA':'parseD').value,counts=parseShipReport(text);window.bcalc=window.bcalc||{a:{},d:{}};window.bcalc[side]=counts;renderAlliance();notify('Ship counts parsed into the calculator.');}const calc=e.target.closest('[data-calculate]');if(calc)calculateBattle();const copybtn=e.target.closest('[data-copycalc]');if(copybtn)copyText(bcalcCopy(copybtn.dataset.copycalc));if(e.target.closest('[data-universe-clear]')){state.universeSearch='';state.universeFilter='all';renderUniverse();}const admTab=e.target.closest('[data-admin-tab]');if(admTab){adminTab=admTab.dataset.adminTab;renderAdmin();}const claim=e.target.closest('[data-claimquest]');if(claim)claimQuest(claim.dataset.claimquest);const adm=e.target.closest('[data-admin]');if(adm)adminAction(adm.dataset.admin);const politics=e.target.closest('[data-politics]');if(politics)politicsAction(politics.dataset.politics);const gfund=e.target.closest('[data-gfund]');if(gfund)galaxyFundAction(gfund.dataset.gfund);const approve=e.target.closest('[data-approveexile]');if(approve)approveExile(approve.dataset.approveexile);const scan=e.target.closest('[data-scan]');if(scan)runScan(scan.dataset.scan);if(e.target.closest('[data-galaxyscan]'))runGalaxyScan();const cp=e.target.closest('[data-copyscan]');if(cp){const sc=state.waves.scans.find(x=>x.id===cp.dataset.copyscan);if(sc)copyText(`${sc.name} · ${sc.targetName}${sc.anonymous?'':' · '+sc.coords}\\n${sc.text}`);}const toggle=e.target.closest('[data-coords]');if(toggle){const sc=state.waves.scans.find(x=>x.id===toggle.dataset.coords);if(sc){sc.anonymous=!sc.anonymous;update();}}const del=e.target.closest('[data-deletescan]');if(del){state.waves.scans=state.waves.scans.filter(x=>x.id!==del.dataset.deletescan);update();}if(e.target.closest('[data-politics]')){} });
document.addEventListener('input',e=>{if(e.target.id==='universeSearch'){state.universeSearch=e.target.value;renderUniverse();}if(e.target.id==='newsSearch'){state.newsSearch=e.target.value;renderNews();save();}if(e.target.matches('[data-shipqty]')){state.shipOrderAmounts=state.shipOrderAmounts||{};state.shipOrderAmounts[e.target.dataset.shipqty]=e.target.value;save();updateShipPreview(e.target.dataset.shipqty);}if(e.target.id==='anonymousScan'){state.waves.anonymous=e.target.checked;save();}if(e.target.matches('[data-wave-coord]')){state.waves.targetCoords[e.target.dataset.waveCoord]=e.target.value;save();}if(e.target.matches('[data-cship]')){window.bcalc=window.bcalc||{a:{},d:{}};window.bcalc[e.target.dataset.cship][e.target.dataset.ship]=Number(e.target.value)||0;}});
document.addEventListener('click',e=>{const summary=e.target.closest('#nav .nav-group>summary');if(summary&&state.userSettings?.keepMenuUnfolded){e.preventDefault();document.querySelectorAll('#nav .nav-group').forEach(x=>x.open=true);}},true);
document.addEventListener('click',e=>{const assign=e.target.closest('[data-factory-assign-all]');if(!assign)return;state.factoryAssignments=state.factoryAssignments||{};for(const id of Object.keys(FACTORY_WEIGHTS))state.factoryAssignments[id]=factoryOwned(id);update();notify('All available factories are assigned to production.');});
document.addEventListener('change',e=>{if(e.target.matches('[data-factoryassign]')){const id=e.target.dataset.factoryassign,owned=factoryOwned(id),requested=Math.floor(Number(e.target.value)||0);state.factoryAssignments[id]=Math.max(0,Math.min(owned,requested));update();notify(`${state.factoryAssignments[id]} ${FACTORY_LABELS[id][0]} assigned to production.`);return;}if(e.target.id==='keepMenuUnfolded'){state.userSettings.keepMenuUnfolded=e.target.checked;localStorage.setItem('starfall-menu-unfolded',e.target.checked?'1':'0');applyMenuPreference();save();notify(e.target.checked?'All sidebar sections will stay open.':'Sidebar returned to accordion mode.');}if(e.target.id==='planetRaceSelect'){setPlanetRace(e.target.value);}if(e.target.id==='allianceTaxEnabled'){state.userSettings.allianceTaxEnabled=e.target.checked;save();update();notify(e.target.checked?'Alliance tax enabled for your planet.':'Alliance tax disabled for your planet.');}if(e.target.id==='allianceScansEnabled'){state.userSettings.allianceScansEnabled=e.target.checked;save();renderPlanetSettings();renderWaves();notify(e.target.checked?'Alliance scan sharing enabled.':'Alliance scan sharing disabled.');}if(e.target.id==='skinRaceSelect'){state.userSettings.skinRace=e.target.value;applyRaceSkin();save();renderPlanetSettings();renderQuests();notify(`Interface theme changed to ${themeLabel(e.target.value)}.`);location.hash='planetSettings';location.reload();}if(e.target.id==='admShipRaceFilter'){state.adminShipRaceFilter=e.target.value;renderAdmin();}if(e.target.id==='universeFilter'){state.universeFilter=e.target.value;renderUniverse();}if(e.target.id==='newsAllCategories'){state.newsCategories=Object.fromEntries(NEWS_CATEGORIES.map(x=>[x,e.target.checked]));renderNews();save();}if(e.target.matches('[data-news-category]')){state.newsCategories[e.target.dataset.newsCategory]=e.target.checked;renderNews();save();}if(e.target.matches('[data-trust]')){state.politics.trust[e.target.dataset.trust]=e.target.value;}if(e.target.matches('[data-fundallow]'))state.politics.allowedFund[e.target.dataset.fundallow]=e.target.checked;if(e.target.matches('[data-scan-funding]')){if(!isCurrentScanner())return notify('Only the Alliance HC or an appointed scanner can change scan funding.',true);state.waves.fundSources=state.waves.fundSources||{};state.waves.fundSources['A. Commander']=e.target.dataset.scanFunding;update();notify(`Scan funding switched to ${scanFundLabel(e.target.dataset.scanFunding)}.`);}if(e.target.matches('[data-member-role]'))updateAllianceMemberRank(e.target.dataset.memberRole,e.target.value);});
// Galaxy coordinates retain the existing X:Y representation; planet slots are 1–10.
function galaxyOf(coords){return String(coords||'').split(':').slice(0,2).map(n=>padCoord(Number(n))).join(':');}
function homeGalaxy(){return galaxyOf((state.galaxy.find(p=>p.player)||state.galaxy[0]).coords);}
function memberCoordinates(name){if(name==='A. Commander'){const home=state.galaxy.find(p=>p.player);if(home&&isAllianceMember(name))return home.coords;}const member=state.alliance.members.find(m=>m.name===name);if(!member)return '';const p=state.galaxy.find(p=>p.ruler===name||p.name===member.planet);return p?.coords||member.coords||'';}
function isStrongholdResident(name){return isAllianceMember(name)&&!!state.alliance.fortress.strongholdGalaxy&&galaxyOf(memberCoordinates(name))===state.alliance.fortress.strongholdGalaxy;}
function galaxyHTML(){const key=homeGalaxy(),planets=state.galaxy.filter(p=>galaxyOf(p.coords)===key),rows=galaxyPlanetHTML().match(/<tr>[\s\S]*?<\/tr>/g)||[],bySlot=new Map(planets.map((p,i)=>[Number(p.coords.split(':')[2]),rows[i]]));return Array.from({length:15},(_,i)=>{const slot=i+1;if(slot<=10&&bySlot.has(slot))return bySlot.get(slot);const structure=slot>10?state.structurePlanets.find(p=>galaxyOf(p.coords)===key&&Number(p.slot)===slot):null;return '<tr data-slot="'+slot+'"><td><b>'+ (structure?esc(structure.name):slot<=10?'Empty':'Empty / Reserved')+'</b><small>'+key+':'+padCoord(slot)+'</small></td><td>'+ (structure?esc(structure.ruler||structure.alliance):'—')+'</td><td colspan="5">'+(slot<=10?'Planet slot':'Alliance stronghold structure')+'</td><td>—</td><td>—</td></tr>';}).join('');}
function updateHomeWorldSurvey(){const type=planetTypeFor(state),art=document.getElementById('homePlanetTypeArtwork'),src='/assets/planets/'+type.id+'.svg';if(art?.getAttribute&&art.getAttribute('src')!==src){art.src=src;art.alt=type.name+' orbital survey';}for(const [id,value] of [['homeWorldType',type.name],['homeWorldHabitability',type.habitability+'%'],['homeWorldGrowth',(type.growthPercent>=0?'+':'')+type.growthPercent+'%'],['homeWorldBase',nfmt(type.basePopulation)]]){const e=document.getElementById(id);if(e&&e.textContent!==value)e.textContent=value;}}
function updateHomeCoordinates(){updateHomeWorldSurvey();const home=state.galaxy.find(p=>p.player);if(!home)return;for(const [id,value] of [['headerPlanetName',displayPlanetName(home.name)||'Home Planet'],['homeSceneName',displayPlanetName(home.name)||'Home Planet'],['homeSceneRace','COMMAND PLANET · '+(state.race||home.race||'Terran').toUpperCase()],['homeHeroTitle',(displayPlanetName(home.name)||'Home Planet')+', under your command.'],['homeHeroDescription','Ruler: '+(home.ruler||'Unassigned')+(home.username?' · Commander: '+home.username:'')+' · '+home.coords],['headerPlanetCoords',home.coords],['headerPlanetRuler',home.ruler||'Unassigned'],['headerAccountId',state.accountId||'—'],['headerPlanetTick',String(state.tick).padStart(3,'0')],['headerPlanetScore',nfmt(playerScore())],['headerPlanetXP',nfmt(state.xp)],['headerPlanetValue',nfmt(playerValue())],['homeGalaxyLabel','Planetary command · Galaxy '+homeGalaxy()],['homeSceneCoordinates',home.coords.split(':').join(' : ')],['homeRailCoordinates','REALTIME · PLANET '+home.coords],['homeGalaxyStatusLabel','Galaxy '+homeGalaxy()+' · local practice round']]){const el=document.getElementById(id);if(el)el.textContent=value;}}
function freePlanetCoordinates(excludedGalaxy=''){
  const occupied=new Set(state.galaxy.map(p=>p.coords));
  const [sector]=homeGalaxy().split(':').map(Number);
  for(let offset=1;offset<=100;offset++){
    const y=((Number(homeGalaxy().split(':')[1])-1+offset)%100)+1,key=`${padCoord(sector)}:${padCoord(y)}`;
    if(key===excludedGalaxy)continue;
    for(let z=1;z<=10;z++){const coords=`${key}:${padCoord(z)}`;if(!occupied.has(coords))return coords;}
  }
  return null;
}
function movePlanet(p,coords){const old=p.coords;p.coords=coords;p.exiled=false;for(const m of state.alliance.members)if(m.name===p.ruler||m.planet===p.name)m.coords=coords;for(const a of state.alliance.applicants)if(a.name===p.ruler||a.planet===p.name)a.coords=coords;return old;}
function normalizeGalaxySlots(){
  const occupied=new Set();
  for(const p of state.galaxy){const z=Number(String(p.coords).split(':')[2]);if(z<1||z>10||occupied.has(p.coords)){const coords=freePlanetCoordinates();if(coords)movePlanet(p,coords);}occupied.add(p.coords);}
  for(const p of state.structurePlanets){if(Number(p.slot)===10){const used=new Set(state.structurePlanets.filter(q=>q!==p&&galaxyOf(q.coords)===galaxyOf(p.coords)).map(q=>Number(q.slot)));const slot=[11,12,13,14,15].find(n=>!used.has(n));if(slot){p.slot=slot;p.coords=galaxyOf(p.coords)+':'+padCoord(slot);const effect=state.alliance.structures.active.find(a=>a.id===p.id);if(effect)effect.slot=slot;}}}
}
function calculateSelfExileCost(value,count,galaxyScore,averageScore,free=false){const base=Math.max(0,value)/10,ratio=Math.max(0,galaxyScore)/Math.max(1,Math.trunc(averageScore));const cost=base+Math.trunc(2*(base+1000)*Math.pow(Math.max(0,count)+1,2.5)*Math.pow(ratio,2.5));return Math.ceil(cost*(free?2:1));}
function selfExileCost(forceFree){const scores=new Map();for(const p of state.galaxy){const key=galaxyOf(p.coords);if(key==='01:01'||Number(key.split(':')[0])===200)continue;const counted=Math.max(0,planetScore(p)-(Number(p.galaxyEntryScore)||0));scores.set(key,(scores.get(key)||0)+counted);}const avg=scores.size?[...scores.values()].reduce((a,b)=>a+b,0)/scores.size:1;const current=state.galaxy.filter(p=>galaxyOf(p.coords)===homeGalaxy()).reduce((a,p)=>a+Math.max(0,planetScore(p)-(Number(p.galaxyEntryScore)||0)),0);return calculateSelfExileCost(playerValue(),state.selfExileCount||0,current,avg,forceFree===undefined?state.accountType==='free':forceFree);}
function requestSelfExile(checkbox){
  if(!checkbox.checked)return;
  checkbox.checked=false;
  const home=state.galaxy.find(p=>p.player);if(!home)return;
  const cost=selfExileCost();if(!Number.isSafeInteger(cost)||!Object.keys(RES).every(k=>state.resources[k]>=cost))return notify('Not enough resources for self exile: '+nfmt(cost)+' Metal, Crystal and Eonium required.',true);if(state.missions.length)return notify('All fleets must be at home before self exile.',true);if(!confirm('Exile to a different galaxy for '+nfmt(cost)+' Metal + '+nfmt(cost)+' Crystal + '+nfmt(cost)+' Eonium? Payment goes to the galaxy you are leaving. Fleets, buildings, research and alliance membership are preserved.'))return;
  const oldGalaxy=galaxyOf(home.coords),coords=freePlanetCoordinates(oldGalaxy);
  if(!coords)return notify('No free planet slot is available in another galaxy.',true);
  state.galaxyFunds=state.galaxyFunds||{};const originFund=copy(state.galaxyFund);for(const k of Object.keys(RES)){state.resources[k]-=cost;originFund[k]=(originFund[k]||0)+cost;}state.galaxyFunds[oldGalaxy]=originFund;state.selfExileCount=(state.selfExileCount||0)+1;const old=movePlanet(home,coords);home.galaxyEntryScore=planetScore(home);
  const [x,y]=coords.split(':').map(Number);state.browserCoords={x,y};
  state.politics={...freshState().politics,gc:home.ruler,votes:{[home.ruler]:1},ministers:{},exiles:[],votesToExile:[]};
  state.galaxyFund=copy(state.galaxyFunds[galaxyOf(coords)]||{metal:0,crystal:0,eonium:0,log:[]});
  addNews(`Your planet moved from ${old} to ${coords} by Exile Option.`,'warn');update();
}
function renderGalaxyBrowser(){
  renderGalaxyPlanets();
  const rows=document.getElementById('browserPlanetRows');if(!rows)return;
  const data=browserGalaxyData(),key=`${padCoord(state.browserCoords.x)}:${padCoord(state.browserCoords.y)}`;
  const planetRows=rows.innerHTML.match(/<tr>[\s\S]*?<\/tr>/g)||[];
  const bySlot=new Map(data.planets.map((p,i)=>[Number(p.coords.split(':')[2]),planetRows[i]]));
  const map=document.getElementById('browserPlanetMap');const chips=map.innerHTML.match(/<div class="planet-chip[\s\S]*?<\/div>/g)||[];
  const chipsBySlot=new Map(data.planets.map((p,i)=>[Number(p.coords.split(':')[2]),chips[i]]));
  const rowSlots=[],mapSlots=[];
  for(let slot=1;slot<=15;slot++){
    const structure=slot>10?state.structurePlanets.find(p=>galaxyOf(p.coords)===key&&Number(p.slot)===slot):null;
    if(slot<=10&&bySlot.has(slot)){rowSlots.push(bySlot.get(slot));mapSlots.push(chipsBySlot.get(slot));continue;}
    const label=structure?structure.name:slot<=10?'Empty':'Empty / Reserved';
    rowSlots.push(`<tr class="${structure?'structure-slot-row':'reserved-slot'}" data-slot="${slot}"><td>${padCoord(slot)}</td><td>${structure?esc(structure.ruler||structure.alliance):'—'}</td><td>${structure?'<em>'+esc(label)+'</em>':esc(label)}<small>${key}:${padCoord(slot)}</small></td><td>—</td><td>${structure?esc(structure.alliance):'—'}</td><td colspan="3">${slot<=10?'Planet slot':'Alliance stronghold structure'}</td><td>—</td><td>—</td></tr>`);
    mapSlots.push(`<div class="planet-chip ${structure?'ally':'reserved-slot'}"><i class="planet-dot"></i><span>${padCoord(slot)} · ${esc(label)}</span></div>`);
  }
  rows.innerHTML=rowSlots.join('');map.innerHTML=mapSlots.join('');renderGalaxyIntelOverlay();
  document.getElementById('browserPlanetCount').textContent=`${data.planets.length} PLANETS · 15 SLOTS · ${data.local?'LOCAL DATA':'SIMULATED'}`;
}
function parseCustomScanCoordinates(text){
  const raw=String(text||'').trim();const full=raw.match(/^(\d{1,3})\s*:\s*(\d{1,3})\s*:\s*(\d{1,2})$/),compact=raw.match(/^(\d{1,3})\s*:\s*(\d{1,2})$/);
  const values=full?full.slice(1).map(Number):compact?[Number(homeGalaxy().split(':')[0]),...compact.slice(1).map(Number)]:null;
  if(!values||values[0]<1||values[0]>100||values[1]<1||values[1]>100||values[2]<1||values[2]>15)return null;
  return Object.fromEntries(['x','y','z'].map((k,i)=>[k,padCoord(values[i])]));
}
function applyCustomScanCoordinates(source){
  const input=document.getElementById(source==='paste'?'pasteScanCoordinates':'customScanCoordinates'),coords=parseCustomScanCoordinates(input.value);
  const feedback=document.getElementById('scanCoordinateFeedback');
  if(!coords){feedback.textContent='Invalid coordinates. Enter Galaxy:slot (2:7) or X:Y:Z (07:04:01), with slot 1–15.';return;}
  state.waves.targetCoords=coords;save();renderWaves();document.getElementById('scanCoordinateFeedback').textContent=`Scan target set to ${coords.x}:${coords.y}:${coords.z}. Select a scan below to launch it.`;
}
document.addEventListener('change',e=>{if(e.target.id==='selfExile')requestSelfExile(e.target);});
document.addEventListener('click',e=>{const button=e.target.closest('[data-apply-scan-coordinates]');if(button)applyCustomScanCoordinates(button.dataset.applyScanCoordinates);});

function chosenAdminCoordinates(){const values=['admCoordX','admCoordY','admCoordZ'].map(id=>Number(document.getElementById(id)?.value));return values.every((n,i)=>Number.isInteger(n)&&n>=1&&n<=(i===2?10:100))?values.map(padCoord).join(':'):null;}
function openPlanetEditor(id){if(!state.galaxy.some(p=>p.id===id))return;state.adminSelected=id;save();navigate('adminPlanets');document.getElementById('adminPlanetEditor')?.scrollIntoView?.({behavior:'smooth',block:'start'});document.getElementById('admName')?.focus?.({preventScroll:true});}
document.addEventListener('click',e=>{const edit=e.target.closest('[data-edit-planet]');if(edit)openPlanetEditor(edit.dataset.editPlanet);});
function allianceChoices(){return [...new Set(['Unaffiliated',state.alliance.name,...(state.allianceDirectory||[]).map(a=>a.name),...state.galaxy.map(p=>p.alliance||'Unaffiliated')])].sort();}
function createAllianceLocal(){const name=(document.getElementById('newAllianceName')?.value||'').trim(),tag=(document.getElementById('newAllianceTag')?.value||'').trim().toUpperCase();if(name.length<3||name.length>40)return notify('Use an alliance name of 3–40 characters.',true);if(!/^[A-Z0-9]{2,8}$/.test(tag))return notify('Use a tag of 2–8 letters or numbers.',true);if(allianceChoices().some(n=>n.toLowerCase()===name.toLowerCase()))return notify('An alliance with that name already exists.',true);const home=state.galaxy.find(p=>p.player);if(!home)return;state.allianceDirectory=state.allianceDirectory||[];const old=copy(state.alliance);if(!state.allianceDirectory.some(a=>a.name===old.name))state.allianceDirectory.push(old);const fresh=copy(freshState().alliance);fresh.name=name;fresh.tag=tag;fresh.description=document.getElementById('newAllianceDescription')?.value||'';fresh.recruitmentMessage=document.getElementById('newAllianceRecruitment')?.value||'';fresh.motd=document.getElementById('newAllianceMotd')?.value||'';fresh.fund={metal:0,crystal:0,eonium:0};fresh.members=[{id:'member-'+home.id,planetId:home.id,name:home.username||home.ruler,planet:home.name,coords:home.coords,rank:'Owner',online:true}];fresh.applicants=[];fresh.message='Welcome to '+name+'.';state.alliance=fresh;home.alliance=name;let created=0;for(let i=0;!state.centralPlayerOnly&&i<5&&state.galaxy.length<40;i++){const coords=freePlanetCoordinates();if(!coords)break;state.dummyPlanetCount=(state.dummyPlanetCount||0)+1;const n=state.dummyPlanetCount;state.galaxy.push({id:'dummy-'+Date.now()+'-'+n,name:'Practice Planet '+n,ruler:'Practice Commander '+n,race:'Terran',alliance:'Unaffiliated',coords,roids:{metal:6,crystal:6,eonium:6},resources:{metal:9000,crystal:9000,eonium:9000},ships:normalizeFleet({}),xp:0,structures:0,dummy:true});created++;}state.allianceCreated=true;if(document.getElementById('allianceCreatePanel'))document.getElementById('allianceCreatePanel').open=false;allianceTab='home';addNews('Alliance '+name+' ['+tag+'] created. '+created+' unassigned practice planets are available for Administration.','good');update();navigate('alliance');notify('Alliance created. Assign practice planets from Administration → Planets.');}
function allianceProfile(name){if(name===state.alliance.name)return state.alliance;state.allianceDirectory=state.allianceDirectory||[];let a=state.allianceDirectory.find(a=>a.name===name);if(!a&&name&&name!=='Unaffiliated'){a={...copy(freshState().alliance),name,members:[],applicants:[],fund:{metal:0,crystal:0,eonium:0},wars:[]};state.allianceDirectory.push(a);}return a;}
function syncEditedAllianceMember(p,previous=p){for(const a of [state.alliance,...(state.allianceDirectory||[])])a.members=(a.members||[]).filter(m=>!((m.planetId===p.id||m.planet===previous.name||m.planet===p.name)&&a.name!==p.alliance));const a=allianceProfile(p.alliance);if(!a)return;let m=(a.members||[]).find(m=>m.planetId===p.id||m.planet===previous.name||m.planet===p.name);if(!m){m={id:'member-'+p.id,name:p.player?'A. Commander':p.ruler,rank:p.player?'HC':'Member',online:!!p.player};a.members.push(m);}m.planetId=p.id;m.planet=p.name;m.coords=p.coords;if(!p.player)m.name=p.username||p.ruler;}
function reconcileAllianceMembers(){for(const a of [state.alliance,...(state.allianceDirectory||[])]){a.members=(a.members||[]).filter(m=>{const p=state.galaxy.find(p=>m.planetId===p.id||m.planet===p.name);return !p||p.alliance===a.name;});for(const m of a.members){const p=state.galaxy.find(p=>m.planetId===p.id||m.planet===p.name);if(p){m.planetId=p.id;m.planet=p.name;m.coords=p.coords;}}}for(const p of state.galaxy){const a=allianceProfile(p.alliance);if(a&&!(a.members||[]).some(m=>m.planetId===p.id||m.planet===p.name))syncEditedAllianceMember(p);}}

document.addEventListener('click',e=>{if(e.target.closest('[data-create-alliance]'))createAlliance();});

function addAdminDummyMember(allianceName){
 const name=allianceName||document.getElementById('admDummyAlliance')?.value;
 if(!name||name==='Unaffiliated'||!allianceChoices().includes(name))return notify('Choose an alliance for the dummy member.',true);
 const alliance=name===state.alliance.name?state.alliance:(state.allianceDirectory||[]).find(a=>a.name===name);
 if(state.galaxy.length>=40)return notify('Planet capacity reached (40).',true);
 if((alliance?.members?.length||state.galaxy.filter(p=>p.alliance===name).length)>=40)return notify('Alliance member capacity reached (40).',true);
 const coords=freePlanetCoordinates();if(!coords)return notify('No free planet slot is available.',true);
 state.dummyPlanetCount=(state.dummyPlanetCount||0)+1;const n=state.dummyPlanetCount;
 const p={id:'dummy-'+Date.now()+'-'+n,name:'Practice Planet '+n,ruler:'Practice Commander '+n,race:'Terran',alliance:name,coords,roids:{metal:6,crystal:6,eonium:6},resources:{metal:9000,crystal:9000,eonium:9000},ships:normalizeFleet({}),xp:0,structures:0,dummy:true};
 state.galaxy.push(p);if(alliance){alliance.members=alliance.members||[];alliance.members.push({id:'member-'+p.id,name:p.ruler,planet:p.name,coords,rank:'Member',online:false});}
 state.adminSelected=p.id;const [x,y]=coords.split(':').map(Number);state.adminBrowserCoords={x,y};
 addNews('Administrator added '+p.ruler+' to '+name+'.','good');update();if(typeof syncPlanetDirectory==='function')syncPlanetDirectory();notify('Dummy member added to '+name+'.');
}
function adminGalaxyBrowserHTML(){
 const [hx,hy]=homeGalaxy().split(':').map(Number),c=state.adminBrowserCoords||{x:hx,y:hy},key=padCoord(c.x)+':'+padCoord(c.y);
 const options=value=>Array.from({length:100},(_,i)=>'<option value="'+(i+1)+'" '+(i+1===Number(value)?'selected':'')+'>'+padCoord(i+1)+'</option>').join('');
 const rows=Array.from({length:15},(_,i)=>{const slot=i+1,p=slot<=10?state.galaxy.find(p=>p.coords===key+':'+padCoord(slot)):state.structurePlanets.find(p=>galaxyOf(p.coords)===key&&Number(p.slot)===slot);return '<tr><td>'+padCoord(slot)+'</td><td>'+esc(p?.name||(slot<=10?'Empty':'Empty / Reserved'))+'</td><td>'+esc(p?.ruler||'—')+'</td><td>'+esc(p?.alliance||'—')+'</td><td>'+(p&&slot<=10?'<button class="btn" data-edit-planet="'+esc(p.id)+'" aria-label="Edit '+esc(p.name)+'">🔧 EDIT</button>':'—')+'</td></tr>';}).join('');
 return '<section class="panel admin-galaxy-browser" style="margin-bottom:14px"><div class="ph"><div class="pt">GALAXY BROWSER · '+key+'</div><span class="meta">ADMIN · SAVED PRACTICE PLANETS · 15 SLOTS</span></div><div class="controls"><button class="btn" data-admin-galaxy-step="-1">← PREVIOUS</button><div class="field"><label for="admBrowserX">Sector</label><select id="admBrowserX">'+options(c.x)+'</select></div><div class="field"><label for="admBrowserY">Galaxy</label><select id="admBrowserY">'+options(c.y)+'</select></div><button class="btn primary" data-admin-browse>VIEW GALAXY</button><button class="btn" data-admin-galaxy-step="1">NEXT →</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Slot</th><th>Planet / structure</th><th>Ruler</th><th>Alliance</th><th>Edit planet</th></tr></thead><tbody>'+rows+'</tbody></table></div></section>';
}
function browseAdminGalaxy(step=0){let x=Number(document.getElementById('admBrowserX')?.value),y=Number(document.getElementById('admBrowserY')?.value);if(!Number.isInteger(x)||!Number.isInteger(y)||x<1||x>100||y<1||y>100)return;y+=step;if(y>100){y=1;x=x===100?1:x+1;}if(y<1){y=100;x=x===1?100:x-1;}state.adminBrowserCoords={x,y};save();renderAdmin();}
function questOfficeIcon(id){if(id==='ticker')return questGoalIcon('ticker:start');if(id==='alliance')return questGoalIcon('alliance');const categories={education:'RESEARCH',defense:'FLEET',treasury:'ECONOMY',development:'DEVELOPMENT',security:'INTELLIGENCE',chiefs:'POLITICS',veterans:'ALLIANCE',fleet:'FLEET',clandestine:'INTELLIGENCE',intelligence:'INTELLIGENCE',civilCovert:'INTELLIGENCE',habitats:'DEVELOPMENT',special:'SYSTEM'};return newsIcon(categories[id]||'SYSTEM');}
document.addEventListener('click',e=>{const browse=e.target.closest('[data-admin-browse]'),step=e.target.closest('[data-admin-galaxy-step]');if(browse||step)browseAdminGalaxy(step?Number(step.dataset.adminGalaxyStep):0);});

function adminAllianceDummyHTML(){if(!window.isGameAdmin)return '';const candidates=state.galaxy.filter(p=>p.dummy&&p.alliance==='Unaffiliated');return '<section class="panel" style="margin-bottom:14px"><div class="ph"><div class="pt">ADD DUMMY MEMBERS</div><span class="meta">GAME ADMIN ONLY</span></div><div class="controls"><div class="field"><label for="allianceDummyPlanet">Unassigned dummy planet</label><select id="allianceDummyPlanet">'+(candidates.length?candidates.map(p=>'<option value="'+esc(p.id)+'">'+esc(p.name)+' · '+p.coords+'</option>').join(''):'<option value="">No unassigned dummy planets</option>')+'</select></div><button class="btn primary" data-assign-alliance-dummy '+(candidates.length?'':'disabled')+'>ADD TO ALLIANCE</button><button class="btn" data-new-alliance-dummy>CREATE NEW DUMMY MEMBER</button><button class="btn" data-goto="adminPlanets">OPEN PLANET ADMIN</button></div></section>';}
function assignAllianceDummy(){if(!window.isGameAdmin)return;const p=state.galaxy.find(p=>p.id===document.getElementById('allianceDummyPlanet')?.value&&p.dummy&&p.alliance==='Unaffiliated');if(!p)return notify('Choose an unassigned dummy planet.',true);if(state.alliance.members.length>=40)return notify('Alliance member capacity reached (40).',true);p.alliance=state.alliance.name;syncEditedAllianceMember(p);addNews('Administrator assigned '+p.ruler+' to '+state.alliance.name+'.','good');update();notify('Dummy member added.');}
document.addEventListener('click',e=>{if(e.target.closest('[data-assign-alliance-dummy]'))assignAllianceDummy();if(e.target.closest('[data-new-alliance-dummy]')&&window.isGameAdmin){addAdminDummyMember(state.alliance.name);}});

function adminPlanetToolsHTML(){const home=state.galaxy.find(p=>p.player),research=home.player?state.research:(home.research||{}),buildings=home.player?state.buildings:(home.buildings||{});return '<section class="panel"><div class="ph"><div class="pt">PLANET TOOLS · '+esc(home.name)+'</div><span class="meta">THIS PLANET · '+home.coords+'</span></div><div class="controls"><button class="btn primary" data-planet-tools="research">UNLOCK ALL RESEARCH</button><button class="btn" data-planet-tools="construction">ADD ONE OF EACH CONSTRUCTION</button></div><div class="ph"><div class="pt">RESEARCH LEVELS</div></div><div class="admin-form">'+TECH_TREE.map(t=>'<div class="field"><label for="admTech-'+t.id+'">'+esc(t.name)+' · max '+t.max+'</label><input id="admTech-'+t.id+'" data-admin-tech="'+t.id+'" type="number" min="0" max="'+t.max+'" step="1" value="'+(research[t.id]||0)+'"></div>').join('')+'</div><div class="ph"><div class="pt">CONSTRUCTION COUNTS</div></div><div class="admin-form">'+Object.entries(BUILDINGS).map(([id,b])=>'<div class="field"><label for="admBuild-'+id+'">'+esc(b.name)+'</label><input id="admBuild-'+id+'" data-admin-building="'+id+'" type="number" min="0" max="1000000" step="1" value="'+(buildings[id]||0)+'"></div>').join('')+'</div><div class="admin-actions"><button class="btn primary" data-planet-tools="save">SAVE PLANET OPTIONS</button></div><div class="note" style="margin:12px">These admin overrides apply to the planet named above. Research levels use the listed limits. Saving cancels this planet’s active research and construction orders.</div></section>';}
function applyPlanetTools(action){
 const home=state.galaxy.find(p=>p.player),selected=adminTab==='havoc'?(state.galaxy.find(p=>p.id===state.havocSelected)||home):home;
 if(!['research','construction','save','all'].includes(action))return;
 if(action==='all'&&havocMatrixPresent()){const checked=validateHavocShipMatrix();if(!checked.ok)return notify(checked.error,true);if(state.havocConfirmedSetup!==havocSetupSignature())return notify('Confirm this Havoc setup before applying it. Changes require a new confirmation.',true);}
 if(action==='all')state.havocBackup=copy({biodomeDamage:state.biodomeDamage,population:state.population,research:state.research,buildings:state.buildings,researchActive:state.researchActive,researchProgress:state.researchProgress,construction:state.construction,resources:state.resources,roids:state.roids,fleets:state.fleets,ships:state.ships,tickHours:state.config.tickHours,planets:state.galaxy.map(p=>({id:p.id,biodomeDamage:p.biodomeDamage,population:p.population,research:p.research,buildings:p.buildings,structures:p.structures,resources:p.resources,roids:p.roids,ships:p.ships}))});const targets=action==='all'?state.galaxy:[selected];
 const levels={},counts={};if(action==='save'||action==='all'){for(const t of TECH_TREE)levels[t.id]=Math.max(0,Math.min(t.max,Math.floor(Number(document.getElementById('admTech-'+t.id)?.value)||0)));for(const id of Object.keys(BUILDINGS))counts[id]=Math.max(0,Math.min(1000000,Math.floor(Number(document.getElementById('admBuild-'+id)?.value)||0)));}
 for(const p of targets){const r=p.player?state.research:(p.research=p.research||{}),b=p.player?state.buildings:(p.buildings=p.buildings||{});if(action==='research')for(const t of TECH_TREE)r[t.id]=t.max;else if(action==='construction')for(const id of Object.keys(BUILDINGS))b[id]=(b[id]||0)+1;else{Object.assign(r,levels);Object.assign(b,counts);}p.structures=Object.values(b).reduce((a,v)=>a+Number(v||0),0);if(action==='all')applyHavocEconomy(p);if(p.player&&(action==='research'||action==='save'||action==='all')){state.researchActive=null;state.researchProgress=0;if(action!=='research')state.construction=null;}}
 if(adminTab==='havoc'&&(action==='save'||action==='all')){const minutes=Number(document.getElementById('havocTickMinutes')?.value);if(Number.isFinite(minutes)&&minutes>=1.2&&minutes<=1440){const hours=minutes/60;if(state.config.tickHours!==hours){state.config.tickHours=hours;state.nextTickAt=Date.now()+gameTickMs();}}}
 addNews('Administrator applied planet tools: '+action+' to '+targets.length+' planet(s).','warn');update();notify(action==='all'?'Configuration applied to all planets.':'Planet options applied.');
}
function adminHavocHTML(){let options=adminPlanetToolsHTML();options=options.replace(/<div class="controls">[\s\S]*?<\/div>/,'').replace(/<div class="ph">[\s\S]*?<\/div><span class="meta">[\s\S]*?<\/span><\/div>/,'').replace('SAVE PLANET OPTIONS','APPLY TO ALL').replace('data-planet-tools="save"','data-planet-tools="all"').replace('These admin overrides apply to the planet named above. Research levels use the listed limits. Saving cancels this planet’s active research and construction orders.','Apply to all sets these values instantly on every saved planet and cancels the current planet’s active research and construction orders.');for(const t of TECH_TREE){options=options.replace('<input id="admTech-'+t.id+'"','<label class="havoc-toggle"><input type="checkbox" data-havoc-research="'+t.id+'" '+((state.research[t.id]||0)===t.max?'checked':'')+'> Fully unlocked</label><input id="admTech-'+t.id+'"');}options+=havocEconomyHTML();return '<div class="havoc-board">'+havocPresetControlsHTML()+'<section class="panel"><div class="ph"><div class="pt">HAVOC · ROUND CONTROL BOARD</div><span class="meta">INSTANT · EVERY PLANET</span></div><div class="controls"><div class="field"><label for="havocTickMinutes">Gamespeed · minutes per tick</label><input id="havocTickMinutes" type="number" min="1.2" max="1440" step="0.1" value="'+(state.config.tickHours*60)+'"></div><button class="btn primary" data-planet-tools="all">APPLY TO ALL</button><button class="btn warn" data-havoc-reset '+(state.havocBackup?'':'disabled')+'>RESET TO PREVIOUS</button></div><div class="note" style="margin:12px">Set the controls below, confirm the setup, then Apply to all. Smaller tick intervals run the round faster. Reset restores the configuration from before your latest Havoc application.</div></section>'+options+'</div>';}
function resetHavoc(){const backup=state.havocBackup;if(!backup)return;state.biodomeDamage=backup.biodomeDamage||0;state.population=backup.population??1000;state.research=copy(backup.research);state.buildings=copy(backup.buildings);state.researchActive=backup.researchActive;state.researchProgress=backup.researchProgress;state.construction=copy(backup.construction);state.resources=copy(backup.resources);state.roids=copy(backup.roids);state.fleets=copy(backup.fleets);state.ships=copy(backup.ships);state.config.tickHours=backup.tickHours;state.nextTickAt=Date.now()+gameTickMs();for(const saved of backup.planets){const p=state.galaxy.find(p=>p.id===saved.id);if(!p)continue;for(const key of ['population','biodomeDamage','research','buildings','structures','resources','roids','ships']){if(saved[key]===undefined)delete p[key];else p[key]=copy(saved[key]);}}delete state.havocBackup;addNews('Administrator restored the previous Havoc configuration.','warn');update();notify('Previous configuration restored.');}
document.addEventListener('click',e=>{if(e.target.closest('[data-havoc-reset]'))resetHavoc();});
document.addEventListener('change',e=>{const t=TECH_TREE.find(t=>t.id===e.target.dataset.havocResearch);if(t){document.getElementById('admTech-'+t.id).value=e.target.checked?t.max:0;}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-planet-tools]');if(b)applyPlanetTools(b.dataset.planetTools);});

const HAVOC_CLASSES=['Fighter','Corvette','Frigate','Destroyer','Cruiser','Battleship'];
function havocEconomyHTML(){const input=(id,label,value)=>'<div class="field"><label for="'+id+'">'+esc(label)+'</label><input id="'+id+'" type="number" min="0" max="1000000000000" step="1" value="'+value+'"></div>';return '<section class="panel"><div class="ph"><div class="pt">RESOURCES, ASTEROIDS & POPULATION</div></div><div class="admin-form">'+input('havocBiodomeDamage','Biodome damage (HP / 1000)',state.biodomeDamage||0)+input('havocPopulation','Population (capacity: '+populationCapacity()+')',state.population)+Object.entries(RES).map(([id,r])=>input('havocResource-'+id,r.label+' resources',state.resources[id]||0)+input('havocRoids-'+id,r.label+' asteroids',state.roids[id]||0)).join('')+'</div></section>'+havocShipMatrixHTML()+'<div class="admin-actions"><button class="btn primary" data-planet-tools="all">APPLY TO ALL</button><button class="btn warn" data-havoc-reset '+(state.havocBackup?'':'disabled')+'>RESET TO PREVIOUS</button></div>';}
function applyHavocEconomy(p){const read=id=>Math.max(0,Math.min(1000000000000,Math.floor(Number(document.getElementById(id)?.value)||0)));p.biodomeDamage=Math.min(999,document.getElementById('havocBiodomeDamage')?read('havocBiodomeDamage'):(p.biodomeDamage||0));p.population=Math.min(planetBasePopulation(p)+(p.buildings?.biodome||0)*50-Math.floor(p.biodomeDamage/20),document.getElementById('havocPopulation')?read('havocPopulation'):(p.population||1000));if(p.player){state.population=p.population;state.biodomeDamage=p.biodomeDamage;}p.resources=Object.fromEntries(Object.keys(RES).map(id=>[id,read('havocResource-'+id)]));p.roids=Object.fromEntries(Object.keys(RES).map(id=>[id,read('havocRoids-'+id)]));const ships=normalizeFleet({}),shipMatrix=!!document.getElementById('havocShipSlot-0')?.hasAttribute?.('data-havoc-ship-slot');if(shipMatrix){const rows=Object.entries(SHIPS).filter(([,d])=>d.race===(p.player?state.race:p.race)).slice(0,10);rows.forEach(([id],i)=>ships[id]=Math.min(1000000000,read('havocShipSlot-'+i)));}else for(const cls of HAVOC_CLASSES){const ids=Object.entries(SHIPS).filter(([id,d])=>d.race===(p.player?state.race:p.race)&&d.class===cls).map(([id])=>id),amount=read('havocClass-'+cls);ids.forEach((id,i)=>ships[id]=Math.floor(amount/ids.length)+(i<amount%ids.length?1:0));}p.ships=ships;if(p.player){state.resources={...p.resources};state.roids={...p.roids};state.fleets.base={...ships};state.ships={...ships};}}

function allianceFundHTML(){const a=state.alliance,options=Object.entries(RES).map(([id,r])=>'<option value="'+id+'">'+r.label+'</option>').join('');return '<div class="alliance-grid"><section class="panel"><div class="ph"><div class="pt">ALLIANCE FUND</div><span class="meta">RESOURCE POOL</span></div><div class="summary-list">'+Object.entries(RES).map(([id,r])=>'<div class="summary-line"><span>'+r.label+'</span><b>'+nfmt(a.fund[id]||0)+'</b></div>').join('')+'</div><div class="ph"><div class="pt">DONATE TO ALLIANCE FUND</div></div><div class="controls"><div class="field"><label for="fundResource">Resource</label><select id="fundResource">'+options+'</select></div><div class="field"><label for="fundAmount">Amount from your planet</label><input type="number" id="fundAmount" min="1" step="1" value="500"></div><button class="btn primary" data-alliance="donate">DONATE TO ALLIANCE FUND</button></div><div class="note" style="margin:12px">Resources leave your planet immediately and reach the fund after 8 ticks. Your combined donations of each resource are capped at two ticks of income per 24 hours.</div>'+((a.pendingDonations||[]).length?'<div class="summary-list">'+a.pendingDonations.map(d=>'<div class="summary-line"><span>'+nfmt(d.amount)+' '+RES[d.resource].label+'</span><small>ARRIVES T'+d.tick+'</small></div>').join('')+'</div>':'')+'</section><section class="panel"><div class="ph"><div class="pt">EXCHANGE RESOURCES</div><span class="meta">5% LOSS</span></div><div class="controls"><div class="field"><label for="fundExchangePool">Exchange from</label><select id="fundExchangePool"><option value="personal">My planet resources</option><option value="fund" '+(mayAlliance('exchange')?'':'disabled')+'>Alliance Fund</option></select></div><div class="field"><label for="fundExchangeFrom">Give resource</label><select id="fundExchangeFrom">'+options+'</select></div><div class="field"><label for="fundExchangeTo">Receive resource</label><select id="fundExchangeTo">'+options.replace('value="crystal"','value="crystal" selected')+'</select></div><div class="field"><label for="fundExchangeAmount">Amount to exchange</label><input id="fundExchangeAmount" type="number" min="1" step="1" value="1000"></div><button class="btn primary" data-alliance="exchange">EXCHANGE · 5% LOSS</button></div><div class="note" id="fundExchangePreview" style="margin:12px" role="status" aria-live="polite">Give 1,000 Metal → receive 950 Crystal. Loss: 50. Received resources remain in the selected account.</div><div class="note" style="margin:12px">Whole resource units only. The 5% fee is rounded up. Alliance reserve exchange is controlled by rank permissions and must preserve the minimum reserve.</div></section><section class="panel"><div class="ph"><div class="pt">MEMBER CONTRIBUTIONS</div><span class="meta">OPTIONAL TAX · MAX 5%</span></div><div class="controls"><div class="field"><label for="allianceTax">Automatic tax (%)</label><input type="number" id="allianceTax" min="0" max="5" value="'+a.tax+'"></div><button class="btn" data-alliance="tax">SAVE TAX</button></div></section>'+allianceFundMinimumHTML()+'</div>';}
function donateAllianceFund(){const r=document.getElementById('fundResource')?.value,n=Number(document.getElementById('fundAmount')?.value);if(!RES[r]||!Number.isSafeInteger(n)||n<=0)return notify('Enter a positive whole resource amount.',true);if(!mayAlliance('donate'))return notify('Your rank cannot donate to this alliance.',true);const a=state.alliance,windowTicks=allianceHoursToTicks(24),ledger=(a.donationLedger||[]).filter(d=>d.tick>state.tick-windowTicks),used=ledger.filter(d=>d.resource===r).reduce((sum,d)=>sum+d.amount,0),cap=Math.floor(income()[r]*2);if(used+n>cap)return notify('Remaining donation allowance: '+nfmt(Math.max(0,cap-used))+' '+RES[r].label+'.',true);if(state.resources[r]<n)return notify('Not enough resources.',true);state.resources[r]-=n;a.donationLedger=[...ledger,{resource:r,amount:n,tick:state.tick}];a.pendingDonations=a.pendingDonations||[];a.pendingDonations.push({resource:r,amount:n,tick:state.tick+8});allianceLog(nfmt(n)+' '+RES[r].label+' donation scheduled for tick '+(state.tick+8)+'.');update();notify('Donation scheduled. Arrives in 8 ticks.');}
function exchangeAllianceResources(){const pool=document.getElementById('fundExchangePool')?.value,from=document.getElementById('fundExchangeFrom')?.value,to=document.getElementById('fundExchangeTo')?.value,n=Number(document.getElementById('fundExchangeAmount')?.value);if(!['personal','fund'].includes(pool)||!RES[from]||!RES[to]||from===to||!Number.isSafeInteger(n)||n<=0)return notify('Choose two different resources and a positive whole amount.',true);if(pool==='fund'&&!mayAlliance('exchange'))return notify('Your rank cannot exchange alliance fund resources.',true);const account=pool==='fund'?state.alliance.fund:state.resources,received=n-Math.ceil(n*.05);if(received<1)return notify('That exchange returns no whole resource units.',true);if((account[from]||0)<n)return notify('Not enough '+RES[from].label+' in that account.',true);if(pool==='fund'&&!Object.keys(RES).every(id=>(account[id]||0)-(id===from?n:0)+(id===to?received:0)>=(state.alliance.fundMinimum?.[id]||0)))return notify('That exchange would leave the alliance fund below its minimum reserve.',true);account[from]-=n;account[to]=(account[to]||0)+received;allianceLogAction((pool==='fund'?'Alliance Fund':'Planet')+' exchanged '+nfmt(n)+' '+RES[from].label+' for '+nfmt(received)+' '+RES[to].label+' (5% loss).','good');update();notify('Received '+nfmt(received)+' '+RES[to].label+'.');}
function previewFundExchange(){const el=document.getElementById('fundExchangePreview');if(!el)return;const from=document.getElementById('fundExchangeFrom')?.value,to=document.getElementById('fundExchangeTo')?.value,n=Number(document.getElementById('fundExchangeAmount')?.value),pool=document.getElementById('fundExchangePool')?.value;if(!RES[from]||!RES[to]||from===to||!Number.isSafeInteger(n)||n<=0){el.textContent='Choose two different resources and a positive whole amount.';return;}const fee=Math.ceil(n*.05),account=pool==='fund'?state.alliance.fund:state.resources;el.textContent='Give '+nfmt(n)+' '+RES[from].label+' → receive '+nfmt(Math.max(0,n-fee))+' '+RES[to].label+'. Loss: '+nfmt(fee)+'. Available: '+nfmt(account[from]||0)+'.';}
for(const eventName of ['input','change'])document.addEventListener(eventName,e=>{if(e.target.id?.startsWith('fundExchange'))previewFundExchange();});

const ALLIANCE_RANKS=['Owner','HC','Officer','Scanner','Member','Recruit'];
const ALLIANCE_PERMISSIONS=[['attack','Manage attack operations'],['attackClaim','Claim attack targets'],['fortress','Set / move stronghold'],['structures','Build alliance structures'],['war','Declare war / peace'],['roles','Promote / demote members'],['recruitment','Manage recruitment'],['message','Edit alliance message'],['tax','Set alliance tax'],['exchange','Exchange alliance fund reserves'],['fundMinimum','Set minimum fund reserves'],['permissions','Configure rank permissions'],['donate','Donate to alliance fund'],['defence','Create / close defence calls'],['fleetStatus','View member idle fleets'],['launchBay','Control permanent Alliance Fleet'],['scans','Use alliance scan funding'],['intel','View alliance intel'],['intelNotes','Edit intel notes / threat labels']];
const ALLIANCE_ACTION_PERMISSIONS={setFortress:'fortress',buildStructure:'structures',toggleWar:'war',message:'message',toggleapps:'recruitment',accept:'recruitment',decline:'recruitment',tax:'tax',donate:'donate',call:'defence',dismiss:'defence'};
function defaultAlliancePermissions(){return Object.fromEntries(ALLIANCE_RANKS.map(rank=>[rank,Object.fromEntries(ALLIANCE_PERMISSIONS.map(([id])=>[id,['Owner','HC'].includes(rank)||(['fleetStatus','launchBay','attack'].includes(id)&&rank==='Officer')||(['exchange','donate','defence'].includes(id)&&rank!=='Recruit')||(id==='scans'&&rank==='Scanner')||(id==='attackClaim'&&rank!=='Recruit')||id==='intel'||(id==='intelNotes'&&['Officer','Scanner'].includes(rank))]))]));}
function currentAllianceRank(){return state.alliance.members.find(isOwnAllianceMember)?.rank||'Recruit';}
function mayAlliance(key){if(key==='permissions'&&window.isGameAdmin)return true;const rank=currentAllianceRank();if(!isAllianceMember('A. Commander'))return false;const defaults=defaultAlliancePermissions();return state.alliance.rankPermissions?.[rank]?.[key]??defaults[rank]?.[key]??false;}
function allianceRanksHTML(){const editable=mayAlliance('permissions'),defaults=defaultAlliancePermissions(),rules=state.alliance.rankPermissions||{};return '<section class="panel"><div class="ph"><div class="pt">RANKS · ALLIANCE PERMISSIONS</div><span class="meta">'+(editable?'CONFIGURABLE':'VIEW ONLY')+'</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Alliance option</th>'+ALLIANCE_RANKS.map(r=>'<th>'+r+'</th>').join('')+'</tr></thead><tbody>'+ALLIANCE_PERMISSIONS.map(([id,label])=>'<tr><td>'+label+'</td>'+ALLIANCE_RANKS.map(rank=>'<td><input type="checkbox" data-rank-permission="'+id+'" data-permission-rank="'+rank+'" aria-label="'+rank+' · '+label+'" '+((rules[rank]?.[id]??defaults[rank][id])?'checked':'')+' '+(editable?'':'disabled')+'></td>').join('')+'</tr>').join('')+'<tr><td>Grant or remove Owner · fixed rule</td>'+ALLIANCE_RANKS.map(rank=>'<td>'+(rank==='Owner'?'Owner + staff':'Staff only')+'</td>').join('')+'</tr></tbody></table></div>'+allianceIntelFieldMatrix(editable)+'<div class="controls"><button class="btn primary" data-ranks-save '+(editable?'':'disabled')+'>SAVE RANK PERMISSIONS</button><button class="btn" data-ranks-reset '+(editable?'':'disabled')+'>RESTORE DEFAULT PERMISSIONS</button></div><div class="note" style="margin:12px">Permissions apply to every member with that rank. Owner is the highest rank. Only an Owner or staff can add or remove Owners; this rule cannot be delegated through the permissions matrix. Members can exchange reserves by default; Owner and HC can configure minimum reserves. Game admins retain access to this configuration to recover a locked permission setup.</div></section>';}
async function saveAlliancePermissions(reset=false){if(!mayAlliance('permissions'))return notify('Your rank cannot configure permissions.',true);const rules=defaultAlliancePermissions();if(!reset)document.querySelectorAll('[data-rank-permission]').forEach(input=>{if(rules[input.dataset.permissionRank]&&ALLIANCE_PERMISSIONS.some(([id])=>id===input.dataset.rankPermission))rules[input.dataset.permissionRank][input.dataset.rankPermission]=input.checked;});const fields=defaultIntelFields();if(!reset)document.querySelectorAll('[data-rank-field]').forEach(input=>{if(fields[input.dataset.fieldRank]&&INTEL_FIELDS.some(([id])=>id===input.dataset.rankField))fields[input.dataset.fieldRank][input.dataset.rankField]=input.checked;});if(typeof persistAllianceSettings==='function'){try{await persistAllianceSettings({rankPermissions:rules,intelFields:fields});}catch(error){return notify(error.message,true);}}state.alliance.rankPermissions=rules;state.alliance.intelFields=fields;allianceLogAction(reset?'Default rank permissions restored.':'Alliance rank permissions updated.','warn');update();notify('Rank permissions saved.');}
function allianceFundMinimumHTML(){const values=state.alliance.fundMinimum||{},editable=mayAlliance('fundMinimum');return '<section class="panel"><div class="ph"><div class="pt">MINIMUM FUND RESERVES</div><span class="meta">'+(editable?'CONFIGURABLE':'VIEW ONLY')+'</span></div><div class="controls">'+Object.entries(RES).map(([id,r])=>'<div class="field"><label for="fundMinimum-'+id+'">'+r.label+' minimum</label><input id="fundMinimum-'+id+'" type="number" min="0" step="1" value="'+(values[id]||0)+'" '+(editable?'':'disabled')+'></div>').join('')+'<button class="btn primary" data-fund-minimum-save '+(editable?'':'disabled')+'>SAVE MINIMUM RESERVES</button></div><div class="note" style="margin:12px">A fund exchange is allowed only if every resulting reserve is at or above its minimum. Personal resource exchanges use your planet’s own stock.</div></section>';}
async function saveAllianceFundMinimum(){if(!mayAlliance('fundMinimum'))return notify('Your rank cannot change minimum reserves.',true);const values=Object.fromEntries(Object.keys(RES).map(id=>[id,Number(document.getElementById('fundMinimum-'+id)?.value)]));if(!Object.values(values).every(n=>Number.isSafeInteger(n)&&n>=0))return notify('Minimum reserves must be non-negative whole amounts.',true);if(typeof persistAllianceSettings==='function'){try{await persistAllianceSettings({fundMinimum:values});}catch(error){return notify(error.message,true);}}state.alliance.fundMinimum=values;allianceLogAction('Minimum alliance fund reserves updated.','warn');update();notify('Minimum reserves saved.');}
document.addEventListener('click',e=>{if(e.target.closest('[data-ranks-save]'))saveAlliancePermissions();if(e.target.closest('[data-ranks-reset]'))saveAlliancePermissions(true);if(e.target.closest('[data-fund-minimum-save]'))saveAllianceFundMinimum();});
if(state.allianceCreated||(state.allianceDirectory?.length&&state.alliance.name!==freshState().alliance.name)){const panel=document.getElementById('allianceCreatePanel');if(panel)panel.open=false;}

function renderCreatedAllianceStats(){const created=state.alliance?.name!=="Unaffiliated"&&isAllianceMember("A. Commander"),form=document.getElementById('allianceCreatePanel'),panel=document.getElementById('allianceStatistics');if(form)form.hidden=created;if(!panel)return;panel.hidden=!created;if(!created)return;const a=state.alliance,planets=state.galaxy.filter(p=>p.alliance===a.name),score=planets.reduce((n,p)=>n+planetScore(p),0),galaxies=new Set(a.members.map(m=>galaxyOf(m.coords)).filter(Boolean));panel.innerHTML='<div class="ph"><div class="pt">ALLIANCE STATISTICS · '+esc(a.name)+'</div><span class="meta">'+esc(a.tag||'')+'</span></div><div class="alliance-kpis" style="padding:12px;margin:0">'+[['MEMBERS',a.members.length+' / 40'],['GALAXIES',galaxies.size],['TRACKED SCORE',nfmt(score)],['FUND RESOURCES',nfmt(Object.keys(RES).reduce((n,id)=>n+(a.fund[id]||0),0))],['ALLIANCE TAX',a.tax+'%'],['STRONGHOLD',a.fortress.strongholdGalaxy||'Not set']].map(([label,value])=>'<div class="alliance-kpi"><small>'+label+'</small><b>'+value+'</b></div>').join('')+'</div>';}

function intelAllianceNames(){return [...new Set([state.alliance.name,...(state.allianceDirectory||[]).map(a=>a.name),...state.galaxy.map(p=>p.alliance)])].filter(n=>n&&n!=='Unaffiliated').sort();}
function intelRowRelation(record,planet){return ['Neutral','Ally','War','NAP'].includes(record.relation)?record.relation:'Neutral';}
function latestIntelLetters(coords){const reports=[...(state.alliance.intelGalaxyScans||[]),...state.waves.scans].filter(s=>!s.anonymous&&s.coords===coords&&mayIntelField(s.type)),latest=new Map();for(const sc of reports){const old=latest.get(sc.type);if(!old||Number(sc.savedAt||sc.tick)>Number(old.savedAt||old.tick))latest.set(sc.type,sc);}const letters={planet:'P',development:'D',unit:'U',advanced:'A',landing:'L',incoming:'I',jumpgate:'J',news:'N'};return [...latest.values()].map(sc=>'<button class="quickscan" data-intel-scan-coords="'+coords+'" data-intel-scan-type="'+esc(sc.type)+'" title="'+esc((sc.name||sc.type)+' · T'+sc.tick)+'">'+esc(letters[sc.type]||sc.type.slice(0,1).toUpperCase())+'</button>').join(' ')||'—';}
function allianceIntelHTML(){if(!mayAlliance('intel'))return '<section class="panel"><div class="empty">Your rank cannot view alliance intel.</div></section>';const a=state.alliance,[hx,hy]=homeGalaxy().split(':').map(Number),c=a.intelBrowserCoords||{x:hx,y:hy},key=padCoord(c.x)+':'+padCoord(c.y),data=browserGalaxyData(c),records=a.intelRecords||{},query=(a.intelSearch||'').toLowerCase(),opts=value=>Array.from({length:100},(_,i)=>'<option value="'+(i+1)+'" '+(Number(value)===i+1?'selected':'')+'>'+padCoord(i+1)+'</option>').join(''),rows=Array.from({length:15},(_,i)=>{const slot=i+1,coords=key+':'+padCoord(slot),p=slot<=10?data.planets.find(p=>p.coords===coords):state.structurePlanets.find(p=>p.coords===coords),record=records[coords]||{},label=p?.name||(slot<=10?'Empty':'Empty / Reserved');if(query&&!((label+' '+coords+' '+(p?.ruler||'')+' '+(record.targetAlliance||'')+' '+(record.nickname||'')+' '+(record.status||'')+' '+(record.note||'')).toLowerCase().includes(query)))return '';const relation=mayIntelField('assessment')?intelRowRelation(record,p):'Neutral',editable=mayAlliance('intelNotes')&&mayIntelField('assessment');return '<tr class="intel-relation-'+(mayIntelField('assessment')?relation.toLowerCase():'neutral')+'"><td>'+padCoord(slot)+'</td><td>'+(p?'<a href="#allianceIntelDetail" data-intel-target="'+coords+'">'+esc(label)+'</a>':esc(label))+'<small>'+coords+'</small></td><td>'+(p?'<input aria-label="Nickname for '+coords+'" data-intel-nickname="'+coords+'" list="unassignedIntelMembers" maxlength="80" value="'+esc(mayIntelField('assessment')?(record.nickname||''):'')+'" placeholder="Nickname / unassigned member" '+(editable?'':'disabled')+'>':'—')+'</td><td>'+esc(p?.race||'—')+'</td><td>'+(p?'<select aria-label="Intel alliance for '+coords+'" data-intel-affiliation="'+coords+'" '+(editable?'':'disabled')+'><option value="">Unassigned</option>'+intelAllianceNames().map(n=>'<option value="'+esc(n)+'" '+(n===(mayIntelField('assessment')?record.targetAlliance:'')?'selected':'')+'>'+esc(n)+'</option>').join('')+'</select>':'—')+'</td><td>'+(p?'<strong class="intel-relation-text '+relation.toLowerCase()+'">'+esc(mayIntelField('assessment')?relation:'Restricted')+'</strong>':'—')+'</td><td>'+latestIntelLetters(coords)+'</td><td>'+esc(mayIntelField('assessment')?(record.status||'Unassessed'):'Restricted')+'</td></tr>';}).join('');return '<datalist id="unassignedIntelMembers">'+state.alliance.members.filter(m=>!state.galaxy.some(p=>p.alliance===a.name&&(m.planetId===p.id||m.planet===p.name))).map(m=>'<option value="'+esc(m.name)+'">Unassigned alliance member</option>').join('')+'</datalist><section class="panel"><div class="ph"><div class="pt">ALLIANCE INTEL · '+esc(a.name)+' · '+key+'</div><span class="meta">'+(data.local?'TRACKED PLANETS':'SIMULATED GALAXY')+' · 15 SLOTS</span></div><div class="controls"><button class="btn" data-intel-step="-1">← PREVIOUS</button><div class="field"><label for="intelSector">Sector</label><select id="intelSector">'+opts(c.x)+'</select></div><div class="field"><label for="intelGalaxy">Galaxy</label><select id="intelGalaxy">'+opts(c.y)+'</select></div><button class="btn primary" data-intel-browse>VIEW GALAXY</button><button class="btn" data-intel-step="1">NEXT →</button><div class="field"><label for="allianceIntelSearch">Find a planet / note</label><input id="allianceIntelSearch" value="'+esc(a.intelSearch||'')+'" placeholder="Planet, coordinates, alliance or threat"></div><button class="btn" data-intel-search>SEARCH</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Slot</th><th>Planet</th><th>Nickname</th><th>Race</th><th>Alliance</th><th>Relation</th><th>Latest scans</th><th>Assessment</th></tr></thead><tbody>'+rows+'</tbody></table></div></section><section class="panel alliance-intel-detail" id="allianceIntelDetail" style="margin-top:14px">'+allianceIntelDetailHTML()+'</section><div class="note" style="margin-top:12px">This browser has its own coordinates. Alliance affiliations, relations and notes are stored centrally for your alliance. Scan intelligence combines your saved scans with reports shared through the central database.</div>';}
function allianceIntelDetailHTML(){const a=state.alliance,coords=a.intelTarget;if(!coords)return '<div class="empty">Select a planet to view scan intelligence and record an assessment.</div>';const record=a.intelRecords?.[coords]||{},editable=mayAlliance('intelNotes'),viewNotes=mayIntelField('notes'),viewAssessment=mayIntelField('assessment');return '<div class="ph"><div class="pt">INTEL DOSSIER · '+coords+'</div><span class="meta">'+(editable?'EDITABLE':'VIEW ONLY')+'</span></div><div class="controls"><div class="field"><label for="intelThreat">Assessment</label><select id="intelThreat" '+(editable&&viewAssessment?'':'disabled')+'>'+['Unassessed','Friendly','Watch','Hostile'].map(status=>'<option '+(status===(viewAssessment?(record.status||'Unassessed'):'Unassessed')?'selected':'')+'>'+status+'</option>').join('')+'</select></div><div class="field"><label for="intelNote">Alliance intel notes</label><textarea id="intelNote" maxlength="2000" rows="3" '+(editable&&viewNotes?'':'disabled')+'>'+esc(viewNotes?(record.note||''):'Your rank cannot view intel notes.')+'</textarea></div><button class="btn primary" data-intel-save '+(editable?'':'disabled')+'>SAVE ASSESSMENT</button><button class="btn" data-intel-refresh>REFRESH SCANS</button></div><p class="meta" id="intelScanStatus" style="padding:0 12px">Your saved reports are shown below. Refresh to include central shared reports.</p><div id="intelScanReports">'+intelReportHTML(state.waves.scans.filter(sc=>!sc.anonymous&&sc.coords===coords&&mayIntelField(sc.type)))+'</div>';}
function intelReportHTML(scans){return scans.length?scans.map(sc=>'<details class="intel-scan" data-scan-type="'+esc(sc.type)+'"><summary>'+waveScanIcon(sc.type||'planet').replace(/ data-scan="[^"]*"/g,'')+esc(sc.name||sc.type||'Scan')+' · T'+sc.tick+'</summary><pre>'+esc(sc.text||'')+'</pre></details>').join(''):'<div class="empty">No scan reports for this planet.</div>';}
function browseAllianceIntel(step=0){if(!mayAlliance('intel'))return;let x=Number(document.getElementById('intelSector')?.value),y=Number(document.getElementById('intelGalaxy')?.value);if(!Number.isInteger(x)||!Number.isInteger(y)||x<1||x>100||y<1||y>100)return;y+=step;if(y>100){y=1;x=x===100?1:x+1;}if(y<1){y=100;x=x===1?100:x-1;}state.alliance.intelBrowserCoords={x,y};state.alliance.intelTarget='';save();renderAlliance();}
async function saveAllianceIntel(){if(!mayAlliance('intelNotes'))return notify('Your rank cannot edit intel assessments.',true);const a=state.alliance,coords=a.intelTarget,status=document.getElementById('intelThreat')?.value,note=(document.getElementById('intelNote')?.value||'').trim().slice(0,2000);if(!coords||!['Unassessed','Friendly','Watch','Hostile'].includes(status))return;if(typeof centralDirectoryRequest==='function'){try{await centralDirectoryRequest('/api/alliance-intel',{coords,status,note,tick:state.tick});}catch(error){return notify(error.message,true);}}a.intelRecords=a.intelRecords||{};a.intelRecords[coords]={...(a.intelRecords[coords]||{}),status,note,tick:state.tick};save();renderAlliance();notify('Intel assessment saved.');}
async function loadAllianceIntelScans(){if(!mayAlliance('intel'))return;const a=state.alliance,coords=a.intelTarget,name=a.name;if(!coords)return;const status=document.getElementById('intelScanStatus');if(status)status.textContent='Loading shared scan reports…';try{let data=await centralDirectoryRequest('/api/alliance-intel?'+new URLSearchParams({coords}));const shared=[...data.scans];while(data.hasMore){if(state.alliance.name!==name||state.alliance.intelTarget!==coords)return;data=await centralDirectoryRequest('/api/alliance-intel?'+new URLSearchParams({coords,offset:data.nextOffset}));shared.push(...data.scans);}if(state.alliance.name!==name||state.alliance.intelTarget!==coords)return;const own=state.waves.scans.filter(sc=>!sc.anonymous&&sc.coords===coords&&mayIntelField(sc.type)),unique=new Map([...own,...shared].map(sc=>[[sc.type,sc.tick,sc.text].join('|'),sc]));document.getElementById('intelScanReports').innerHTML=intelReportHTML([...unique.values()].sort((a,b)=>Number(b.savedAt||b.tick)-Number(a.savedAt||a.tick)));document.getElementById('intelScanStatus').textContent=unique.size+' reports · your archive + central shared scans';}catch(error){if(state.alliance.intelTarget===coords&&document.getElementById('intelScanStatus'))document.getElementById('intelScanStatus').textContent='Central reports unavailable. Your local scan archive remains visible.';}}
document.addEventListener('click',e=>{const target=e.target.closest('[data-intel-target]'),step=e.target.closest('[data-intel-step]');if(target&&mayAlliance('intel')){state.alliance.intelTarget=target.dataset.intelTarget;save();renderAlliance();document.getElementById('allianceIntelDetail')?.scrollIntoView?.({behavior:'smooth',block:'start'});loadAllianceIntelScans();}if(step||e.target.closest('[data-intel-browse]'))browseAllianceIntel(step?Number(step.dataset.intelStep):0);if(e.target.closest('[data-intel-save]'))saveAllianceIntel();if(e.target.closest('[data-intel-refresh]'))loadAllianceIntelScans();if(e.target.closest('[data-intel-search]')){state.alliance.intelSearch=document.getElementById('allianceIntelSearch').value.trim();save();renderAlliance();}});

const INTEL_FIELDS=[['assessment','Threat assessment · Friendly / Watch / Hostile'],['notes','Alliance notes'],['planet','Planet Scan · value, resources, asteroids'],['development','Development Scan · buildings and research'],['unit','Unit Scan · approximate fleet composition'],['advanced','Advanced Unit Scan · exact fleet composition'],['landing','Landing Scan · ETA 1 fleets'],['incoming','Incoming Scan · incoming hostile fleets'],['jumpgate','Jumpgate Probe · fleet routes'],['news','News Scan · intercepted events']];
