function renderGalaxyIntelOverlay(){const control=document.getElementById('galaxyIntelOverlayControl');if(!control)return;const allowed=mayAlliance('intel'),enabled=allowed&&!!state.alliance.intelOverlay;control.innerHTML=allowed?'<label class="galaxy-intel-toggle"><input type="checkbox" id="galaxyIntelOverlay" '+(enabled?'checked':'')+'> ENABLE ALLIANCE INTEL OVERLAY</label><span class="meta" id="centralPlanetStatus">'+(typeof planetDirectoryReady!=='undefined'&&planetDirectoryReady?'CENTRAL PLANET DATABASE · CONNECTED':'CONNECTING TO CENTRAL PLANET DATABASE')+'</span>':'';const rows=document.getElementById('browserPlanetRows');if(!rows)return;const table=rows.closest?.('table'),heading=table?.querySelector('thead tr');heading?.querySelectorAll('[data-intel-heading]').forEach(el=>el.remove());setGalaxyTotalsSpan(heading);if(!enabled)return;heading?.insertAdjacentHTML('beforeend',['Nickname','Intel alliance','Relation','Latest scans','Assessment'].map(label=>'<th data-intel-heading>'+label+'</th>').join(''));setGalaxyTotalsSpan(heading);const key=padCoord(state.browserCoords.x)+':'+padCoord(state.browserCoords.y),data=browserGalaxyData();rows.querySelectorAll?.('tr').forEach((row,i)=>{const coords=key+':'+padCoord(i+1),p=i<10?data.planets.find(p=>p.coords===coords):state.structurePlanets.find(p=>p.coords===coords),r=state.alliance.intelRecords?.[coords]||{},visible=mayIntelField('assessment'),relation=visible?intelRowRelation(r,p):'Restricted';if(p&&visible&&relation!=='Neutral')row.classList.add('intel-relation-'+relation.toLowerCase());row.insertAdjacentHTML('beforeend','<td>'+esc(visible?(r.nickname||''):'Restricted')+'</td><td>'+esc(visible?(r.targetAlliance||'—'):'Restricted')+'</td><td>'+(p?'<strong class="intel-relation-text '+relation.toLowerCase()+'">'+esc(relation)+'</strong>':'—')+'</td><td>'+latestIntelLetters(coords)+'</td><td>'+esc(visible?(r.status||'Unassessed'):'Restricted')+'</td>');});}

async function loadCentralIntelGalaxy(){if(!mayAlliance('intel')||typeof centralDirectoryRequest!=='function')return;const intelOwner=state.alliance,intelUser=state.centralPlayerId;const key=allianceTab==='intel'?state.alliance.intelBrowserCoords||state.browserCoords:state.browserCoords,galaxy=padCoord(key.x)+':'+padCoord(key.y);try{const data=await centralDirectoryRequest('/api/alliance-intel?'+new URLSearchParams({galaxy}));if(state.alliance!==intelOwner||state.centralPlayerId!==intelUser||data.alliance!==state.alliance.name||!mayAlliance('intel'))return;for(const coords of Object.keys(state.alliance.intelRecords||{}))if(coords.startsWith(galaxy+':'))delete state.alliance.intelRecords[coords];state.alliance.intelRecords=state.alliance.intelRecords||{};for(const r of data.records)state.alliance.intelRecords[r.coords]=r;state.alliance.intelGalaxyScans=data.scans||[];if(allianceTab==='intel')renderAlliance();renderGalaxyBrowser();save();}catch(error){const status=document.getElementById('intelDirectoryStatus');if(status)status.textContent=error.message;}}
document.addEventListener('change',e=>{if(e.target.id==='galaxyIntelOverlay'){state.alliance.intelOverlay=e.target.checked;save();renderGalaxyBrowser();if(e.target.checked)loadCentralIntelGalaxy();}});
document.addEventListener('click',e=>{const target=e.target.closest('[data-intel-overlay-target]');if(target&&mayAlliance('intel')){state.alliance.intelTarget=target.dataset.intelOverlayTarget;const [x,y]=target.dataset.intelOverlayTarget.split(':').map(Number);state.alliance.intelBrowserCoords={x,y};allianceTab='intel';navigate('alliance');loadAllianceIntelScans();}if(e.target.closest('[data-atab="intel"]')||e.target.closest('[data-intel-browse]')||e.target.closest('[data-intel-step]'))loadCentralIntelGalaxy();});


async function saveIntelAffiliation(coords,field,value){if(!mayAlliance('intelNotes')||!mayIntelField('assessment'))return;const intelOwner=state.alliance,intelUser=state.centralPlayerId,record={status:'Unassessed',note:'',...(state.alliance.intelRecords?.[coords]||{}),coords,tick:state.tick,[field]:value};try{if(typeof centralDirectoryRequest==='function')await centralDirectoryRequest('/api/alliance-intel',record);if(state.alliance!==intelOwner||state.centralPlayerId!==intelUser)return;state.alliance.intelRecords=state.alliance.intelRecords||{};state.alliance.intelRecords[coords]=record;save();renderAlliance();}catch(error){notify(error.message,true);renderAlliance();}}
