async function savePlanetUsername(){const username=(document.getElementById('planetUsername')?.value||'').trim();if(!/^[\p{L}\p{N} _.-]{2,32}$/u.test(username))return notify('Use 2–32 letters, numbers, spaces, dots, underscores or hyphens.',true);try{if(typeof centralDirectoryRequest==='function'){const result=await centralDirectoryRequest('/api/planets',{username},'PATCH');planetDirectoryRevision=result.revision;}const home=state.galaxy.find(p=>p.player);if(home)home.username=username;state.userSettings.username=username;update();notify('Username saved.');}catch(error){notify(error.message,true);}}
