document.addEventListener('click',e=>{const button=e.target.closest('[data-factory-apply-order]');if(button)applyFactoriesToOrder(button.dataset.factoryApplyOrder);});

function adminPlanetEditorHTML(p){const field=(label,id,value,type='text')=>'<div class="field"><label for="'+id+'">'+esc(label)+'</label><input id="'+id+'" type="'+type+'" '+(type==='number'?'min="0" step="1" ':'')+'value="'+esc(value)+'"></div>',select=(label,id,values,value)=>'<div class="field"><label for="'+id+'">'+esc(label)+'</label><select id="'+id+'">'+values.map(([v,text])=>'<option value="'+esc(v)+'" '+(String(v)===String(value)?'selected':'')+'>'+esc(text)+'</option>').join('')+'</select></div>',module=(key,title,fields)=>'<section class="panel planet-editor-module" data-planet-module="'+key+'"><div class="ph"><div class="pt">'+title+'</div><span class="meta">'+esc(p.name)+'</span></div><div class="admin-form">'+fields+'</div><div class="admin-actions"><button class="btn primary" data-apply-planet-module="'+key+'">APPLY CHANGES</button><span class="meta" role="status" id="planetModuleStatus-'+key+'"></span></div></section>',coords=p.coords.split(':').map(Number),coordOptions=max=>Array.from({length:max},(_,i)=>[i+1,padCoord(i+1)]);return '<section class="panel" id="adminPlanetEditor"><div class="ph"><div class="pt">PLANET EDITOR · '+state.galaxy.length+' PLANETS</div><span class="meta">INDEPENDENT MODULES</span></div><div class="controls">'+select('Select planet','adminPlanetSelect',state.galaxy.map(p=>[p.id,p.name+' · '+p.coords]),p.id)+'<button class="btn" data-admin="selectPlanet">LOAD</button>'+'<button class="btn" data-goto="adminAlliances">ALLIANCE CONTROLCENTER</button><button class="btn" data-admin="addplanet" '+(state.galaxy.length>=40?'disabled':'')+'>ADD PLANET</button><button class="btn warn" data-admin="resetplanets">RESET DEFAULT PLANETS</button></div></section><div class="planet-editor-modules">'+module('identity','IDENTITY',field('Name','admName',p.name)+field('Ruler','admRuler',p.ruler)+(p.player?'<div class="note">Player race: '+esc(state.race)+' · use Round setup to change race.</div>':field('Race','admRace',p.race||'Terran')))+module('location','PLANET LOCATION',select('Sector X','admCoordX',coordOptions(100),coords[0])+select('Galaxy Y','admCoordY',coordOptions(100),coords[1])+select('Planet slot','admCoordZ',coordOptions(10),coords[2])+'<small>Planet location · all galaxies. Slots 1–10 only. Slots 11–15 are reserved for alliance structures.</small>')+module('resources','RESOURCE BANK',Object.entries(RES).map(([id,r])=>field(r.label+' resources','admRes-'+id,p.player?state.resources[id]:p.resources?.[id]||0,'number')).join(''))+module('asteroids','ASTEROID FIELDS',Object.entries(RES).map(([id,r])=>field(r.label+' asteroids','admRoid-'+id,p.player?state.roids[id]:p.roids?.[id]||0,'number')).join(''))+module('ships','BASE FLEET',Object.entries(SHIPS).filter(([,d])=>d.race===(p.player?state.race:p.race)).map(([id,d])=>field(d.name,'admShip-'+id,p.player?state.fleets.base[id]:p.ships?.[id]||0,'number')).join('')||'<div class="empty">No ships in this race catalogue.</div>')+module('experience','EXPERIENCE',field('Experience','admXp',p.player?state.xp:p.xp||0,'number'))+module('structures','STRUCTURES',p.player?Object.entries(BUILDINGS).map(([id,b])=>field(b.name,'admStructure-'+id,state.buildings[id]||0,'number')).join(''):field('Structures','admStructures',p.structures||0,'number'))+module('status','PLANET STATUS',select('Status','admExiled',[[false,'Active'],[true,'Exiled']],!!p.exiled))+'</div>'+(p.player?'':'<div class="admin-actions"><button class="btn warn" data-admin="deleteplanet">DELETE PLANET</button></div>');}
function applyAdminPlanetModule(key){if(!window.isGameAdmin)return notify('Game-admin access is required.',true);const p=state.galaxy.find(p=>p.id===(state.adminSelected||'home'));if(!p)return;const previous=copy(p),read=id=>document.getElementById(id)?.value||'',number=id=>{const n=Number(read(id));if(!Number.isSafeInteger(n)||n<0)throw Error('Enter non-negative whole numbers.');return n;},drafts=[];document.querySelectorAll('[data-planet-module] input,[data-planet-module] select').forEach(el=>{if(el.closest('[data-planet-module]').dataset.planetModule!==key)drafts.push([el.id,el.value]);});try{if(key==='identity'){const name=read('admName').trim(),ruler=read('admRuler').trim(),race=p.player?state.race:read('admRace').trim();if(!name||!ruler||/[<>]/.test(name+ruler)||name.length>80||ruler.length>80)throw Error('Enter plain planet and ruler names of up to 80 characters.');if(!['Terran','Cathaar','Xandathrii','Zikonian','Eitraides','Ilyr','Khepri','Drax'].includes(race))throw Error('Choose a supported race.');p.name=name;p.ruler=ruler;if(!p.player)p.race=race;syncEditedAllianceMember(p,previous);}else if(key==='location'){const coords=chosenAdminCoordinates();if(!coords)throw Error('Choose a valid sector, galaxy and planet slot.');if(state.galaxy.some(q=>q.id!==p.id&&q.coords===coords))throw Error('That planet slot is occupied.');movePlanet(p,coords);if(p.player){const [x,y]=coords.split(':').map(Number);state.browserCoords={x,y};}syncEditedAllianceMember(p,previous);}else if(key==='alliance'){const name=read('admAlliance');if(!allianceChoices().includes(name))throw Error('Select an existing alliance.');const a=allianceProfile(name);if(a&&!a.members.some(m=>m.planetId===p.id||m.planet===p.name)&&a.members.length>=40)throw Error('Alliance member capacity reached (40).');p.alliance=name;syncEditedAllianceMember(p,previous);}else if(key==='resources'||key==='asteroids'){const values=Object.fromEntries(Object.keys(RES).map(id=>[id,number((key==='resources'?'admRes-':'admRoid-')+id)]));if(key==='resources'){p.resources=values;if(p.player)state.resources={...values};}else{p.roids=values;if(p.player)state.roids={...values};}}else if(key==='ships'){const values=Object.fromEntries(Object.entries(SHIPS).filter(([,d])=>d.race===(p.player?state.race:p.race)).map(([id])=>[id,number('admShip-'+id)]));p.ships={...(p.ships||{}),...values};if(p.player){Object.assign(state.fleets.base,values);Object.assign(state.ships,values);}}else if(key==='experience'){const xp=number('admXp');p.xp=xp;if(p.player)state.xp=xp;}else if(key==='structures'){if(p.player){const values=Object.fromEntries(Object.keys(BUILDINGS).map(id=>[id,number('admStructure-'+id)]));state.buildings={...values};p.buildings={...values};p.structures=Object.values(values).reduce((n,v)=>n+v,0);}else p.structures=number('admStructures');}else if(key==='status'){if(!['true','false'].includes(read('admExiled')))throw Error('Choose Active or Exiled.');p.exiled=read('admExiled')==='true';}else return;addNews('Administrator applied '+key+' changes to '+p.name+'.','warn');update();for(const [id,value] of drafts){const el=document.getElementById(id);if(el)el.value=value;}if(typeof syncPlanetDirectory==='function')syncPlanetDirectory();const status=document.getElementById('planetModuleStatus-'+key);if(status)status.textContent='CHANGES APPLIED';notify('Applied '+key+' changes.');}catch(error){notify(error.message,true);}}
document.addEventListener('click',e=>{const button=e.target.closest('[data-apply-planet-module]');if(button)applyAdminPlanetModule(button.dataset.applyPlanetModule);});

document.addEventListener('click',e=>{if(e.target.closest('[data-open-round-reset]')){if(!window.isGameAdmin)return notify('Only game admins can reset the shared round.',true);document.getElementById('resetButton').click();}});

document.addEventListener('click',e=>{if(e.target.closest('[data-save-government]'))saveGovernment();});

function selectedProductionFleet(id){const value=document.getElementById('shipFleet-'+id)?.value||state.shipFleetTargets?.[id]||'base';return ['base','f1','f2','f3','f4'].includes(value)?value:'base';}
function productionOrderItems(o){return Array.isArray(o.items)?o.items:[{id:o.id,qty:o.qty,fleet:o.destinationFleet||'base'}];}
function productionOrderLabel(o){return productionOrderItems(o).map(item=>item.qty+' × '+(SHIPS[item.id]?.name||item.id)+' → '+fleetLabel(item.fleet||'base')).join(' · ');}
function completeProductionOrder(order){for(const item of productionOrderItems(order)){const fleet=['base','f1','f2','f3','f4'].includes(item.fleet)?item.fleet:'base';state.fleets[fleet][item.id]=(state.fleets[fleet][item.id]||0)+item.qty;}addNews(productionOrderLabel(order)+' completed. Ships delivered to the selected fleets.','good');}
function addShipToDraft(id){const ship=SHIPS[id];if(!ship||!shipUnlocked(id)||!state.buildings[ship.factory])return notify('Unlock the ship and build its factory first.',true);const qty=Math.floor(Number(document.getElementById('qty-'+id)?.value)||0);if(qty<1||qty>20000)return notify('Enter 1–20,000 ships.',true);const fleet=selectedProductionFleet(id),draft=state.productionDraft=state.productionDraft||[],entry=draft.find(item=>item.id===id&&item.fleet===fleet);if(entry&&entry.qty+qty>20000)return notify('A draft item can contain at most 20,000 ships.',true);if(entry)entry.qty+=qty;else draft.push({id,qty,fleet});save();renderProductionDraft();notify('Added to draft. Use Order all to confirm.');}
function productionDraftCost(items){const bill={metal:0,crystal:0,eonium:0};for(const item of items.filter(x=>SHIPS[x.id]))for(const [r,n] of Object.entries(shipProductionCost(item.id)))bill[r]+=n*item.qty;return bill;}
function renderProductionDraft(){const el=document.getElementById('productionDraft');if(!el)return;const draft=state.productionDraft||[],cost=draft.length?productionDraftCost(draft):{metal:0,crystal:0,eonium:0};el.innerHTML='<section class="panel"><div class="ph"><div class="pt">DRAFT SHIP ORDER</div><span class="meta">NOT CONFIRMED · NO RESOURCES CHARGED</span></div>'+(draft.length?'<div class="table-wrap"><table class="table"><thead><tr><th>Ship</th><th>Amount</th><th>Destination on completion</th><th></th></tr></thead><tbody>'+draft.map((item,i)=>'<tr><td>'+esc(SHIPS[item.id]?.name||item.id)+'</td><td>'+nfmt(item.qty)+'</td><td>'+esc(fleetLabel(item.fleet))+'</td><td><button class="btn" data-remove-ship-draft="'+i+'">REMOVE</button></td></tr>').join('')+'</tbody></table></div>':'<div class="empty">Use Add to order on ship cards to build a combined order.</div>')+'<div class="controls"><span class="meta">TOTAL · '+constructionCostText(cost)+'</span><button class="btn primary" data-confirm-ship-draft '+(!draft.length?'disabled':'')+'>ORDER ALL</button><button class="btn" data-clear-ship-draft '+(!draft.length?'disabled':'')+'>CLEAR DRAFT</button></div><div class="note" style="margin:12px">Order all confirms this draft as one combined order. Prices include the current government discount and are checked again at confirmation. Each ship is delivered to its selected fleet when the order completes.</div></section>';}
function confirmShipDraft(){const draft=state.productionDraft||[];if(!draft.length)return notify('Add ships to the draft first.',true);if(state.production&&state.productionQueue.length>=1)return notify('One active and one queued ship order are allowed. The draft is preserved.',true);for(const item of draft){const ship=SHIPS[item.id];if(!ship||ship.race!==state.race||!shipUnlocked(item.id)||!state.buildings[ship.factory]||!Number.isSafeInteger(item.qty)||item.qty<1||item.qty>20000||!['base','f1','f2','f3','f4'].includes(item.fleet))return notify('A draft item is no longer valid or unlocked. Review the draft.',true);}const cost=productionDraftCost(draft);if(!canAfford(cost))return notify('Not enough resources to confirm the whole draft. No resources were charged.',true);const items=copy(draft),total=Object.values(cost).reduce((n,v)=>n+v,0),order={id:items[0].id,qty:items.reduce((n,item)=>n+item.qty,0),items,total,remaining:total,cost,orderNumber:state.nextShipOrderNumber=(state.nextShipOrderNumber||0)+1,factoryAssignments:copy(state.factoryAssignments||{})};pay(cost);if(!state.production)state.production=order;else state.productionQueue.push(order);state.productionDraft=[];addNews('Combined ship order #'+order.orderNumber+' confirmed: '+productionOrderLabel(order)+'.','good');update();notify('Order all confirmed.');refreshPageAfterOrder();}
document.addEventListener('change',e=>{if(e.target.dataset.shipDestination){state.shipFleetTargets=state.shipFleetTargets||{};state.shipFleetTargets[e.target.dataset.shipDestination]=e.target.value;save();}});
document.addEventListener('click',e=>{const add=e.target.closest('[data-add-ship-draft]'),remove=e.target.closest('[data-remove-ship-draft]');if(add)addShipToDraft(add.dataset.addShipDraft);if(remove){state.productionDraft.splice(Number(remove.dataset.removeShipDraft),1);save();renderProductionDraft();}if(e.target.closest('[data-clear-ship-draft]')){state.productionDraft=[];save();renderProductionDraft();}if(e.target.closest('[data-confirm-ship-draft]'))confirmShipDraft();});

function recordBattleNews(m,target,fight){const report={id:'battle-'+state.tick+'-'+Date.now()+'-'+Math.random().toString(36).slice(2,7),tick:state.tick,coords:target.coords||'',targetId:target.id,target:target.name,attackerName:m.name||'Attacking fleet',defenderName:target.name,attacker:copy(fight.arrivedA),defender:copy(fight.arrivedD),survivorsA:copy(fight.attacker),survivorsD:copy(fight.defender),habitat:copy(fight.habitat),population:{before:fight.populationBefore,lost:fight.populationLost,after:fight.populationAfter,damagePercent:fight.populationDamagePercent},salvage:{metal:0,crystal:0,eonium:0}};report.earthSalvage=earthBattleSalvage(report,target);if(report.earthSalvage){report.salvage=report.earthSalvage.award;queueEarthSalvage(report);}addNews('Combat: '+report.attackerName+' fighting at '+report.coords+' · '+report.target,'warn');state.news[0].battleReport=report;}
function battleNewsHTML(r){const side=(name,arrived,survived)=>'<h4>Report of losses from '+esc(name)+' fighting at '+esc(displayCoords(r.coords))+'</h4><table class="table"><thead><tr><th>Ship</th><th>Arrived</th><th>Lost</th></tr></thead><tbody>'+Object.entries(arrived||{}).filter(([,n])=>n>0).map(([id,n])=>'<tr data-ship-class="'+esc(SHIPS[id]?.class||'')+'"><td>'+esc(SHIPS[id]?.name||id)+'</td><td>'+nfmt(n)+'</td><td class="loss">'+nfmt(n-(survived?.[id]||0))+'</td></tr>').join('')+'</tbody></table>';return '<section class="battle-news-report">'+side(r.attackerName,r.attacker,r.survivorsA)+side(r.defenderName,r.defender,r.survivorsD)+(r.population?'<h4>Population impact</h4><table class="table"><thead><tr><th>Before</th><th>Pop dmg%</th><th>Casualties</th><th>Survivors</th><th>Mining bonus after</th><th>Population CU / RP after</th></tr></thead><tbody><tr><td>'+nfmt(r.population.before)+'</td><td>'+Number(r.population.damagePercent||0).toLocaleString('en-US',{maximumFractionDigits:3})+'%</td><td class="loss">'+nfmt(r.population.lost)+'</td><td>'+nfmt(r.population.after)+'</td><td>+'+(r.population.after*.001).toFixed(3)+'%</td><td>+'+Math.floor(r.population.after/100)+' CU / RP</td></tr></tbody></table>':'')+(r.habitat?.before?'<h4>Biodome impact</h4><table class="table"><thead><tr><th>Before</th><th>Destroyed</th><th>Remaining</th><th>Surviving dome damage</th><th>Habitat casualties</th></tr></thead><tbody><tr><td>'+nfmt(r.habitat.before)+'</td><td class="loss">'+nfmt(r.habitat.destroyed)+'</td><td>'+nfmt(r.habitat.after)+'</td><td>'+((r.habitat.damageAfter||0)/10).toFixed(1)+'%</td><td>'+nfmt(r.habitat.populationLost)+'</td></tr></tbody></table>':'')+'<h4>Salvage report</h4><table class="table"><thead><tr><th>Metal</th><th>Crystal</th><th>Eonium</th></tr></thead><tbody><tr>'+['metal','crystal','eonium'].map(k=>'<td>'+nfmt(r.salvage?.[k])+'</td>').join('')+'</tr></tbody></table><small>'+ (r.earthSalvage?'Earth receives all 20% bonus salvage from destroyed attackers and defenders. '+esc(r.earthSalvage.status||'Settlement pending'):'No eligible Earth fleet participated; no bonus salvage.') +'</small><button class="btn" data-battle-calculator="'+esc(r.id)+'">OPEN IN BATTLE CALCULATOR · TWEAK FLEETS</button></section>';}
function openBattleNews(id){const r=state.news.find(x=>x.battleReport?.id===id)?.battleReport||(state.uplinkTestBattles||[]).find(r=>r.id===id);if(!r)return;window.bcalc={a:copy(r.attacker),d:copy(r.defender),population:r.population?.before??1000,biodomes:r.habitat?.before||0,biodomeDamage:r.habitat?.damageBefore||0};window.bcalcResult='Original engagement at '+esc(displayCoords(r.coords))+' · tick '+r.tick+'. Edit the starting fleets and calculate again.';allianceTab='bcalc';renderAlliance();navigate('alliance');}
function tickerControlsHTML(){return '<section class="panel" style="margin-bottom:14px"><div class="ph"><div class="pt">ROUND TICKER</div><span class="meta">'+(state.config.tickerStopped?'STOPPED':state.config.tickerPaused?'PAUSED':'RUNNING')+' · TICK '+state.tick+'</span></div><div id="tickerStatusBox">'+tickerStatusHTML()+'</div><div class="controls"><button class="btn primary" data-ticker="start">START</button><button class="btn" data-ticker="pause">PAUSE</button><button class="btn warn" data-ticker="stop">STOP</button><button class="btn" data-ticker="step">RUN ONE TICK</button><label class="field">Minutes per tick<input id="tickerMinutes" type="number" min="1" max="1440" step="1" value="'+(state.config.tickHours*60)+'"></label><button class="btn" data-ticker="speed">APPLY SPEED</button></div><div class="note" style="margin:12px">The practice ticker runs while this game is open and catches up at most 24 ticks after inactivity. Pausing freezes automatic ticks; restarting schedules a fresh interval.</div><div class="ticker-auto-start"><label class="field">Automatic start · local date and time<input id="tickerAutoStart" type="datetime-local" value="'+tickerAutoStartValue()+'"></label><button class="btn primary" data-ticker-auto="save">SCHEDULE START</button><button class="btn" data-ticker-auto="cancel">CANCEL SCHEDULE</button><span class="meta">'+(state.config.tickerAutoStartAt?'SCHEDULED: '+new Date(state.config.tickerAutoStartAt).toLocaleString():'NO AUTOMATIC START SCHEDULED')+' · Automatic starts do not unlock quests. This practice schedule runs when the game is open.</span></div></section>';}
function controlTicker(action){const wasPaused=!!state.config.tickerPaused;if(action==='start'&&state.tick>=state.roundLength)return notify('The round has ended.',true);if(action==='stop'){state.config.tickerPaused=true;state.config.tickerStopped=true;state.config.tickerPausedAt=Date.now();state.tickerQuestFlags=state.tickerQuestFlags||{};state.tickerQuestFlags.stop=true;}if(action==='pause'){state.config.tickerStopped=false;state.config.tickerPaused=true;state.config.tickerPausedAt=Date.now();}else if(action==='start'){state.tickerQuestFlags=state.tickerQuestFlags||{};if(state.tickerQuestFlags.start&&wasPaused)state.tickerQuestFlags.restart=true;state.tickerQuestFlags.start=true;state.config.tickerStopped=false;state.config.tickerPaused=false;state.config.tickerPausedAt=null;state.nextTickAt=Date.now()+gameTickMs();}else if(action==='step'){if(state.tick>=state.roundLength)return notify('The round has ended.',true);tickOnce();state.nextTickAt=Date.now()+gameTickMs();}else if(action==='speed'){const minutes=Number(document.getElementById('tickerMinutes').value);if(!Number.isFinite(minutes)||minutes<1||minutes>1440)return notify('Choose 1–1440 minutes.',true);state.config.tickHours=minutes/60;state.nextTickAt=Date.now()+gameTickMs();}if(['start','pause','stop'].includes(action)){const label={start:'STARTED',pause:'PAUSED',stop:'STOPPED'}[action];addNews('GAME UPDATE · Ticker '+label+' at tick '+state.tick+'.','warn');state.news[0].category='GAME_UPDATES';notify('Ticker '+label.toLowerCase()+'.');}state.tickerLastAction={message:{start:'Ticker started. Automatic ticks are enabled.',pause:'Ticker paused. Automatic ticks are frozen.',stop:'Ticker stopped. Automatic ticks are disabled.',step:'One tick processed successfully.',speed:'Tick interval updated.'}[action]||'Ticker updated.',at:Date.now()};update();save();shareStaffTickerSettings();}
document.addEventListener('click',e=>{const battle=e.target.closest('[data-battle-calculator]');if(battle)openBattleNews(battle.dataset.battleCalculator);const ticker=e.target.closest('[data-ticker]');if(ticker)controlTicker(ticker.dataset.ticker);});
function fitSidebarMenu(){const side=document.querySelector('.side'),nav=document.getElementById('nav');if(!side||!nav)return;for(const mode of ['normal','compact','dense']){side.dataset.density=mode;if(side.scrollHeight<=side.clientHeight+1&&nav.scrollHeight<=nav.clientHeight+1)break;}}
if(window.addEventListener)window.addEventListener('resize',fitSidebarMenu);document.querySelectorAll('#nav details').forEach(el=>el.addEventListener('toggle',fitSidebarMenu));if(typeof ResizeObserver!=='undefined'){const sidebar=document.querySelector('.side');if(sidebar)new ResizeObserver(fitSidebarMenu).observe(sidebar);}setTimeout(fitSidebarMenu,0);

document.addEventListener('change',e=>{const key=e.target.dataset?.quickSetting;if(!['allianceTaxEnabled','allianceScansEnabled'].includes(key))return;state.userSettings[key]=e.target.checked;save();renderPlanetSettings();renderWaves();notify('Alliance preference updated.');});

function questBonusBank(){state.questBonuses=state.questBonuses||{metal:0,crystal:0,eonium:0,research:0,construction:0,roids:{metal:0,crystal:0,eonium:0}};if(!state.startupBonusGranted){const rates={Terran:[125,95],Cathaar:[105,110],Xandathrii:[100,105],Zikonian:[115,95],Eitraides:[110,100]},rate=rates[state.race]||[100,100];for(const k of ['metal','crystal','eonium'])state.questBonuses[k]+=2000000;state.questBonuses.construction+=Math.floor(7000*rate[0]/100);state.questBonuses.research+=Math.floor(8000*rate[1]/100);state.startupBonusGranted=true;state.startupBonusRace=state.race;save();}return state.questBonuses;}
function questReward(q){if(q[4]?.reward)return resolveQuestReward(q[4].reward);if(q[3]==='population'||q[3]==='research:demography'){const tier=q[3]==='population'?[1050,1250,1500,2000,3000].indexOf(q[2]):q[2]-1,construction=[50,100,200,400,800][tier]||0,research=[100,150,250,400,600][tier]||0;return {metal:0,crystal:0,eonium:0,construction,research,roids:{metal:0,crystal:0,eonium:0}};}if(q[3]==='covert:strike'||q[3]==='covert:biodome'){const [construction,research]=({1:[100,200],5:[200,400],15:[400,800]})[q[2]]||[0,0];return {metal:0,crystal:0,eonium:0,construction,research,roids:{metal:0,crystal:0,eonium:0}};}if(q[3]==='building:biodome'){const rewards={1:[50,50],5:[150,100],15:[300,200],25:[500,350],50:[1000,700]},[construction,research]=rewards[q[2]]||[0,0];return {metal:0,crystal:0,eonium:0,construction,research,roids:{metal:0,crystal:0,eonium:0}};}if(q[3].startsWith('ticker:'))return {metal:0,crystal:0,eonium:0,research:0,construction:0,roids:{metal:1,crystal:1,eonium:1}};const metric=q[3],reward={metal:500,crystal:350,eonium:200,research:0,construction:0,roids:{metal:0,crystal:0,eonium:0}};if(metric.startsWith('research:')||metric.startsWith('scan'))reward.research=200;else if(metric.startsWith('building:')||metric==='buildings')reward.construction=200;else if(metric.startsWith('roid:'))reward.roids[metric.split(':')[1]]=1;else if(metric==='roids')reward.roids.metal=1;return reward;}
function questRewardText(q){const r=questReward(q);return [r.metal?r.metal+' Metal':'',r.crystal?r.crystal+' Crystal':'',r.eonium?r.eonium+' Eonium':'',r.research?r.research+' RP':'',r.construction?r.construction+' CU':'',...Object.entries(r.roids).filter(([,n])=>n).map(([k,n])=>n+' '+k+' asteroid')].filter(Boolean).join(' · ');}
function questLore(metric){if(metric==='population')return 'The census lights a new neighbourhood on the colonial map. The Development Ministry releases housing and research grants for its growing citizens.';if(metric==='research:demography')return 'The Green Ark programme links clinics, family services and habitat registries, bringing new settlers into the colony without exceeding its shelter capacity.';if(metric==='ticker:start')return 'The first pulse travels through the rebuilt Miday relay. Prospectors mark three asteroid fields as the Reach awakens.';if(metric==='ticker:stop')return 'Command seals the temporal relay to shelter the colonies. Emergency survey teams secure one field of each resource for the quiet hours.';if(metric==='ticker:restart')return 'The beacon burns again. As the suspended convoys resume their journey, three prospecting crews return with newly charted asteroid fields.';if(metric.startsWith('research:'))return 'The sealed Miday archive opens one more fragment as your scientists restore the lost technology.';if(metric.startsWith('building:')||metric==='buildings')return 'Vesper engineers raise a new beacon of industry among the ruins of the old jumpgate network.';if(metric.startsWith('roid'))return 'Prospectors follow the Starfall debris trail and recover supplies for the scattered colonies.';if(metric.startsWith('scan'))return 'A faint signal crosses the dark. Your listening arrays bring its message into focus.';if(metric.startsWith('setting:')||metric==='alliance')return 'The shared command charter asks each colony to sustain its allies through tribute and intelligence.';return 'The command offices record your service to the Vesper Reach and release a sealed supply warrant.';}
function questBonusHTML(){const b=questBonusBank();return '<section class="panel quest-bonus-bank" id="questBonusBank"><div class="ph"><div class="pt">'+newsIcon('ECONOMY')+' UNUSED QUEST BONUSES</div><span class="meta">CURRENT UNUSED BONUS</span></div><div class="note" style="margin:12px">Planetarion startup bonus imported once for ' + esc(state.startupBonusRace||state.race) + '. Base: 2,000,000 of each resource, 7,000 CU and 8,000 RP, with race adjustments. Loyalty bonus: 0% because previous-round history is unavailable. <a href="https://game.planetarion.com/manual.pl?page=formulae" target="_blank" rel="noopener">Manual source</a></div><div class="controls">'+['metal','crystal','eonium'].map(k=>'<span>'+esc(RES[k].label)+' · '+nfmt(b[k])+' resources / '+nfmt(b.roids[k])+' asteroids</span>').join('')+'<button class="btn primary" data-quest-bonus="accept">ACCEPT RESOURCES / ASTEROIDS</button></div><div class="ph"><div class="pt">RESEARCH · '+nfmt(b.research)+' RP TO ALLOCATE</div></div><div class="table-wrap"><table class="table"><thead><tr><th>Branch</th><th>Next research</th><th>Current RP / total</th><th>Remaining RP</th><th>Allocate RP</th></tr></thead><tbody>'+TECH_TREE.map(t=>{const level=state.research[t.id]||0,max=level>=researchMax(t.id),progress=state.researchProgress[t.id]||0,cost=researchCost(t.id,level+1);return '<tr><td>'+esc(t.name)+'</td><td>'+esc(max?'Complete':t.levels[level]||t.name)+'</td><td>'+nfmt(progress)+' / '+(max?'—':nfmt(cost))+'</td><td>'+(max?'—':nfmt(cost-progress))+'</td><td><input type="number" min="0" step="1" value="0" data-bonus-rp="'+t.id+'" '+(max?'disabled':'')+' aria-label="Allocate RP to '+esc(t.name)+'"></td></tr>';}).join('')+'</tbody></table></div><div class="controls"><button class="btn primary" data-quest-bonus="research">ALLOCATE RESEARCH POINTS</button></div><div class="ph"><div class="pt">POPULATION RESERVE · '+nfmt(b.population||0)+' SETTLERS · CONSTRUCTIONS · '+nfmt(b.construction)+' CU TO ALLOCATE</div></div><div class="table-wrap"><table class="table"><thead><tr><th>Construction</th><th>Built</th><th>Current CU / total</th><th>Remaining CU</th><th>Allocate CU</th></tr></thead><tbody>'+Object.entries(BUILDINGS).map(([id,d])=>{const current=state.bonusConstructionProgress?.[id]||0;return '<tr><td>'+esc(d.name)+'</td><td>'+nfmt(state.buildings[id])+'</td><td>'+nfmt(current)+' / '+nfmt(d.cu)+'</td><td>'+nfmt(d.cu-current)+'</td><td><input type="number" min="0" step="1" value="0" data-bonus-cu="'+id+'" aria-label="Allocate CU to '+esc(d.name)+'"></td></tr>';}).join('')+'</tbody></table></div><div class="controls"><button class="btn primary" data-quest-bonus="construction">ALLOCATE CONSTRUCTION UNITS</button></div><div class="note" style="margin:12px">Allocations are final. You can allocate partial progress or several levels and buildings at once. Unused points remain banked. Construction limits still apply; queued paid projects keep their progress.</div></section>';}
function allocateQuestBonus(action){const bank=questBonusBank();if(action==='accept'){const people=Math.min(bank.population||0,Math.max(0,populationCapacity()-state.population));state.population+=people;bank.population=(bank.population||0)-people;for(const k of ['metal','crystal','eonium']){state.resources[k]+=bank[k];state.roids[k]+=bank.roids[k];bank[k]=0;bank.roids[k]=0;}update();return;}const research=action==='research',selector=research?'[data-bonus-rp]':'[data-bonus-cu]',key=research?'research':'construction',entries=[...document.querySelectorAll(selector)].map(input=>({id:research?input.dataset.bonusRp:input.dataset.bonusCu,n:Number(input.value)}));if(entries.some(x=>!Number.isSafeInteger(x.n)||x.n<0))return notify('Enter whole, non-negative point amounts.',true);const total=entries.reduce((s,x)=>s+x.n,0);if(!total)return notify('Enter points to allocate.',true);if(total>bank[key])return notify('You cannot allocate more than your unused bonus.',true);const progress=copy(research?state.researchProgress:state.bonusConstructionProgress||{}),counts=copy(research?state.research:state.buildings);for(const {id,n} of entries){if(!n)continue;if(!research&&!bonusBuildingAvailable(id))return notify('Research has not unlocked this bonus structure. CU remains in your bank.',true);if(research&&!TECH_TREE.some(t=>t.id===id)||!research&&!BUILDINGS[id])return;let remaining=(progress[id]||0)+n,level=counts[id]||0;while(remaining>0){const cost=research?researchCost(id,level+1):BUILDINGS[id].cu;if(research&&level>=researchMax(id))return notify('That allocation exceeds the remaining research levels.',true);if(remaining<cost)break;remaining-=cost;level++;if(!research){counts[id]=level;if(Object.values(counts).reduce((a,v)=>a+v,0)>buildingLimit())return notify('Construction capacity would be exceeded. No points allocated.',true);}}counts[id]=level;progress[id]=remaining;}bank[key]-=total;if(research){state.research=counts;state.researchProgress=progress;if(state.researchActive&&(state.research[state.researchActive]||0)>=researchMax(state.researchActive))state.researchActive=null;}else{state.buildings=counts;state.bonusConstructionProgress=progress;}addNews('Quest bonus allocated: '+total+' '+(research?'RP':'CU')+'.','good');update();}
document.addEventListener('click',e=>{const button=e.target.closest('[data-quest-bonus]');if(button)allocateQuestBonus(button.dataset.questBonus);});

function newsTintClass(entry){if(newsCategory(entry)==='GAME_UPDATES')return 'news-game-update';if(newsCategory(entry)==='COVERT_OPS')return 'news-covert';if(entry.battleReport)return 'news-battle';if(newsCategory(entry)==='ALLIANCE')return 'alliance-signal';if(newsCategory(entry)==='RESEARCH')return 'news-research';if(/ship order|production|factory.*assigned|combined.*order/i.test(entry.text||''))return 'news-production';return ({FLEET:'news-fleet',ECONOMY:'news-economy',DEVELOPMENT:'news-development',INTELLIGENCE:'news-intelligence',POLITICS:'news-politics',SYSTEM:'news-system'})[newsCategory(entry)]||'';}

function achievementCategoryTabsHTML(){const selected=QUEST_CATEGORIES.some(c=>c.id===state.questCategory)?state.questCategory:QUEST_CATEGORIES[0].id;state.questCategory=selected;return '<nav class="achievement-category-tabs" aria-label="Achievement categories">'+QUEST_CATEGORIES.map(c=>'<button class="btn '+(c.id===selected?'active':'')+'" data-achievement-category="'+c.id+'">'+esc(c.shortName||c.name)+' <small>'+c.quests.filter(q=>q[3]!=='offsite'&&questValue(q[3])>=q[2]&&!state.questClaims[q[0]]).length+'</small></button>').join('')+'</nav>';}
function applyQuestTab(){const view=state.questView==='bonuses'?'bonuses':state.questView==='category'?'category':'board',content=document.getElementById('questContent');content.dataset.view=view;content.hidden=view==='board';document.querySelectorAll('[data-quest-category]').forEach(e=>e.hidden=view!=='category'||e.dataset.questCategory!==state.questCategory);document.querySelectorAll('[data-achievement-category]').forEach(e=>e.classList.toggle('active',view==='category'&&e.dataset.achievementCategory===state.questCategory));document.querySelectorAll('[data-quest-tab]').forEach(e=>e.classList.toggle('active',e.dataset.questTab===view));document.getElementById('questSummary').hidden=view!=='board';content.querySelector?.('.quest-lore')?.setAttribute?.('hidden','');content.querySelector?.('.quest-claim-all')?.setAttribute?.('hidden','');const bank=content.querySelector?.('.quest-bonus-bank');if(bank)bank.hidden=view!=='bonuses';}
document.addEventListener('click',e=>{const button=e.target.closest('[data-quest-tab]');if(button){state.questView=button.dataset.questTab;applyQuestTab();}});

const COVERT_OPS=[['fist','Exploding Fist',0,9],['agents','Agent Defection',1,15],['guards','Security Guard Defection',2,5],['science','Hacking: Science Database',3,10],['warp','Warp Drive Manipulation',4,5],['blackout','Information Blackout',5,15],['havoc','Havoc',6,10],['resources','Hacking: Resource Transfers',7,5],['government','Government Subversion',8,20],['strike','Worker Bribery · Quiet Picket',3,10],['biodome','Biodome Sabotage · Glassfall',6,15]];
function covertState(){state.covert=state.covert||{agents:0,guards:0,stealth:80,history:[],successes:0};return state.covert;}
function covertRace(race){return ({Terran:[80,8],Cathaar:[80,8],Xandathrii:[80,6],Zikonian:[85,6],Eitraides:[85,6]})[race]||[80,8];}
function covertAlert(p){const own=p?.player,guards=own?covertState().guards:(p?.guards||0),roids=own?state.roids:p?.roids||{},security=own?state.workforce.security:p?.workforce?.security||0,centres=own?state.buildings.securityCenter:p?.buildings?.securityCenter||0,gov=own?currentGovernmentName():p?.government||'None',bonus=({Corporatism:-5,Democracy:-10,Nationalism:25,Socialism:0,Totalitarianism:15,Anarchy:-15})[gov]||0;const base=(50+5*Math.min(guards/(totalRoids(roids)+1),15))*(1+((centres||0)*2.75+Math.min(50,security)+bonus)/100);return Math.max(base,p?.covertAlert||0);}
function tickCovert(){const c=covertState(),gov=({Democracy:10,Socialism:10})[currentGovernmentName()]||0,[max,growth]=covertRace(state.race);c.stealth=Math.min(max*(1+gov/100)+Math.min(5,c.successes||0),c.stealth+Math.round(growth*(1+gov/100)));const perAgent=1,perGuard=1;let available=Math.min(...Object.values(grossIncome()));while(c.guards&&c.guards*perGuard+c.agents*perAgent>available)c.guards--;while(c.agents&&c.guards*perGuard+c.agents*perAgent>available)c.agents--;for(const k of ['metal','crystal','eonium'])state.resources[k]=Math.max(0,state.resources[k]-c.guards*perGuard-c.agents*perAgent);for(const p of state.galaxy){if(p.covertAlert)p.covertAlert=Math.max(0,p.covertAlert-3);if(p.government==='Anarchy'&&p.governmentPending&&p.governmentRevolutionUntil<=state.tick){p.government=p.governmentPending;p.governmentPending=null;}}}
function renderCovert(){const el=document.getElementById('covertContent');if(!el)return;const c=covertState(),level=state.research.covert||0;el.innerHTML='<section class="panel covert-civil-lore"><div class="ph"><div class="pt">CIVIL OPERATIONS · THE QUIET FRONT</div></div><div class="settings-body"><p><b>Quiet Picket · Worker Bribery.</b> Couriers carry hardship credits and promises of better contracts. A peaceful walkout disrupts ore shipments: −10% mining income for 6 ticks, without population casualties. Covert level 3; at least 10 agents.</p><p><b>Glassfall · Biodome Sabotage.</b> Infiltrators compromise the Green Ark life-support lattice. Every 15 sent agents can destroy one known Biodome, costing its remaining resident places. Covert level 6; at least 15 agents.</p></div></section><section class="panel"><div class="ph"><div class="pt">'+newsIcon('INTELLIGENCE')+' AGENT COMMAND</div><span class="meta">INSTANT PRACTICE OPERATIONS</span></div><div class="alliance-kpis"><div class="alliance-kpi"><small>AGENTS</small><b>'+nfmt(c.agents)+'</b></div><div class="alliance-kpi"><small>GUARDS</small><b>'+nfmt(c.guards)+'</b></div><div class="alliance-kpi"><small>STEALTH</small><b>'+Math.floor(c.stealth)+'</b></div><div class="alliance-kpi"><small>ALERT</small><b>'+Math.floor(covertAlert(state.galaxy.find(p=>p.player)))+'</b></div></div><div class="controls"><label class="field">Personnel amount<input id="covertTrainAmount" type="number" min="1" max="100000" value="5"></label><button class="btn" data-covert-train="agents">TRAIN AGENTS</button><button class="btn" data-covert-train="guards">TRAIN GUARDS</button><button class="btn" data-covert-fire="agents">DISMISS AGENTS</button><button class="btn" data-covert-fire="guards">DISMISS GUARDS</button></div><div class="note" style="margin:12px">Starfall practice training: 500 of each resource per agent, 100 per guard. Wages: 1 of each resource per person per tick; guards are dismissed before agents if income cannot support them.</div></section><section class="panel" style="margin-top:14px"><div class="ph"><div class="pt">OPERATION ORDERS</div><span class="meta">COVERT RESEARCH LEVEL '+level+'</span></div><div class="controls"><label class="field">Target planet<select id="covertTarget">'+state.galaxy.filter(p=>!p.player&&p.status!=='Closed').map(p=>'<option value="'+esc(p.id)+'">'+esc(p.coords+' · '+p.name)+'</option>').join('')+'</select></label><label class="field">Operation<select id="covertOperation">'+COVERT_OPS.map(([id,name,req,min])=>'<option value="'+id+'" '+(level<req?'disabled':'')+'>'+esc(name)+' · '+min+' agents'+(level<req?' · LOCKED L'+req:'')+'</option>').join('')+'</select></label><label class="field">Agents to send<input type="number" id="covertSendAmount" min="5" max="100000" value="9"></label><button class="btn primary" data-covert-launch>EXECUTE OPERATION</button></div><div class="note" style="margin:12px">Mission charge: 500 of each resource per agent, including failed attempts. Protection, paused ticks, closed targets and insufficient stealth block launch. Outcomes are simulated in this browser’s practice round. <a href="https://game.planetarion.com/manual.pl?page=covertops" target="_blank" rel="noopener">Planetarion rules</a></div></section><section class="panel" style="margin-top:14px"><div class="ph"><div class="pt">OPERATION REPORTS</div></div>'+c.history.slice(0,20).map(r=>'<div class="note" style="margin:10px"><b>TICK '+r.tick+' · '+(r.success?'SUCCESS':'FAILED')+'</b><br>'+esc(r.operation+' · '+r.coords+' · '+r.agents+' agents · '+r.result)+'</div>').join('')+'</section>';}
function trainCovert(kind,fire=false){if(!['agents','guards'].includes(kind))return;const amount=Number(document.getElementById('covertTrainAmount').value);if(!Number.isSafeInteger(amount)||amount<1||amount>100000)return notify('Enter 1–100,000 personnel.',true);const c=covertState();if(fire)c[kind]=Math.max(0,c[kind]-amount);else{const cost=Object.fromEntries(['metal','crystal','eonium'].map(k=>[k,amount*(kind==='agents'?500:100)]));if(!canAfford(cost))return notify('Not enough resources for training.',true);pay(cost);c[kind]+=amount;}addNews('Covert command: '+(fire?'dismissed ':'trained ')+amount+' '+kind+'.','info');update();}
async function executeCovert(){const c=covertState(),op=COVERT_OPS.find(x=>x[0]===document.getElementById('covertOperation').value),p=state.galaxy.find(x=>x.id===document.getElementById('covertTarget').value),n=Number(document.getElementById('covertSendAmount').value);if(!op||!p||p.player||p.status==='Closed'||state.tick<=state.config.protectionTicks||state.config.tickerPaused||state.tick>=state.roundLength)return notify('Target unavailable, protection active, or ticks not running.',true);if((state.research.covert||0)<op[2])return notify('Research this operation first.',true);if(!Number.isSafeInteger(n)||n<op[3]||n>c.agents)return notify('Check the mission minimum and your available agents.',true);if(op[0]==='biodome'&&!(p.buildings?.biodome>0))return notify('No known Biodome on this target.',true);if(op[0]==='strike'&&p.strikeUntilTick>state.tick)return notify('This workforce is already on strike.',true);if(['strike','biodome'].includes(op[0])&&typeof runCivilCovert==='function'&&!window.isStaffWorkspace)return runCivilCovert(op,n,p);const newStealth=c.stealth-5-Math.floor(n*.5);if(newStealth<0)return notify('Agents refuse: recover your stealth first.',true);const bill={metal:500*n,crystal:500*n,eonium:500*n};if(!canAfford(bill))return notify('Not enough resources for the mission.',true);const alert=covertAlert(p);pay(bill);c.stealth=newStealth;const success=1+Math.floor(Math.random()*9)+newStealth-alert>1;let result='Detected; mission failed.';if(success){c.successes=(c.successes||0)+1;p.covertAlert=alert+20;result=applyCovertEffect(op[0],n,p);}else{c.successes=0;if(Math.random()<.5){c.agents-=n;result+=' '+n+' agents lost.';}}const xp=Math.floor(2*(op[2]+1+n/5));state.xp+=xp;const report={tick:state.tick,operation:op[1],coords:p.coords,agents:n,success,result:result+' · '+xp+' XP'};c.history.unshift(report);c.history=c.history.slice(0,100);addNews('Covert operation '+op[1]+' at '+p.coords+': '+report.result,success?'good':'warn');state.news[0].category='COVERT_OPS';update();}
function applyCovertEffect(id,n,p){const c=covertState();if(id==='strike'){p.strikeUntilTick=state.tick+6;c.strikes=(c.strikes||0)+1;return 'Quiet Picket: organisers offer hardship credits to entice workers into a strike. Mining income reduced by 10% for 6 ticks; ends at tick '+p.strikeUntilTick+'. No residents are killed.';}if(id==='biodome'){const before=Math.max(0,p.buildings?.biodome||0),destroyed=Math.min(before,Math.floor(n/15)),lost=Math.min(Math.max(0,(p.population??p.publicPopulation??planetBasePopulation(p))-planetBasePopulation(p)),Math.max(0,destroyed*50-Math.floor((p.biodomeDamage||0)/20)));p.buildings.biodome=before-destroyed;p.biodomeDamage=0;p.population=Math.max(0,(p.population??p.publicPopulation??1000)-lost);p.publicPopulation=p.population;if(destroyed)c.biodomeSabotages=(c.biodomeSabotages||0)+1;return 'Glassfall: operatives compromise the Green Ark life-support lattice. '+destroyed+' Biodome(s) destroyed; '+lost+' residents lost; housing capacity reduced by '+destroyed*50+'.';}p.resources=p.resources||{metal:0,crystal:0,eonium:0};p.roids=p.roids||{metal:0,crystal:0,eonium:0};if(id==='fist'){let left=Math.floor(n/3),lost=0;for(const k of ['metal','crystal','eonium']){const take=Math.min(p.roids[k]||0,left);p.roids[k]-=take;left-=take;lost+=take;}return lost+' asteroids destroyed.';}if(id==='agents'||id==='guards'){const key=id==='agents'?'agents':'guards',take=Math.min(p[key]||0,n*(id==='guards'?10:1));p[key]=(p[key]||0)-take;c[key]+=take;return take+' '+key+' defected.';}if(id==='science'){const branch=p.researchActive,progress=p.researchProgress?.[branch]||0,take=Math.min(progress,10*n,Math.floor(progress*Math.floor(n/4)/100));if(branch)p.researchProgress[branch]-=take;if(state.researchActive)state.researchProgress[state.researchActive]=(state.researchProgress[state.researchActive]||0)+take;return take+' RP removed'+(state.researchActive?' and transferred.':'; no active home research to receive them.');}if(id==='resources'){const ratio=npcValue(p)/Math.max(1,playerValue());let moved=0;for(const k of ['metal','crystal','eonium']){const take=Math.floor(Math.min((p.resources[k]||0)*.1,n*8000,n*2000*ratio));p.resources[k]-=take;state.resources[k]+=take;moved+=take;}return nfmt(moved)+' resources transferred.';}if(id==='government'){if(!p.government||p.government==='None')return 'Target has no government.';p.governmentPending=p.government;p.government='Anarchy';p.governmentRevolutionUntil=state.tick+Math.floor(n/5);return 'Government destabilized for '+Math.floor(n/5)+' ticks.';}if(id==='warp'){let budget=n*Math.floor(50+Math.min(npcValue(p)/Math.max(1,playerValue())*10,50))*100,lost=0;for(const [ship,qty] of Object.entries(p.ships||{})){const cost=Object.values(SHIPS[ship]?.cost||{}).reduce((s,v)=>s+v,0);if(!cost)continue;const take=Math.min(qty,Math.floor(budget/cost));p.ships[ship]-=take;budget-=take*cost;lost+=take;}return lost+' idle ships destroyed.';}p.buildings=p.buildings||{};let count=0;if(id==='blackout'){for(const key of ['waveAmplifier','waveDistorter']){const take=Math.min(p.buildings[key]||p[key]||0,Math.floor(n/15));p.buildings[key]=Math.max(0,(p.buildings[key]||p[key]||0)-take);p[key]=p.buildings[key];count+=take;}}else if(id==='havoc'){let budget=Math.floor(n/10);for(const key of Object.keys(p.buildings).filter(k=>!['waveAmplifier','waveDistorter'].includes(k))){const take=Math.min(p.buildings[key],budget);p.buildings[key]-=take;budget-=take;count+=take;}if(!Object.keys(p.buildings).length){count=Math.min(p.structures||0,budget);p.structures=(p.structures||0)-count;}}return count+' facilities destroyed.';}
document.addEventListener('click',e=>{const train=e.target.closest('[data-covert-train]'),fire=e.target.closest('[data-covert-fire]');if(train)trainCovert(train.dataset.covertTrain);if(fire)trainCovert(fire.dataset.covertFire,true);if(e.target.closest('[data-covert-launch]'))executeCovert();});

function refreshMilitaryClock(){const el=document.getElementById('militaryClock');if(!el)return;const d=new Date(),military=(date,utc)=>[utc?date.getUTCHours():date.getHours(),utc?date.getUTCMinutes():date.getMinutes(),utc?date.getUTCSeconds():date.getSeconds()].map(v=>String(v).padStart(2,'0')).join(':');el.textContent=military(d,false);const tickDisplay=document.getElementById('countdown');if(tickDisplay&&state.config.tickerStopped)tickDisplay.textContent='STOPPED';el.setAttribute('datetime',d.toISOString());const server=document.getElementById('serverMilitaryClock');if(server&&window.serverClockOffset!==undefined)server.textContent=military(new Date(Date.now()+window.serverClockOffset),true);const now=state.config.tickerPaused?(state.config.tickerPausedAt||Date.now()):Date.now(),percent=Math.max(0,Math.min(100,100*(1-(state.nextTickAt-now)/gameTickMs()))),fill=document.getElementById('tickProgressFill');if(fill){fill.style.width=(state.config.tickerStopped?0:percent).toFixed(2)+'%';fill.parentElement?.setAttribute?.('aria-valuenow',String(Math.floor(state.config.tickerStopped?0:percent)));const label=document.getElementById('tickProgressLabel');if(label)label.textContent=Math.floor(state.config.tickerStopped?0:percent)+'%';}const load=document.getElementById('pageLoadTime');if(load&&typeof performance!=='undefined'){const nav=performance.getEntriesByType?.('navigation')?.[0],duration=nav?.loadEventEnd||nav?.domContentLoadedEventEnd;if(duration)load.textContent='PAGE LOAD · '+Math.round(duration)+' ms';}}
refreshMilitaryClock();

async function syncServerClock(){if(typeof fetch==='undefined')return;const start=Date.now();try{const response=await fetch('/api/version',{cache:'no-store',credentials:'same-origin'}),data=await response.json(),end=Date.now();if(Number.isFinite(data.serverTime))window.serverClockOffset=data.serverTime-(start+end)/2;const el=document.getElementById('serverResponseTime');if(el)el.textContent='SERVER RTT · '+(end-start)+' ms';refreshMilitaryClock();}catch{const el=document.getElementById('serverResponseTime');if(el)el.textContent='SERVER · OFFLINE';}}syncServerClock();setInterval(syncServerClock,30000);

QUEST_CATEGORIES.push({id:'ticker',name:'Temporal command',quests:[['tickerFirstStart','Ignite the first tick',1,'ticker:start'],['tickerFirstStop','Secure the silent interval',1,'ticker:stop'],['tickerFirstRestart','Reawaken the Reach',1,'ticker:restart']]});


function questThemeFrame(){const skin=state.userSettings.skinRace||'Neutral';return ({Terran:'<path d="M8 8h14M8 8v14M56 8H42M56 8v14M8 56h14M8 56V42M56 56H42M56 56V42"/>',Cathaar:'<path d="M10 49 20 10M24 54 32 7M40 54 48 10" opacity=".4"/>',Xandathrii:'<path d="m32 3 26 14v30L32 61 6 47V17z"/>',Zikonian:'<path d="m32 3 28 29-28 29L4 32z"/>',Eitraides:'<path d="M6 32c0-25 52-25 52 0S6 57 6 32ZM32 4v56" opacity=".5"/>',LCARS:'<path d="M8 5h12v54H8M44 5h12v54H44" stroke-width="5"/>',Borg:'<path d="M5 5h54v54H5zM5 17h54M17 5v54M47 5v54M5 47h54"/>',Stargate:'<circle cx="32" cy="32" r="28"/><path d="m27 4 5 8 5-8M4 27l8 5-8 5m56-10-8 5 8 5"/>',DoctorWho:'<path d="M12 7h40v50H12zM12 17h40M32 17v40"/>',Battlestar:'<path d="M4 21 32 5l28 16M4 43l28 16 28-16"/>'})[skin]||'<circle cx="32" cy="32" r="28" stroke-dasharray="8 4"/>';}
function questGoalIcon(metric){const shape=metric.startsWith('ticker:')?'<circle cx="32" cy="32" r="16"/><path d="M32 21v12l9 6"/>':metric.startsWith('research:')?'<circle cx="29" cy="28" r="12"/><path d="m38 38 10 10M29 20v16m-8-8h16"/>':metric.startsWith('building:')||metric==='buildings'?'<path d="M16 47V30l11 6V23l10 8V16h11v31z"/>':metric.startsWith('roid')?'<path d="m29 15 16 7 6 15-11 14-21-4-6-19zM21 24l7 10 13-8M28 34l-2 11"/>':metric.startsWith('scan')||metric==='agents'||metric==='covertMissions'?'<circle cx="32" cy="32" r="18"/><path d="M32 14v18l14 10M14 32h18"/>':metric.startsWith('setting:')||metric==='alliance'?'<circle cx="25" cy="25" r="7"/><circle cx="42" cy="25" r="7"/><path d="M12 47c2-17 24-17 26 0m0-12c10-4 15 3 16 12"/>':'<path d="m32 14 6 12 14 3-10 10 2 14-12-7-12 7 2-14-10-10 14-3z"/>';return '<svg viewBox="0 0 64 64" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+questThemeFrame()+shape+'</svg>';}
function questMedalIcon(claimed){return '<span class="quest-medal '+(claimed?'claimed':'completed')+'" title="'+(claimed?'Reward claimed · gold medal':'Objective completed · reward ready')+'" aria-label="'+(claimed?'Gold medal: reward claimed':'Completion medal')+'"><svg viewBox="0 0 64 64" fill="none" stroke="currentColor" stroke-width="2.5" aria-hidden="true"><path d="m19 30-4 28 17-9 17 9-4-28" fill="currentColor" fill-opacity=".18"/><circle cx="32" cy="25" r="20" fill="currentColor" fill-opacity=".14"/><circle cx="32" cy="25" r="15"/><path d="m32 13 4 8 9 1-7 7 2 9-8-4-8 4 2-9-7-7 9-1z" fill="currentColor"/></svg></span>';}
function questRewardBadges(q){const r=questReward(q),parts=[];for(const k of ['metal','crystal','eonium'])if(r[k])parts.push('<span class="quest-reward-chip"><i class="quest-resource-icon '+k+'"></i>'+nfmt(r[k])+' '+esc(RES[k].label)+'</span>');if(r.research)parts.push('<span class="quest-reward-chip">'+questGoalIcon('research:core')+r.research+' RP</span>');if(r.construction)parts.push('<span class="quest-reward-chip">'+questGoalIcon('buildings')+r.construction+' CU</span>');for(const [k,n] of Object.entries(r.roids))if(n)parts.push('<span class="quest-reward-chip">'+questGoalIcon('roids')+n+' '+esc(k)+' asteroid</span>');if(r.population)parts.push('<span class="quest-reward-chip">+'+nfmt(r.population)+' settlers</span>');for(const [id,n] of Object.entries(r.structures||{}))parts.push('<span class="quest-reward-chip">'+n+' free '+esc(BUILDINGS[id].name)+'</span>');return parts.join('');}


function tickerAutoStartValue(){if(!state.config.tickerAutoStartAt)return '';const d=new Date(state.config.tickerAutoStartAt);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);}
function scheduleTickerStart(action){if(action==='cancel'){state.config.tickerAutoStartAt=null;state.tickerLastAction={message:'Scheduled start cancelled.',at:Date.now()};update();shareStaffTickerSettings();return notify('Automatic start cancelled.');}const input=document.getElementById('tickerAutoStart').value,time=new Date(input).getTime();if(!input||!Number.isFinite(time)||time<=Date.now())return notify('Choose a future local date and time.',true);state.config.tickerAutoStartAt=time;state.tickerLastAction={message:'Automatic start scheduled for '+new Date(time).toLocaleString()+'.',at:Date.now()};addNews('GAME UPDATE · Automatic ticker start scheduled for '+new Date(time).toLocaleString()+'.','info');state.news[0].category='GAME_UPDATES';update();shareStaffTickerSettings();notify('Automatic start scheduled. No quest credit is awarded.');}
function processTickerAutoStart(){const time=state.config.tickerAutoStartAt;if(!time||Date.now()<time||state.tick>=state.roundLength)return;state.config.tickerAutoStartAt=null;state.config.tickerPaused=false;state.config.tickerStopped=false;state.config.tickerPausedAt=null;state.nextTickAt=Date.now()+gameTickMs();state.tickerLastAction={message:'Ticker started at the scheduled time.',at:Date.now()};addNews('GAME UPDATE · Ticker automatically STARTED at tick '+state.tick+'. Scheduled starts do not unlock quests.','warn');state.news[0].category='GAME_UPDATES';update();shareStaffTickerSettings();notify('Ticker automatically started.');}
document.addEventListener('click',e=>{const button=e.target.closest('[data-ticker-auto]');if(button)scheduleTickerStart(button.dataset.tickerAuto);});


function asteroidDraftBill(draft=state.asteroidDraft||{}){return Object.fromEntries(['metal','crystal','eonium'].map(k=>[k,draft[k]?costAsteroids(state.roids[k]||0,draft[k]):0]));}
function addAsteroidDraft(id){if(!RES[id])return;const qty=Number(document.getElementById('mine-'+id).value);if(!Number.isSafeInteger(qty)||qty<1)return notify('Enter a whole positive asteroid amount.',true);const draft=state.asteroidDraft=state.asteroidDraft||{},combined=(draft[id]||0)+qty;if(combined+(state.roids[id]||0)>mineLimit())return notify('The draft exceeds this resource’s mining capacity.',true);draft[id]=combined;save();renderAsteroidDraft();notify('Asteroids added to draft. Use Order all to confirm.');}
function renderAsteroidDraft(){const el=document.getElementById('asteroidDraft');if(!el)return;const draft=state.asteroidDraft||{},bill=asteroidDraftBill(),entries=Object.entries(draft).filter(([,n])=>n>0);el.innerHTML='<section class="panel" style="margin-top:12px"><div class="ph"><div class="pt">ASTEROID ORDER DRAFT</div><span class="meta">NOT CONFIRMED · NO RESOURCES CHARGED</span></div>'+(entries.length?'<table class="table"><thead><tr><th>Asteroid type</th><th>Amount</th><th>Cost</th><th></th></tr></thead><tbody>'+entries.map(([id,n])=>'<tr><td>'+esc(RES[id].label)+'</td><td>'+nfmt(n)+'</td><td>'+nfmt(bill[id])+' '+esc(RES[id].label)+'</td><td><button class="btn" data-remove-asteroid-draft="'+id+'">REMOVE</button></td></tr>').join('')+'</tbody></table>':'<div class="empty">Add asteroid amounts above to prepare a combined order.</div>')+'<div class="controls"><span class="meta">TOTAL · '+constructionCostText(bill)+'</span><button class="btn primary" data-confirm-asteroid-draft '+(!entries.length?'disabled':'')+'>ORDER ALL</button><button class="btn" data-clear-asteroid-draft '+(!entries.length?'disabled':'')+'>CLEAR DRAFT</button></div><div class="note" style="margin:12px">Order all rechecks rising asteroid prices, resource balances and mining capacity. The complete draft is initiated together or left untouched.</div></section>';}
function confirmAsteroidDraft(){const draft=state.asteroidDraft||{},entries=Object.entries(draft).filter(([,n])=>n>0);if(!entries.length)return notify('Add asteroids to the draft first.',true);if(entries.some(([id,n])=>!RES[id]||!Number.isSafeInteger(n)||n<1||(state.roids[id]||0)+n>mineLimit()))return notify('Review the draft: an amount is invalid or exceeds capacity.',true);const bill=asteroidDraftBill(draft);if(!canAfford(bill))return notify('Not enough resources for the complete asteroid order. Draft preserved.',true);pay(bill);for(const [id,n] of entries)state.roids[id]+=n;state.asteroidDraft={};addNews('Combined asteroid order confirmed: '+entries.map(([id,n])=>n+' '+id).join(' · ')+'.','good');update();notify('All draft asteroids initiated.');refreshPageAfterOrder();}
document.addEventListener('click',e=>{const add=e.target.closest('[data-add-asteroid-draft]'),remove=e.target.closest('[data-remove-asteroid-draft]');if(add)addAsteroidDraft(add.dataset.addAsteroidDraft);if(remove){delete state.asteroidDraft[remove.dataset.removeAsteroidDraft];save();renderAsteroidDraft();}if(e.target.closest('[data-clear-asteroid-draft]')){state.asteroidDraft={};save();renderAsteroidDraft();}if(e.target.closest('[data-confirm-asteroid-draft]'))confirmAsteroidDraft();});


function claimCompletedQuests(category,questId){const categories=category?QUEST_CATEGORIES.filter(c=>(c.id||c.name)===category):QUEST_CATEGORIES,ready=categories.flatMap(c=>c.quests).filter(q=>(!questId||q[0]===questId)&&q[3]!=='offsite'&&!state.questClaims[q[0]]&&questValue(q[3])>=q[2]);if(!ready.length)return notify('No completed, unclaimed quests in this selection.');const bank=questBonusBank();for(const q of ready){state.questClaims[q[0]]=true;const r=questReward(q);applyExtraQuestReward(r,bank);state.questRewardReceipts=state.questRewardReceipts||{};state.questRewardReceipts[q[0]]=copy(r);for(const k of ['metal','crystal','eonium','research','construction'])bank[k]+=r[k]||0;for(const k of ['metal','crystal','eonium'])bank.roids[k]+=r.roids[k]||0;}addNews('Quest rewards claimed: '+ready.length+' completed '+(ready.length===1?'objective':'objectives')+'. Bonuses are ready to allocate.','good');attachAchievementReceipt(ready);update();notify(ready.length+' quest rewards added to Bonuses.');}
document.addEventListener('click',e=>{const category=e.target.closest('[data-claim-quest-category]');if(category)claimCompletedQuests(category.dataset.claimQuestCategory);if(e.target.closest('[data-claim-all-quests]'))claimCompletedQuests();});


function newsLore(entry){const category=newsCategory(entry),text=String(entry.text||'').toLowerCase();if(text.includes('vote'))return ['Electoral registrar','The ballots cross the Miday relay. The charter records the vote, and the command roster reflects its result.'];if(text.includes('government selection'))return ['Civil charter office','The new charter is sealed. Department heads align their production directives with the selected government.'];if(text.includes('tax')||text.includes('levy'))return ['Revenue office','The ledgers close on another transmission. Whole residents and resource receipts are recorded; unfinished fractions wait in the next ledger.'];if(entry.achievementReceipt)return ['Charter honours board','The sealed orders have been fulfilled. The treasury releases the itemised grants listed in this receipt.'];return ({ECONOMY:['Quartermaster','Freight beacons pulse across the resource lanes. The ledger below records the supplies and production figures reported by command.'],DEVELOPMENT:['Green Ark engineering','A new signal reaches the works district. Engineers file the construction outcome and keep the colony register aligned.'],RESEARCH:['Miday archive','Another fragment of the old archive comes into focus. The science office records exactly what the transmission has established.'],FLEET:['Flight control','Navigation lights cut through the dark. Fleet command records the order, route and available outcome in the attached report.'],BATTLE_REPORTS:['Combat recorder','The battlefield falls quiet long enough for the recorders to transmit. Losses and surviving units remain matters of the battle report below.'],COVERT_OPS:['Veiled relay','A coded message reaches the sealed operations desk. Command releases only the outcome recorded in this transmission.'],GAME_UPDATES:['Command network','The network distributes a revised command protocol. These recorded changes define the new operational instructions.'],INTELLIGENCE:['Listening station','A faint carrier breaks through the interference. Analysts preserve the received intelligence and its recorded limits.'],ALLIANCE:['Alliance liaison','The alliance relay carries another command signal. The names, declaration and recorded effects remain attached to the official report.'],POLITICS:['Galactic charter office','The council seals its command ledger. Appointments, votes and policy decisions are preserved in the transmission record.'],SYSTEM:['Command recorder','The command recorder acknowledges the signal. The reported action and its recorded state are entered in the colony journal.']})[category]||['Command recorder','The transmission enters the command journal.'];}
function newsFeedbackHTML(entry){if(entry.worldAnnouncement){const w=entry.worldAnnouncement;return '<section class="world-broadcast"><img src="/assets/planets/'+esc(w.worldId)+'.svg" alt="'+esc(w.title)+'"><div><small>PUBLIC REGISTRY · HOLDER & LOCATION SEALED</small><h3>'+esc(w.title)+'</h3>'+w.lore.map(p=>'<p>'+esc(p)+'</p>').join('')+'<b>'+esc(w.rarity)+' · Founding population '+nfmt(w.basePopulation)+' · ETA '+w.etaBonus+' tick · Bonus salvage '+w.salvageBonusPercent+'%</b></div></section>';}const [voice,line]=newsLore(entry),c=entry.context,details=entry.details&&typeof entry.details==='object'?Object.entries(entry.details).filter(([,v])=>['string','number','boolean'].includes(typeof v)):[],rows=c?[['Recorded by',c.actor||'Not recorded'],['Colony',c.planet||'Not recorded'],['Coordinates',c.coords?displayCoords(c.coords):'Not recorded'],['World',c.world||'Not recorded'],['Residents',nfmt(c.population)],['Population mining bonus','+'+Number(c.miningBonus||0).toFixed(3)+'%'],['Population work bonus','+'+(c.workBonus||0)+' CU / RP'],['Metal balance',nfmt(c.resources?.metal||0)],['Crystal balance',nfmt(c.resources?.crystal||0)],['Eonium balance',nfmt(c.resources?.eonium||0)],['XP',nfmt(c.xp||0)],...details]:details;return '<aside class="news-transmission-lore"><span>'+newsIcon(newsCategory(entry))+'</span><div><small>COMMAND ATMOSPHERE · '+esc(voice)+'</small><p>“'+esc(line)+'”</p></div></aside><div class="news-outcome-strip"><small>RECORDED OUTCOME</small><b>'+esc(newsStatus(entry)[0])+'</b><span>'+esc(entry.context?.actor||'Command journal')+'</span></div>'+(rows.length?'<details class="news-record-details"><summary>COLONY SNAPSHOT & EVENT DETAILS · AT TRANSMISSION</summary><dl>'+rows.map(([k,v])=>'<div><dt>'+esc(k)+'</dt><dd>'+esc(v)+'</dd></div>').join('')+'</dl><p>Recorded colony state when this entry was created. Detailed battle, reward and diplomacy receipts above describe the event itself.</p></details>':'');}
function newsEventCard(x,index){const category=newsCategory(x),[label,status]=newsStatus(x),title=category.replaceAll('_',' '),date=x.at?new Date(x.at).toLocaleString():'ROUND START';return '<article class="news-entry news-event-card '+newsTintClass(x)+'"><header class="news-event-header"><div class="news-event-emblem news-entry-icon '+category.toLowerCase()+'">'+newsIcon(category)+'</div><div><span class="news-event-kicker">COMMAND TRANSMISSION · '+String(index+1).padStart(4,'0')+'</span><h3>'+esc(title)+'</h3></div><span class="news-status '+status+'">'+label+'</span></header><div class="news-event-body news-entry-copy"><span class="news-event-label">EVENT REPORT</span><p>'+esc(x.text||'Unknown event')+'</p>'+(x.diplomacy?diplomacyReportHTML(x.diplomacy):'')+(x.achievementReceipt?achievementReceiptHTML(x.achievementReceipt):'')+(x.battleReport?battleNewsHTML(x.battleReport):'')+newsFeedbackHTML(x)+'</div><footer class="news-event-meta"><div><span>TICK</span><b>'+String(x.tick||0).padStart(3,'0')+'</b></div><div><span>TRANSMISSION TIME</span><b>'+esc(date)+'</b></div><div><span>CATEGORY</span><b>'+esc(title)+'</b></div></footer></article>';}


async function loadUniverseIntel(){if(!mayAlliance('intel')||!state.universeIntelOverlay)return;if(typeof centralDirectoryRequest!=='function'){renderUniverse();return;}try{const data=await centralDirectoryRequest('/api/alliance-intel');if(data.alliance!==state.alliance.name)return;state.universeIntelOwner=data.alliance;state.universeIntelRecords=Object.fromEntries((data.records||[]).map(r=>[r.coords,r]));renderUniverse();}catch(error){state.universeIntelOverlay=false;state.universeIntelRecords={};renderUniverse();notify(error.message,true);}}
document.addEventListener('change',e=>{if(e.target.id==='universeIntelOverlay'){state.universeIntelOverlay=e.target.checked;state.universeFilter='all';save();renderUniverse();if(e.target.checked)loadUniverseIntel();}});


function autoClaimQuestRewards(){if(!state.userSettings?.autoClaimQuests)return 0;state.questAutomationStats=state.questAutomationStats||{total:0};state.questAutomationStats.lastCheckAt=Date.now();const ready=QUEST_CATEGORIES.flatMap(c=>c.quests).filter(q=>q[3]!=='offsite'&&!state.questClaims[q[0]]&&questValue(q[3])>=q[2]);if(!ready.length)return 0;const bank=questBonusBank();for(const q of ready){state.questClaims[q[0]]=true;const r=questReward(q);for(const k of ['metal','crystal','eonium','research','construction'])bank[k]+=r[k]||0;for(const k of ['metal','crystal','eonium'])bank.roids[k]+=r.roids[k]||0;}state.questAutomationStats.total+=ready.length;state.questAutomationStats.lastClaimAt=Date.now();state.questAutomationStats.lastClaimTick=state.tick;state.questAutomationStats.lastClaimCount=ready.length;addNews('Quest automation claimed '+ready.length+' completed rewards. Open Bonuses to allocate them.','good');attachAchievementReceipt(ready);return ready.length;}
document.addEventListener('change',e=>{if(e.target.id==='autoClaimQuestRewards'){const enabled=e.target.checked,before=state.questAutomationStats?.total||0;state.userSettings.autoClaimQuests=enabled;update();const count=(state.questAutomationStats?.total||0)-before;notify(enabled?'Automatic claiming ON. '+(count?count+' completed rewards added to Bonuses.':'No new completed rewards waiting; future completions will be banked.'):'Automatic claiming OFF.');}});


const TREK_POWERS=['Federation','Klingon','Romulan','Cardassian','Dominion','Borg','Ferengi','Breen'];
const TREK_NAMES={Federation:['USS Defiant','USS Voyager','USS Enterprise NX-01','USS Enterprise NCC-1701','USS Enterprise-A','USS Enterprise-D','USS Enterprise-E','USS Discovery','USS Titan-A','USS Enterprise-G'],Klingon:['IKS Bounty','IKS Pagh','IKS Rotarran','IKS Ch’Tang','IKS Hegh’ta','IKS Negh’Var','IKS Bortas','IKS T’Ong','IKS Koraga','IKS Sarcophagus'],Romulan:['IRW Khazara','IRW T’Met','IRW Devoras','IRW Haakona','IRW Terix','IRW Valdore','IRW Scimitar','IRW Narada','IRW D’Deridex','IRW Tal Shiar'],Cardassian:['CDS Prakesh','CDS Trager','CDS Vetar','CDS Reklar','CDS Aldara','CDS Kraxon','CDS Galor','CDS Keldon','CDS Bok’Nor','CDS Ravinok'],Dominion:['Jem’Hadar Vanguard','Jem’Hadar Interceptor','Jem’Hadar Strike Wing','Jem’Hadar Escort','Jem’Hadar Attack Ship','Jem’Hadar Battlecruiser','Jem’Hadar Dreadnought','Founder’s Will','Vorta Command','Dominion Flagship'],Borg:['Probe Alpha','Sphere One','Tactical Cube','Assimilation Cube','Queen’s Vessel','Unimatrix One','Diamond Command','Collective Vanguard','Cube 001','Nexus Prime'],Ferengi:['Kreechta','Krayton','D’Kora','Marauder Profit','Grand Nagus','Divine Treasury','Latinum Venture','Commerce Raider','Acquisition Prime','Fortune’s Edge'],Breen:['Gor’s Command','Thot’s Spear','Chel Grett','Rezreth','Sarr Theln','Absolute Zero','Cold Dominion','Polar Vanguard','Cryonic Blade','Breen Flagship']};
const originalFleetNames=Object.fromEntries(Object.entries(SHIPS).map(([id,d])=>[id,d.name]));
function trekPower(){const selected=state.userSettings.trekFleetPower;if(TREK_POWERS.includes(selected))return selected;if(state.userSettings.skinRace==='Borg')return 'Borg';return ({Terran:'Federation',Cathaar:'Klingon',Xandathrii:'Romulan',Zikonian:'Cardassian',Eitraides:'Dominion'})[state.race]||'Federation';}
function trekRegistry(id){return trekPower().slice(0,3).toUpperCase()+'-'+String(Object.keys(SHIPS).indexOf(id)+1).padStart(3,'0');}
function applyTrekFleetNames(){const enabled=!!state.userSettings.trekFleetEnabled;document.body.dataset.trekFleet=enabled?'on':'off';document.body.dataset.trekPower=trekPower();let n=0;for(const [id,d] of Object.entries(SHIPS)){if(d.race!==state.race){d.name=originalFleetNames[id];continue;}d.name=enabled?TREK_NAMES[trekPower()][n%10]+(n>=10?' · '+d.class:''):originalFleetNames[id];n++;}}
document.addEventListener('change',e=>{if(e.target.id==='trekFleetEnabled'||e.target.id==='trekFleetPower'){state.userSettings[e.target.id]=e.target.id==='trekFleetEnabled'?e.target.checked:e.target.value;update();notify('Fleet appearance updated.');location.hash='planetSettings';location.reload();}});


async function savePlanetIdentity(field){const id=field==='planetName'?'planetDisplayName':'planetRulerName',value=(document.getElementById(id)?.value||'').trim();if(value.length<2||value.length>60||!/^['’\p{L}\p{N} _.-]+$/u.test(value))return notify('Use 2–60 plain letters, numbers, spaces, dots, apostrophes, underscores or hyphens.',true);try{if(typeof centralDirectoryRequest==='function'){const result=await centralDirectoryRequest('/api/planets',{[field]:value},'PATCH');planetDirectoryRevision=result.revision;}const home=state.galaxy.find(p=>p.player);if(home){const oldName=home.name;if(field==='planetName'){home.name=value;for(const a of [state.alliance,...state.allianceDirectory||[]])for(const member of a.members||[])if(member.planetId===home.id||member.planet===oldName)member.planet=value;}else home.ruler=value;}update();notify(field==='planetName'?'Planet name saved.':'Ruler name saved.');}catch(error){notify(error.message,true);}}
document.addEventListener('click',e=>{const button=e.target.closest('[data-save-planet-identity]');if(button)savePlanetIdentity(button.dataset.savePlanetIdentity);});

function universePopulation(p){return p.player?state.population:Math.max(0,Number(p.population??p.publicPopulation)||0);}
function universeSize(p){return p.player?totalRoids(state.roids):p.roids?totalRoids(p.roids):Number(p.publicSize)||0;}
function universeSnapshot(){const planets=state.galaxy.filter(p=>!p.exiled).map(p=>({id:p.id,size:universeSize(p),score:planetScore(p),value:p.player?playerValue():npcValue(p),population:universePopulation(p)}));state.universeHistory=state.universeHistory||[];const snapshot={tick:state.tick,at:Date.now(),planets},last=state.universeHistory.at(-1);if(last?.tick===state.tick)state.universeHistory[state.universeHistory.length-1]=snapshot;else state.universeHistory.push(snapshot);state.universeHistory=state.universeHistory.slice(-169);return snapshot;}
function universeModule(title,columns,rows,tint='cyan',note=''){return '<section class="panel universe-module '+tint+'"><div class="ph"><div class="pt">'+title+'</div></div><div class="table-wrap"><table class="table"><thead><tr>'+columns.map(c=>'<th>'+c+'</th>').join('')+'</tr></thead><tbody>'+ (rows.length?rows.map(row=>'<tr>'+row.map(cell=>'<td>'+cell+'</td>').join('')+'</tr>').join(''):'<tr><td colspan="'+columns.length+'" class="empty">No recorded data yet.</td></tr>')+'</tbody></table></div>'+(note?'<p class="universe-module-note">'+note+'</p>':'')+'</section>';}
function renderUniverseModules(){const el=document.getElementById('universeModules');if(!el)return;const current=universeSnapshot(),active=state.galaxy.filter(p=>!p.exiled),byId=new Map(active.map(p=>[p.id,p])),baseline=[...state.universeHistory].reverse().find(s=>s.tick<=state.tick-24)||state.universeHistory[0],before=new Map((baseline?.planets||[]).map(p=>[p.id,p])),tracked=state.tick-(baseline?.tick||state.tick),delta=p=>({size:universeSize(p)-(before.get(p.id)?.size??universeSize(p)),value:(p.player?playerValue():npcValue(p))-(before.get(p.id)?.value??(p.player?playerValue():npcValue(p))),population:universePopulation(p)-(before.get(p.id)?.population??universePopulation(p))}),signed=n=>'<span class="'+(n>0?'gain':n<0?'loss':'')+'">'+(n>0?'+':n<0?'−':'')+nfmt(Math.abs(n))+'</span>',planetCell=p=>'<button class="universe-planet-link" data-inspect="'+esc(p.id)+'">'+esc(p.ruler)+'<small>'+esc(p.name)+' · '+esc(displayCoords(p.coords))+'</small></button>',top=[...active].sort((a,b)=>planetScore(b)-planetScore(a)).slice(0,10),galaxies=new Map();for(const p of active){const key=galaxyOf(p.coords),g=galaxies.get(key)||{coords:key,size:0,score:0,value:0,members:0};g.size+=universeSize(p);g.score+=planetScore(p);g.value+=p.player?playerValue():npcValue(p);g.members++;galaxies.set(key,g);}const galaxyRows=[...galaxies.values()].sort((a,b)=>b.score-a.score).slice(0,10).map((g,i)=>[i+1,esc(displayCoords(g.coords)),g.members,nfmt(g.size),nfmt(g.score)]),planetRows=top.map((p,i)=>[i+1,planetCell(p),nfmt(universeSize(p)),nfmt(planetScore(p)),signed(delta(p).size)]);let html=universeModule('LARGEST PLANETS · ASTEROIDS',['#','Planet','Asteroids','Population'],[...active].sort((a,b)=>universeSize(b)-universeSize(a)).slice(0,10).map((p,i)=>[i+1,planetCell(p),nfmt(universeSize(p)),nfmt(universePopulation(p))]),'cyan')+universeModule('MOST POPULATED PLANETS',['#','Planet','Population','Mining bonus'],[...active].sort((a,b)=>universePopulation(b)-universePopulation(a)).slice(0,10).map((p,i)=>[i+1,planetCell(p),nfmt(universePopulation(p)),'+'+(universePopulation(p)*.001).toFixed(3)+'%']),'green')+universeModule('TOP PLANETS',['#','Ruler · planet','Size','Score','Δ Size'],planetRows,'cyan')+universeModule('TOP GALAXIES',['#','Galaxy','Planets','Size','Score'],galaxyRows,'purple');
const raceRows=RACE_SKINS.map(r=>{const members=active.filter(p=>p.race===r),share=active.length?Math.round(members.length/active.length*100):0;return [esc(r),members.length,'<div class="universe-race-bar" style="--share:'+share+'%"><span>'+share+'%</span></div>',nfmt(members.reduce((n,p)=>n+universeSize(p),0))];});html+=universeModule('CIVILISATION DISTRIBUTION',['Race','Planets','Share','Size'],raceRows,'green');const ratio=[...active].filter(p=>universeSize(p)>0).sort((a,b)=>(b.player?playerValue():npcValue(b))/universeSize(b)-(a.player?playerValue():npcValue(a))/universeSize(a)).slice(0,10).map((p,i)=>[i+1,planetCell(p),nfmt(universeSize(p)),((p.player?playerValue():npcValue(p))/universeSize(p)).toFixed(2)]);html+=universeModule('VALUE / ASTEROID',['#','Planet','Size','Ratio'],ratio,'gold','Ratio = current value divided by asteroid count.');
for(const [title,key,direction,tint] of [['LARGEST GROWERS · ASTEROIDS','size',1,'green'],['LARGEST LOSERS · ASTEROIDS','size',-1,'red'],['VALUE GAINED','value',1,'gold'],['VALUE LOST · CRASHERS','value',-1,'orange'],['POPULATION GROWERS','population',1,'green'],['POPULATION LOSERS','population',-1,'red']]){const rows=active.filter(p=>delta(p)[key]*direction>0).sort((a,b)=>(delta(b)[key]-delta(a)[key])*direction).slice(0,10).map((p,i)=>[i+1,planetCell(p),signed(delta(p)[key])]);html+=universeModule(title,['#','Planet','Change'],rows,tint,'Recorded window: '+tracked+' ticks (maximum 24). History starts when this browser observes the round.');}
const visible=mayAlliance('intel')&&state.universeIntelOverlay&&mayIntelField('assessment')&&state.universeIntelOwner===state.alliance.name;if(visible){const groups=new Map();for(const p of active){const name=state.universeIntelRecords?.[p.coords]?.targetAlliance;if(!name)continue;const a=groups.get(name)||{name,members:0,size:0,score:0};a.members++;a.size+=universeSize(p);a.score+=planetScore(p);groups.set(name,a);}html+=universeModule('ALLIANCES · PRIVATE INTEL',['#','Alliance','Known members','Size','Score'],[...groups.values()].sort((a,b)=>b.score-a.score).map((a,i)=>[i+1,esc(a.name),a.members,nfmt(a.size),nfmt(a.score)]),'purple','Only affiliations recorded in your permitted alliance intel are used.');}
const combat=new Map();for(const event of state.news.filter(n=>n.battleReport)){const report=event.battleReport,key=report.coords||report.target?.coords||'Unknown',row=combat.get(key)||{coords:key,reports:0};row.reports++;combat.set(key,row);}html+=universeModule('HOT TARGETS · BATTLE ACTIVITY',['Target coordinates','Reports'],[...combat.values()].sort((a,b)=>b.reports-a.reports).map(r=>[esc(displayCoords(r.coords)),r.reports]),'red','Based on battle reports available in your news log.');const recent=state.universeHistory.slice(-8).reverse().map(s=>[s.tick,nfmt(s.planets.reduce((n,p)=>n+p.size,0)),nfmt(s.planets.reduce((n,p)=>n+p.score,0)),nfmt(s.planets.reduce((n,p)=>n+p.value,0))]);html+=universeModule('TICK HISTORY',['Tick','Asteroids','Score','Value'],recent,'blue','Snapshots are kept for 168 observed ticks and cleared by a round reset.');el.innerHTML=html;const status=document.getElementById('universeParserStatus');if(status)status.innerHTML='<span>PT <b>'+String(state.tick).padStart(3,'0')+'</b></span><span>PLANETS <b>'+active.length+'</b></span><span>GALAXIES <b>'+galaxies.size+'</b></span><span>CLUSTERS <b>'+new Set(active.map(p=>p.coords.split(':')[0])).size+'</b></span><span>ASTEROIDS <b>'+nfmt(current.planets.reduce((n,p)=>n+p.size,0))+'</b></span>';}

document.addEventListener('click',e=>{const button=e.target.closest('[data-universe-focus]');if(button){const target=document.getElementById(button.dataset.universeFocus==='modules'?'universeModules':'universeSearch');target?.scrollIntoView({behavior:'smooth',block:'start'});if(target?.focus)target.focus();}});

function isOwnAllianceMember(member){const home=state.galaxy.find(p=>p.player);return !!home&&home.alliance===state.alliance.name&&(member.planetId===home.id||member.planet===home.name);}
function queueAllianceStructure(type,slot){const a=state.alliance,d=STRUCTURE_DEFS[type];if(!d||!mayAlliance('structures'))return notify('Your rank cannot build alliance structures.',true);if(!a.fortress.strongholdGalaxy||!a.tax)return notify('Set the stronghold and alliance tax first.',true);const queue=a.structures.buildQueue=a.structures.buildQueue||[];if(!availableStructureSlots().includes(slot))return notify('Choose an empty structure slot from 11 to 15.',true);if(queue.some(x=>x.type===type)||a.structures.active.some(x=>x.type===type)||state.tick<(a.structures.cooldowns[type]||0))return notify('This structure is already building, active or cooling down.',true);const cost=structureCost(type);if(!Object.entries(cost).every(([k,n])=>(a.fund[k]||0)>=n))return notify('Alliance fund cannot cover this structure.',true);for(const [k,n] of Object.entries(cost))a.fund[k]-=n;const id='structure-'+type+'-'+Date.now(),build={id,type,slot,startedAt:state.tick,completesAt:state.tick+3};queue.push(build);state.structurePlanets.push({...build,building:true,structurePlanet:true,typeName:d.name,name:d.name+' Structure Planet',ruler:a.name,alliance:a.name,coords:a.fortress.strongholdGalaxy+':'+String(slot).padStart(2,'0'),ships:{},resources:{metal:0,crystal:0,eonium:0},roids:{metal:0,crystal:0,eonium:0}});a.structures.history.unshift({name:d.name,message:'Construction started in slot '+slot+'; completes at tick '+build.completesAt,tick:state.tick});allianceLogAction(d.name+' construction started. Ready in 3 ticks.');update();refreshPageAfterOrder();}
function completeAllianceStructureBuilds(){const a=state.alliance,queue=a.structures.buildQueue||[];for(const build of queue.filter(x=>state.tick>=x.completesAt)){const planet=state.structurePlanets.find(p=>p.id===build.id),d=STRUCTURE_DEFS[build.type];if(!planet||!d)continue;planet.building=false;if(d.duration){const effect={id:build.id,type:build.type,name:d.name,slot:build.slot,alliance:a.name,startedAt:state.tick,expiresAt:state.tick+(d.durationUnit==='hours'?allianceHoursToTicks(d.duration):d.duration)};a.structures.active.push(effect);planet.expiresAt=effect.expiresAt;if(d.cooldown)a.structures.cooldowns[build.type]=state.tick+d.cooldown;allianceLogAction(d.name+' completed in slot '+build.slot+'; effect is now active.','good');}else{distributeAllianceBuilding(build.type==='voyagerIV'?'waveAmplifier':'waveDistorter',5);state.structurePlanets=state.structurePlanets.filter(p=>p.id!==build.id);allianceLogAction(d.name+' completed; every alliance member received 5 '+(build.type==='voyagerIV'?'Wave Amplifiers':'Wave Distorters')+'.','good');}a.structures.history.unshift({name:d.name,message:'Completed after 3 ticks in slot '+build.slot,tick:state.tick});}a.structures.buildQueue=queue.filter(x=>state.tick<x.completesAt);}
function structureBuildProgress(build){const elapsed=Math.min(3,Math.max(0,state.tick-build.startedAt)),percent=Math.round(elapsed/3*100);return '<div class="structure-progress" role="progressbar" aria-label="'+esc(STRUCTURE_DEFS[build.type]?.name||'Structure')+' construction" aria-valuemin="0" aria-valuemax="100" aria-valuenow="'+percent+'"><i style="width:'+percent+'%"></i></div><small>BUILDING · '+elapsed+' / 3 TICKS · '+Math.max(0,build.completesAt-state.tick)+' TICKS LEFT</small>';}
function renderOverviewAllianceStructures(){const el=document.getElementById('overviewAllianceStructures');if(!el)return;const a=state.alliance,active=isAllianceMember('A. Commander')?a.structures.active:[],queue=isAllianceMember('A. Commander')?(a.structures.buildQueue||[]):[];el.innerHTML='<div class="ph"><div class="pt">ALLIANCE STRUCTURES</div><span class="meta">'+active.length+' ACTIVE · '+queue.length+' BUILDING</span></div><div class="overview-structure-art"><small>STRONGHOLD COMMAND</small><b>'+esc(a.name)+'</b></div><div class="overview-structure-grid">'+active.map(x=>{const total=Math.max(1,x.expiresAt-x.startedAt),remaining=Math.max(0,x.expiresAt-state.tick),percent=Math.round(remaining/total*100);return '<article class="overview-structure-box">'+structureGlyph(x.type)+'<div><h3>'+esc(STRUCTURE_DEFS[x.type].name)+'</h3><p>'+esc(STRUCTURE_DEFS[x.type].desc)+'</p><div class="structure-progress" role="progressbar" aria-label="Active effect remaining" aria-valuemin="0" aria-valuemax="100" aria-valuenow="'+percent+'"><i style="width:'+percent+'%"></i></div><small>ACTIVE · SLOT '+x.slot+' · '+remaining+' TICKS LEFT</small></div></article>';}).join('')+queue.map(x=>'<article class="overview-structure-box building">'+structureGlyph(x.type)+'<div><h3>'+esc(STRUCTURE_DEFS[x.type].name)+'</h3>'+structureBuildProgress(x)+'</div></article>').join('')+(!active.length&&!queue.length?'<div class="empty">No active or building alliance structures.</div>':'')+'</div><div class="controls"><button class="btn" data-open-alliance-structures>OPEN ALLIANCE STRUCTURES</button></div>';}
document.addEventListener('click',e=>{if(e.target.closest('[data-open-alliance-structures]')){allianceTab='structures';navigate('alliance');}});

let ownerPasskeyMemory='',ownerPasskeyAlliance='',ownerSettingsPending=false;
async function createAlliance(){const passphrase=document.getElementById('newAlliancePassphrase')?.value||'';if(passphrase&&(passphrase.length<12||passphrase.length>128))return notify('Use a passphrase of 12–128 characters.',true);if(typeof centralDirectoryRequest!=='function'||!planetDirectoryReady)return createAllianceLocal();const before=copy(state),previousIds=new Set(state.galaxy.map(p=>p.id));createAllianceLocal();if(state.alliance.name===before.alliance.name)return;const created=state.alliance,extra=state.galaxy.filter(p=>!previousIds.has(p.id));try{await centralDirectoryRequest('/api/alliance-control/create',{name:created.name,tag:created.tag,description:created.description,recruitmentMessage:created.recruitmentMessage,motd:created.motd,passphrase:passphrase||undefined});applySharedDirectory(await centralDirectoryRequest('/api/planets'));if(planetDirectoryEditable)state.galaxy.push(...extra);state.allianceCreated=true;document.getElementById('allianceCreatePanel').open=false;allianceTab='home';update();navigate('alliance');const phraseField=document.getElementById('newAlliancePassphrase');if(phraseField)phraseField.value='';notify('Alliance created. You are its Owner.'+(passphrase?' Passphrase disclosure enabled.':''));showAllianceCreatedConfirmation(created,!!passphrase);}catch(error){state=before;update();notify(error.message,true);}}
async function updateAllianceMemberRank(memberId,rank){const member=state.alliance.members.find(m=>m.id===memberId);if(!member||!ALLIANCE_RANKS.includes(rank))return;const authority=window.isGameAdmin||currentAllianceRank()==='Owner';if((member.rank==='Owner'||rank==='Owner')&&!authority)return notify('Only an Owner or staff can add or remove an Owner.',true);if(!window.isGameAdmin&&!mayAlliance('roles'))return notify('Your rank cannot manage members.',true);try{if(typeof centralDirectoryRequest==='function'&&planetDirectoryReady){await syncPlanetDirectory();await centralDirectoryRequest('/api/alliance-control/members',{memberId,rank,revision:planetDirectoryRevision});applySharedDirectory(await centralDirectoryRequest('/api/planets'));}else{if(member.rank==='Owner'&&rank!=='Owner'&&state.alliance.members.filter(m=>m.rank==='Owner').length===1&&!window.isGameAdmin)return notify('Assign another Owner first.',true);member.rank=rank;update();}ownerPasskeyMemory='';notify('Alliance rank updated.');}catch(error){renderAlliance();notify(error.message,true);}}
function allianceSettingsHTML(){const a=state.alliance,owner=currentAllianceRank()==='Owner',editable=owner||mayAlliance('message');return '<div class="alliance-settings-grid">'+[['name','Alliance name',a.name],['description','Description',a.description||''],['recruitmentMessage','Recruitment message',a.recruitmentMessage||''],['motd','MOTD',a.motd||a.message||'']].map(([key,label,value])=>'<section class="panel"><div class="ph"><div class="pt">'+label+'</div></div><div class="settings-body"><label class="field" for="allySetting-'+key+'">'+label+'</label>'+(key==='name'?'<input id="allySetting-'+key+'" maxlength="40" value="'+esc(value)+'">':'<textarea id="allySetting-'+key+'" rows="5" maxlength="2000">'+esc(value)+'</textarea>')+'<button class="btn primary" data-save-alliance-setting="'+key+'" '+((key==='name'?owner:editable)?'':'disabled')+'>SAVE '+label.toUpperCase()+'</button></div></section>').join('')+'<section class="panel owner-passkey-box"><div class="ph"><div class="pt">PERSONAL OWNER PASSKEY</div><span class="meta">OWNER ONLY</span></div><div class="settings-body">'+(owner?'<input id="ownerPasskey" type="password" readonly autocomplete="off" aria-label="Personal Owner passkey"><label><input id="showOwnerPasskey" type="checkbox"> Reveal my passkey</label><button class="btn" data-copy-owner-key>COPY PASSKEY</button><button class="btn warn" data-rotate-owner-key>ROTATE MY KEY</button><div class="key-disclosure-box"><label for="ownerRevealPhrase">Optional admin reveal passphrase</label><input id="ownerRevealPhrase" type="password" autocomplete="new-password" minlength="12" maxlength="128" placeholder="12–128 characters"><button class="btn" data-set-key-disclosure>SET REVEAL PASSPHRASE</button><p>Only an admin who receives this passphrase from you can reveal the secret on Keyholders. Rotating a key clears its old reveal passphrase; enter a new phrase above to set it during rotation.</p></div><p id="ownerKeyStatus">Loading your key…</p><p>This key restores the reserved alliance name and settings after a reset. It also authorises the private intel feed with your current rank and field permissions.</p><code>Authorization: Bearer &lt;your passkey&gt;</code><a href="/botfiles/alliance_intel.txt">PRIVATE INTEL FEED →</a>':'<p>Each Owner can view only their own personal passkey. Staff may manage Owner ranks, but cannot view another Owner’s key.</p>')+'</div></section></div>';}
async function loadOwnerSettings(){const input=document.getElementById('ownerPasskey');if(!input)return;if(ownerPasskeyAlliance!==state.alliance.name)ownerPasskeyMemory='';if(ownerPasskeyMemory){input.value=ownerPasskeyMemory;const status=document.getElementById('ownerKeyStatus');if(status)status.textContent='Personal key ready.';return;}if(ownerSettingsPending||typeof centralDirectoryRequest!=='function')return;ownerSettingsPending=true;const requestedAlliance=state.alliance.name;try{const result=await centralDirectoryRequest('/api/alliance-control/settings');if(state.alliance.name!==requestedAlliance)return;ownerPasskeyAlliance=requestedAlliance;ownerPasskeyMemory=result.passkey||'';const current=document.getElementById('ownerPasskey');if(current)current.value=ownerPasskeyMemory;const status=document.getElementById('ownerKeyStatus');if(status)status.textContent=result.isOwner?'Personal key ready.':'Owner access required.';}catch(error){const status=document.getElementById('ownerKeyStatus');if(status)status.textContent=error.message;}finally{ownerSettingsPending=false;}}
async function saveAllianceSetting(key){try{await syncPlanetDirectory();await centralDirectoryRequest('/api/alliance-control/settings',{[key]:document.getElementById('allySetting-'+key).value,revision:planetDirectoryRevision});applySharedDirectory(await centralDirectoryRequest('/api/planets'));notify('Alliance setting saved.');}catch(error){notify(error.message,true);}}
async function recreateAlliance(){const passkey=document.getElementById('allianceRestorePasskey')?.value||'';try{await centralDirectoryRequest('/api/alliance-control/recreate',{passkey});if(document.getElementById('allianceRestorePasskey'))document.getElementById('allianceRestorePasskey').value='';ownerPasskeyMemory='';applySharedDirectory(await centralDirectoryRequest('/api/planets'));state.allianceCreated=true;allianceTab='settings';update();navigate('alliance');notify('Alliance configuration restored.');}catch(error){notify(error.message,true);}}
document.addEventListener('change',e=>{if(e.target.id==='showOwnerPasskey'){const input=document.getElementById('ownerPasskey');if(input)input.type=e.target.checked?'text':'password';}});
document.addEventListener('click',async e=>{const settings=e.target.closest('[data-save-alliance-setting]');if(settings)return saveAllianceSetting(settings.dataset.saveAllianceSetting);if(e.target.closest('[data-copy-owner-key]')){if(ownerPasskeyMemory){await navigator.clipboard.writeText(ownerPasskeyMemory);notify('Owner passkey copied.');}}if(e.target.closest('[data-rotate-owner-key]')){if(!confirm('Rotate your personal key? The previous key will stop working.'))return;try{await centralDirectoryRequest('/api/alliance-control/rotate',{revision:planetDirectoryRevision,passphrase:document.getElementById('ownerRevealPhrase')?.value||undefined});ownerPasskeyMemory='';loadOwnerSettings();notify('Personal Owner key rotated.');}catch(error){notify(error.message,true);}}if(e.target.closest('[data-recreate-alliance]'))recreateAlliance();});
document.addEventListener('click',e=>{if(e.target.closest('[data-universe-bcalc]')){allianceTab='bcalc';navigate('alliance');}});normalizeGalaxySlots();update();setInterval(updateCountdown,1000);if(typeof location!=='undefined'&&location.hash==='#planetSettings')navigate('planetSettings');
function questAutomationStatusHTML(){const enabled=state.userSettings.autoClaimQuests,stats=state.questAutomationStats||{};return '<div class="automation-status" role="status" aria-live="polite"><b>'+ (enabled?'● AUTOMATIC CLAIMING ON':'○ AUTOMATIC CLAIMING OFF')+'</b><p>'+ (enabled?'Checks completed rewards whenever gameplay updates.':'Enable to bank completed rewards automatically.')+'</p><small>AUTO-CLAIMED: '+nfmt(stats.total||0)+' rewards'+(stats.lastClaimAt?' · Last claim: '+stats.lastClaimCount+' at tick '+stats.lastClaimTick+' · '+new Date(stats.lastClaimAt).toLocaleTimeString():' · No automatic claim recorded yet.')+'</small></div>';}
function openAchievementBonuses(){state.questView='bonuses';navigate('quests');renderQuests();save();}
document.addEventListener('click',e=>{if(e.target.closest('[data-open-achievement-bonuses]'))openAchievementBonuses();});

document.addEventListener('change',e=>{if(e.target.id==='gameAmbientMusic'){state.userSettings.gameAmbientMusic=e.target.checked;save();if(typeof applyAmbientMusic==='function')applyAmbientMusic();notify(e.target.checked?'In-game soundtrack enabled.':'In-game soundtrack disabled.');}});

document.addEventListener('click',async e=>{if(!e.target.closest('[data-set-key-disclosure]'))return;const input=document.getElementById('ownerRevealPhrase'),passphrase=input.value;if(passphrase.length<12||passphrase.length>128)return notify('Use a reveal passphrase of 12–128 characters.',true);try{await centralDirectoryRequest('/api/alliance-control/disclosure',{passphrase,revision:planetDirectoryRevision});input.value='';notify('Admin reveal passphrase saved. Give it only to the admin you authorise.');}catch(error){notify(error.message,true);}});
function testBattleUplinkHTML(){if(state.siteManagement?.battleCalcTest===false)return '';return '<section class="panel" id="uplinkTestLab"><div class="ph"><div class="pt">SIMULATED BATTLE LAB</div><span class="tag gold">TEST DATA · LOCAL</span></div><div class="settings-body"><p>Generated practice battles test reports and calculator. Reports remain in this test module. No real ships, resources or farming audit events are changed.</p><button class="btn primary" data-simulate-test-battle>SIMULATE RANDOM BATTLE</button><div id="uplinkTestBattleReports">'+(state.uplinkTestBattles||[]).map(r=>'<article class="fleet-member-box"><h3>SIMULATED · '+esc(r.attackerName)+' vs '+esc(r.defenderName)+'</h3>'+battleNewsHTML(r)+'</article>').join('')+'</div></div></section>';}
function simulateUplinkBattle(){if(state.siteManagement?.battleCalcTest===false)return notify("Battle test is disabled by Site management.",true);const races=[...new Set(Object.values(SHIPS).map(d=>d.race))],aRace=races[Math.floor(Math.random()*races.length)],dRace=races[Math.floor(Math.random()*races.length)],fleet=race=>{const ids=Object.entries(SHIPS).filter(([,d])=>d.race===race&&!d.pod);const ships={};for(let i=0;i<3;i++){const id=ids[Math.floor(Math.random()*ids.length)]?.[0];if(id)ships[id]=(ships[id]||0)+10+Math.floor(Math.random()*41);}return ships;},a=fleet(aRace),d=fleet(dRace),home=state.galaxy.find(p=>p.player),target={name:'SIMULATED defender',coords:home?.coords||'07:04:01'},fight=resolveCombat(copy(a),copy(d),'Simulated attacker','Simulated defender');const report=recordSimulatedCalculatorReport(fight,'Random test engagement');report.attackerName='SIMULATED test fleet';report.defenderName='SIMULATED defender';report.source='uplink';report.simulated=true;report.attackerRace=aRace;report.defenderRace=dRace;state.uplinkTestBattles=[copy(report),...(state.uplinkTestBattles||[])].slice(0,3);save();update();const root=document.getElementById('midayContent');if(root&&typeof buildMidayPage==='function'){buildMidayPage();if(typeof renderMidayReports==='function')renderMidayReports();}notify('Simulated battle added to Satelite Uplink.');return report;}
document.addEventListener('click',e=>{if(e.target.closest('[data-simulate-test-battle]'))simulateUplinkBattle();});
function showAllianceCreatedConfirmation(a,disclosure){const panel=document.createElement('section');panel.className='panel alliance-created-confirmation';panel.setAttribute('role','status');panel.innerHTML='<div class="ph"><div class="pt">✓ ALLIANCE CREATED</div><span class="tag green">OWNER ACCESS CONFIRMED</span></div><div class="settings-body"><h3>'+esc(a.name)+' ['+esc(a.tag)+']</h3><p>Your rank: <b>Owner</b>. Your personal encrypted key has been generated.</p><p>Staff disclosure: <b>'+(disclosure?'Enabled with your passphrase':'Disabled')+'</b>.</p><button class="btn primary" data-created-alliance-settings>OPEN ALLIANCE SETTINGS</button><button class="btn" data-dismiss-alliance-created>DISMISS</button></div>';const previous=document.querySelector('.alliance-created-confirmation');if(previous)previous.remove();document.getElementById('page-alliance').prepend(panel);}
document.addEventListener('click',e=>{const settings=e.target.closest('[data-created-alliance-settings]'),dismiss=e.target.closest('[data-dismiss-alliance-created]');if(settings){allianceTab='settings';renderAlliance();settings.closest('.alliance-created-confirmation').remove();}if(dismiss)dismiss.closest('.alliance-created-confirmation').remove();});
function recordSimulatedCalculatorReport(fight,title){const clean=String(title).replace(/[^\p{L}\p{N} _.:-]/gu,'').slice(0,80)||'Calculator engagement',report={id:'calc-'+Date.now()+'-'+Math.random().toString(36).slice(2),tick:state.tick,coords:'SIMULATION',target:clean,attackerName:'SIMULATED calculator attacker',defenderName:'SIMULATED '+clean,attacker:copy(fight.arrivedA),defender:copy(fight.arrivedD),survivorsA:copy(fight.attacker),survivorsD:copy(fight.defender),population:{before:fight.populationBefore,lost:fight.populationLost,after:fight.populationAfter},salvage:{metal:0,crystal:0,eonium:0},simulated:true,source:'calculator'};report.earthSalvage=earthBattleSalvage(report,{});if(report.earthSalvage){report.salvage=report.earthSalvage.award;report.earthSalvage.status="SIMULATED ONLY · no resources credited";}window.bcalcReport=report;return report;}
function resetTickerAfterRoundReset(){state.config.tickerPaused=true;state.config.tickerStopped=true;state.config.tickerPausedAt=Date.now();state.config.tickerAutoStartAt=null;state.nextTickAt=Date.now()+gameTickMs();}
function shareStaffTickerSettings(){if(!window.isStaffWorkspace||!window.isGameAdmin)return;try{const playing=JSON.parse(localStorage.getItem('starfall-round-v2')||'null');if(!playing)return;playing.config=playing.config||{};for(const key of ['tickerPaused','tickerStopped','tickerPausedAt','tickerAutoStartAt','tickHours'])playing.config[key]=state.config[key];playing.nextTickAt=state.nextTickAt;localStorage.setItem('starfall-round-v2',JSON.stringify(playing));}catch{}}
if(typeof window.addEventListener==='function')window.addEventListener('storage',e=>{if(window.isStaffWorkspace||e.key!=='starfall-round-v2'||!e.newValue)return;try{const playing=JSON.parse(e.newValue);if(playing.centralPlayerId!==state.centralPlayerId)return;for(const key of ['tickerPaused','tickerStopped','tickerPausedAt','tickerAutoStartAt','tickHours'])state.config[key]=playing.config[key];state.nextTickAt=playing.nextTickAt;update();}catch{}});
function bcalcSheetHTML(saved){return '<section class="panel bcalc-sheet"><div class="ph"><div class="pt">FLEET WORKSHEET</div><span class="meta">TAB · ARROW KEYS · PASTE FROM SPREADSHEET</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Ship / class</th><th>Attacker</th><th>Defender</th><th>Population dmg</th></tr></thead><tbody>'+Object.entries(SHIPS).map(([id,d])=>'<tr data-ship-class="'+esc(d.class)+'"><td><b>'+esc(d.name)+'</b><small>'+esc(d.class)+' · '+esc(d.race)+'</small></td>'+['a','d'].map(side=>'<td><input aria-label="'+esc(d.name)+' '+(side==='a'?'attacker':'defender')+'" type="number" min="0" max="1000000000" data-cship="'+side+'" data-ship="'+id+'" value="'+(saved[side][id]||0)+'"></td>').join('')+'<td>'+(['Cruiser','Battleship'].includes(d.class)?populationDamageLabel(d):'')+'</td></tr>').join('')+'</tbody></table></div><p class="note">Paste numeric cells starting at the selected count. Two columns map to Attacker and Defender. Arrow keys move between cells; Tab advances normally.</p></section>';}
document.addEventListener('keydown',e=>{if(!e.target.matches('.bcalc-sheet [data-cship]')||!['ArrowUp','ArrowDown','ArrowLeft','ArrowRight'].includes(e.key))return;const rows=[...document.querySelectorAll('.bcalc-sheet tbody tr')],row=e.target.closest('tr'),r=rows.indexOf(row),col=e.target.dataset.cship==='a'?0:1,nextR=r+(e.key==='ArrowUp'?-1:e.key==='ArrowDown'?1:0),nextC=col+(e.key==='ArrowLeft'?-1:e.key==='ArrowRight'?1:0),input=rows[nextR]?.querySelectorAll('input')[nextC];e.preventDefault();if(input){input.focus();input.select();}});
document.addEventListener('paste',e=>{if(!e.target.matches('.bcalc-sheet [data-cship]'))return;const text=e.clipboardData.getData('text');if(!/[\t\n]/.test(text))return;e.preventDefault();const values=text.trim().split(/\r?\n/).map(line=>line.split('\t').map(v=>Number(v.replace(/,/g,'')))),rows=[...document.querySelectorAll('.bcalc-sheet tbody tr')],start=rows.indexOf(e.target.closest('tr')),col=e.target.dataset.cship==='a'?0:1;if(values.some(v=>v.length>2-col||v.some(n=>!Number.isSafeInteger(n)||n<0||n>1000000000))||start+values.length>rows.length)return notify('Paste at most two numeric columns using whole ship counts.',true);window.bcalc=window.bcalc||{a:{},d:{}};values.forEach((line,i)=>line.forEach((n,j)=>{const input=rows[start+i].querySelectorAll('input')[col+j];input.value=n;window.bcalc[input.dataset.cship][input.dataset.ship]=n;}));notify('Spreadsheet counts pasted.');});
async function loadAllianceAttackBoard(){const box=document.getElementById('allianceAttackBoard');if(!box)return;try{const data=await centralDirectoryRequest('/api/alliance-attack');if(allianceTab!=='attack'||!box.isConnected)return;box.innerHTML='<div class="note">One active claim per player; one claimant per target. Administrators follow the same limit. This board plans operations and does not launch fleets.</div>'+(data.canManage?'<form id="attackCreateForm" class="attack-create"><label>Target coordinates<input name="coords" placeholder="07:04:02" required></label><label>Operation title<input name="title" maxlength="80" required></label><label>Notes<textarea name="notes" maxlength="2000"></textarea></label><button class="btn primary">ADD TARGET</button></form>':'')+'<div class="attack-targets">'+data.targets.map(t=>'<article class="attack-target"><div class="ph"><b>'+esc(t.title)+'</b><span class="tag">'+esc(t.target_coords)+'</span></div><p>'+esc(t.notes)+'</p><p>Claim: <strong>'+esc(t.claim_name||'Available')+'</strong></p><div class="actions">'+(t.claim_user_id===data.userId?'<button class="btn" data-attack-action="release" data-attack-id="'+esc(t.id)+'">RELEASE MY CLAIM</button>':!t.claim_user_id?'<button class="btn primary" data-attack-action="claim" data-attack-id="'+esc(t.id)+'" '+(data.hasClaim||!data.canClaim?'disabled':'')+'>CLAIM TARGET</button>':'')+(data.canManage?'<button class="btn" data-attack-action="close" data-attack-id="'+esc(t.id)+'">CLOSE OPERATION</button>':'')+'</div></article>').join('')+'</div>'+(data.targets.length?'':'<p>No open attack targets.</p>');}catch(error){box.textContent=error.message;}}
document.addEventListener('submit',async e=>{if(e.target.id!=='attackCreateForm')return;e.preventDefault();const f=new FormData(e.target);try{await centralDirectoryRequest('/api/alliance-attack',{action:'create',coords:f.get('coords'),title:f.get('title'),notes:f.get('notes')});loadAllianceAttackBoard();notify('Attack target added.');}catch(error){notify(error.message,true);}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-attack-action]');if(!b)return;b.disabled=true;try{await centralDirectoryRequest('/api/alliance-attack',{action:b.dataset.attackAction,id:b.dataset.attackId});await loadAllianceAttackBoard();notify('Attack board updated.');}catch(error){b.disabled=false;notify(error.message,true);}});

function setGalaxyTotalsSpan(heading){const cell=document.getElementById('browserTotals')?.querySelector?.('td');if(cell)cell.colSpan=heading?.children.length||10;}
function politicsBriefingHTML(){return '<section class="diplomatic-briefing"><div class="council-seal" aria-hidden="true"><svg viewBox="0 0 100 100"><circle cx="50" cy="50" r="33" fill="none" stroke="currentColor" stroke-width="2"/><path d="M21 78Q-2 43 25 15M79 78Q102 43 75 15M25 18L17 29M19 34L12 44M18 50L13 60M23 65L19 74M75 18L83 29M81 34L88 44M82 50L87 60M77 65L81 74" fill="none" stroke="currentColor" stroke-width="3"/><path d="M50 25 55 43 74 43 59 54 64 72 50 61 36 72 41 54 26 43 45 43Z" fill="currentColor" opacity=".75"/></svg></div><div><small>GALACTIC COUNCIL · DIPLOMATIC CHAMBER</small><h3>'+esc(state.politics.banner||'Galaxy council')+'</h3><p>Representation · Cooperation · Governance</p></div><div class="council-office"><small>GALACTIC COMMANDER</small><b>'+esc(state.politics.gc||'Not elected')+'</b><small>CABINET OFFICES</small><b>'+Object.keys(state.politics.ministers||{}).length+'</b></div></section>';}
function galaxyTreasuryBriefingHTML(){const fund=state.galaxyFund,total=Object.keys(RES).reduce((n,k)=>n+(fund[k]||0),0);return '<section class="treasury-briefing"><div><small>GALACTIC TREASURY · RESERVE ALLOCATION</small><h3>Galaxy Fund</h3><p>Contributions finance relief for eligible planets.</p></div><div class="treasury-total"><small>TOTAL RESOURCE UNITS</small><b>'+nfmt(total)+'</b></div><div class="reserve-allocation">'+Object.keys(RES).map(k=>'<div data-resource="'+k+'"><span>'+RES[k].label+'</span><div class="reserve-track"><i style="width:'+(total?100*(fund[k]||0)/total:0)+'%"></i></div><small>'+nfmt(fund[k]||0)+'</small></div>').join('')+'</div></section>';}

function tickerStatusHTML(){const ended=state.tick>=state.roundLength,status=ended?'ROUND ENDED':state.config.tickerStopped?'STOPPED':state.config.tickerPaused?'PAUSED':'RUNNING',tone=ended||state.config.tickerStopped?'stopped':state.config.tickerPaused?'paused':'running',next=tone==='running'?countdown():status==='PAUSED'?'Paused':'—',action=state.tickerLastAction;return '<section class="ticker-live-status '+tone+'"><div class="ticker-status-heading"><span class="ticker-state-dot" aria-hidden="true"></span><strong>'+status+'</strong><small>CURRENT TICKER INFORMATION</small></div><div class="ticker-status-grid"><div><small>CURRENT TICK</small><b>'+state.tick+' / '+state.roundLength+'</b></div><div><small>TICK INTERVAL</small><b>'+nfmt(state.config.tickHours*60)+' minutes</b></div><div><small>NEXT TICK IN</small><b data-ticker-countdown>'+esc(next)+'</b></div><div><small>AUTOMATIC START</small><b>'+esc(state.config.tickerAutoStartAt?new Date(state.config.tickerAutoStartAt).toLocaleString():'Not scheduled')+'</b></div><div><small>LAST PROCESSED TICK</small><b>'+esc(state.lastTickAt?new Date(state.lastTickAt).toLocaleString():'No tick recorded yet')+'</b></div></div>'+(action?'<p class="ticker-action-confirmation" role="status">✓ '+esc(action.message)+' <time>'+new Date(action.at).toLocaleTimeString()+'</time></p>':'')+'</section>';}
function refreshTickerStatusBox(){const box=document.getElementById('tickerStatusBox');if(!box)return;const signature=JSON.stringify([state.tick,state.roundLength,state.config,state.lastTickAt,state.tickerLastAction]);if(box.dataset.signature!==signature){box.dataset.signature=signature;box.innerHTML=tickerStatusHTML();}else{const next=box.querySelector?.('[data-ticker-countdown]');if(next&&!state.config.tickerStopped&&!state.config.tickerPaused&&state.tick<state.roundLength)next.textContent=countdown();}}

function workforceAllocationLimit(){return Math.min(100,50+10*Math.max(0,Math.min(5,state.research.population||0)));}
function validWorkforceAssignments(values){return Object.keys(WORKFORCE_LIMITS).every(k=>Number.isInteger(values[k])&&values[k]>=0&&values[k]<=WORKFORCE_LIMITS[k])&&Object.values(values).reduce((n,v)=>n+v,0)<=workforceAllocationLimit();}
function normalizeWorkforceAssignments(){const keys=Object.keys(WORKFORCE_LIMITS),values=Object.fromEntries(keys.map(k=>[k,Math.max(0,Math.min(WORKFORCE_LIMITS[k],Math.trunc(Number(state.workforce?.[k])||0)))])),total=Object.values(values).reduce((n,v)=>n+v,0),limit=workforceAllocationLimit();if(total>limit){const fractions=keys.map(k=>({k,value:values[k]*limit/total}));for(const x of fractions)values[x.k]=Math.floor(x.value);let remaining=limit-Object.values(values).reduce((n,v)=>n+v,0);for(const x of fractions.sort((a,b)=>(b.value%1)-(a.value%1)))if(remaining-->0)values[x.k]++;}state.workforce=values;}

let orderPageRefreshPending=false;
async function refreshPageAfterOrder(){if(orderPageRefreshPending)return;orderPageRefreshPending=true;save();try{if(typeof sessionStorage!=='undefined')sessionStorage.setItem(SAVE_KEY+'-order-return',JSON.stringify({page:document.querySelector('.page.active')?.id?.slice(5)||'overview',allianceTab,scroll:window.scrollY||0,at:Date.now()}));if(typeof syncPlanetDirectory==='function')await syncPlanetDirectory();save();location.reload();}catch(error){orderPageRefreshPending=false;notify('Order saved. Refresh the page to reload the latest view.',true);}}
if(typeof window.addEventListener==='function')window.addEventListener('load',()=>{if(typeof sessionStorage==='undefined')return;let saved;try{saved=JSON.parse(sessionStorage.getItem(SAVE_KEY+'-order-return')||'null');sessionStorage.removeItem(SAVE_KEY+'-order-return');}catch{return;}if(!saved||Date.now()-saved.at>60000)return;allianceTab=saved.allianceTab||'home';renderAlliance();if(document.getElementById('page-'+saved.page))navigate(saved.page);setTimeout(()=>window.scrollTo({top:saved.scroll||0,behavior:'instant'}),100);notify('Order saved. Page refreshed.');});

function structureCapacityStats(){const built=Object.values(state.buildings).reduce((n,v)=>n+v,0),pending=state.constructionQueue.length+(state.construction?1:0),limit=buildingLimit();return {built,pending,limit,remaining:Math.max(0,limit-built-pending)};}
function affordableStructureCount(id){const d=BUILDINGS[id],room=structureCapacityStats().remaining,stock={...state.resources},start=(state.buildings[id]||0)+state.constructionQueue.filter(o=>o.id===id).length+(state.construction?.id===id?1:0);let count=0;for(;count<room;count++){const n=start+count+1,f=(n**1.25/1000+1)*n,cost=Object.fromEntries(Object.entries(d.cost).map(([k,v])=>[k,Math.ceil(v*f)]));if(Object.entries(cost).some(([k,v])=>stock[k]<v))break;for(const [k,v] of Object.entries(cost))stock[k]-=v;}return count;}
function structureBonusSummary(id){const owned=state.buildings[id]||0,d=BUILDINGS[id];let total='';if(id.endsWith('Refinery'))total=nfmt(owned*1100)+' base resource units / tick';else if(id==='biodome')total=nfmt(owned*50)+' extra resident places';else if(id==='financeCenter')total='+'+(owned*.5)+'% income';else if(id==='researchLab')total=nfmt(owned*24)+' base RP / tick before workforce modifiers';else if(d.kind==='Factory')total=owned+' production '+(owned===1?'facility':'facilities');const description=id==='biodome'?'+50 housing and +1 resident / tick per dome. Growth research: +'+populationGrowthBonus()+'%. Residents add mining income and CU/RP.':d.desc;return '<span>'+esc(description)+'</span>'+(total?'<small>Current: '+esc(total)+'</small>':'');}
function currentStructuresHTML(){const cap=structureCapacityStats();return '<section class="panel current-structures-panel"><div class="ph"><div class="pt">CURRENT STRUCTURES & BONUSES</div><span class="meta">'+cap.built+' BUILT · '+cap.pending+' IN PROGRESS · '+cap.remaining+' FREE / '+cap.limit+' SLOTS</span></div><div class="table-wrap"><table class="table current-structures-table"><colgroup><col style="width:23%"><col style="width:6%"><col style="width:7%"><col style="width:7%"><col style="width:7%"><col style="width:20%"><col style="width:30%"></colgroup><thead><tr><th>Facility</th><th>Owned</th><th>In progress</th><th>Free slots</th><th>Affordable</th><th>Next build cost</th><th>Bonus / effect</th></tr></thead><tbody>'+Object.entries(BUILDINGS).map(([id,d])=>{const pending=state.constructionQueue.filter(o=>o.id===id).length+(state.construction?.id===id?1:0),cost=buildingCost(id);return '<tr class="structure-register-row"><td data-label="Facility"><div class="structure-register-identity">'+structureGlyph(id)+'<div><b>'+esc(d.name)+'</b><small>'+esc(d.kind)+'</small></div></div></td><td data-label="Owned"><span class="structure-register-number">'+nfmt(state.buildings[id]||0)+'</span></td><td data-label="In progress">'+pending+'</td><td data-label="Free slots">'+cap.remaining+'</td><td data-label="Affordable">'+affordableStructureCount(id)+'</td><td data-label="Next build cost"><div class="structure-register-cost">'+Object.entries(cost).filter(([,n])=>n>0).map(([key,n])=>'<span class="structure-register-price '+esc(key)+'"><span>'+esc(RES[key].label)+'</span><b>'+nfmt(n)+'</b></span>').join('')+'</div></td><td data-label="Bonus / effect"><div class="structure-register-effect"><img src="/assets/structures/'+id+'.svg" loading="lazy" alt="'+esc(d.name)+' illustration"><div>'+structureBonusSummary(id)+'</div></div></td></tr>';}).join('')+'</tbody></table></div><div class="note">Free slots are shared by all facilities, including active and queued builds. Affordable counts are alternatives based on current resources. Infrastructure research increases the shared limit.</div></section>';}

function syncTransferAmountState(){const all=document.getElementById('transferShip')?.value==='group:all',amount=document.getElementById('transferAmount');if(amount){amount.disabled=all;amount.title=all?'All ships in the source fleet will be moved.':'Amount per selected ship type';}}
document.addEventListener('change',e=>{if(e.target.id==='transferShip')syncTransferAmountState();});

function attachAchievementReceipt(quests){const totals={metal:0,crystal:0,eonium:0,research:0,construction:0,population:0,structures:{},roids:{metal:0,crystal:0,eonium:0}},entries=quests.map(q=>{const reward=state.questRewardReceipts?.[q[0]]||questReward(q);totals.population+=reward.population||0;for(const [id,n] of Object.entries(reward.structures||{}))totals.structures[id]=(totals.structures[id]||0)+n;for(const k of ['metal','crystal','eonium','research','construction'])totals[k]+=reward[k]||0;for(const k of ['metal','crystal','eonium'])totals.roids[k]+=reward.roids[k]||0;return {id:q[0],name:q[1],office:QUEST_CATEGORIES.find(c=>c.quests.some(x=>x[0]===q[0]))?.name||'Achievements',medal:'Gold claim medal',reward};});const receipt={entries,totals,medals:entries.length};if(state.news[0])state.news[0].achievementReceipt=receipt;return receipt;}
function achievementReceiptHTML(receipt){const t=receipt.totals,types=[['SETTLERS',t.population||0,''],...Object.entries(t.structures||{}).map(([id,n])=>[BUILDINGS[id].name.toUpperCase(),n,'']),['METAL',t.metal,'metal'],['CRYSTAL',t.crystal,'crystal'],['EONIUM',t.eonium,'eonium'],['RESEARCH POINTS',t.research,''],['CONSTRUCTION UNITS',t.construction,''],['METAL ASTEROIDS',t.roids.metal,'metal'],['CRYSTAL ASTEROIDS',t.roids.crystal,'crystal'],['EONIUM ASTEROIDS',t.roids.eonium,'eonium']];return '<section class="achievement-receipt"><div class="achievement-receipt-banner"><div class="receipt-medal-emblem" aria-hidden="true">'+questMedalIcon(true)+'</div><div><span class="eyebrow">COMMAND HONOURS · REWARD RECEIPT</span><h3>'+ (receipt.entries.length===1?'Achievement claimed!':'Achievements claimed!')+'</h3><p>'+receipt.entries.length+' '+(receipt.entries.length===1?'achievement':'achievements')+' · '+receipt.medals+' '+(receipt.medals===1?'gold claim medal':'gold claim medals')+'</p></div><span class="receipt-sparkle" aria-hidden="true">✦</span></div><div class="receipt-awards">'+receipt.entries.map(e=>'<article><span>'+questMedalIcon(true)+'</span><div><b>'+esc(e.name)+'</b><small>'+esc(e.office)+'</small><small class="receipt-medal-label">'+esc(e.medal)+'</small></div></article>').join('')+'</div><h4>TOTAL REWARDS CLAIMED</h4><div class="receipt-totals">'+types.map(([label,n,resource])=>'<div>'+(resource?'<span class="quest-resource-icon '+resource+'" aria-hidden="true"></span>':'<span class="receipt-point-icon" aria-hidden="true">'+(label==='RESEARCH POINTS'?'RP':'CU')+'</span>')+'<span><small>'+label+'</small><b>+'+nfmt(n||0)+'</b></span></div>').join('')+'</div><p class="receipt-footer">✓ Added to your Bonuses bank. Allocate rewards from Achievements → Bonuses. Gold medals mark claimed achievement rewards.</p></section>';}

function resolveBiodomeDamage(ships,count,previousDamage,population,populationBase=1000){const before=Math.max(0,Math.floor(count||0)),damageBefore=before?Math.max(0,Math.min(999,Math.floor(previousDamage||0))):0,fire=Object.entries(ships).reduce((sum,[id,n])=>sum+(SHIPS[id]?.type==='Struc'?n*(SHIPS[id].guns||1)*(SHIPS[id].damage||0):0),0),damage=Math.min(Math.max(0,before*1000-damageBefore),Math.max(0,Math.floor(fire))),total=damageBefore+damage,destroyed=Math.min(before,Math.floor(total/1000)),after=before-destroyed,damageAfter=after?total%1000:0,populationLost=Math.min(Math.max(0,(population||0)-populationBase),Math.floor(total/20)-Math.floor(damageBefore/20));return {before,after,destroyed,damageBefore,damageAfter,populationLost};}
function allianceWarBonus(target){const declarations=state.alliance.warDeclarations||{},active=(state.alliance.wars||[]).filter(name=>!declarations[name]||state.tick<declarations[name].expiresAt),war=declarations[target];if(active.includes(target))return war?{capture:war.captureBonus,xp:war.xpBonus}:{capture:5,xp:25};return active.length?{capture:-5,xp:-25}:{capture:0,xp:0};}
function expireAllianceWars(){const a=state.alliance;if(!a)return;for(const [name,war] of Object.entries(a.warDeclarations||{}))if(state.tick>=war.expiresAt&&a.wars.includes(name)){a.wars=a.wars.filter(n=>n!==name);addNews('The 48-tick war declared by '+a.name+' against '+name+' has expired.','info');}}
function diplomacyReportHTML(d){const war=d.action==='war',bonus=d.bonus;return '<section class="war-report"><h3>'+esc(d.source)+(war?' declared war against ':' declared peace with ')+esc(d.target)+'</h3><blockquote><b>'+esc(d.source)+' envoy:</b> '+(war?'Our council has sealed the war mandate. The border beacons now mark your fleets as hostile.':'Our council withdraws the war mandate. Let trade lanes reopen under a quiet sky.')+'</blockquote><blockquote><b>'+esc(d.target)+' communications officer:</b> '+(war?'Transmission received. Civilian habitats are being secured; command is placing the defence watch on alert.':'Transmission acknowledged. We have recorded your declaration of peace.')+'</blockquote><div class="war-bonuses">'+(war&&bonus?'<b>Asteroid capture: +'+bonus.capture+' percentage points</b><b>Capture XP: +'+bonus.xp+'%</b><b>Duration: 48 ticks</b>':'<b>No war bonus applies to this peace declaration.</b>')+'</div><small>Fictional diplomatic transcript. '+(war?'Bonuses apply to attacks by '+esc(d.source)+' on '+esc(d.target)+'. Other targets during an active war: −5 capture points and −25% capture XP.':'Peace is declared by the sender; it does not cancel a separate declaration by the other alliance.')+'</small></section>';}

function planetTypeHTML(){const t=planetTypeFor(state);return '<section class="panel planet-type-register"><div class="ph"><div class="pt">01 · PLANETARY SURVEY</div><span class="meta">COLONIAL DEVELOPMENT AUTHORITY</span></div><div class="planet-survey-body"><img src="/assets/planets/'+t.id+'.svg" alt="'+esc(t.name)+' planet"><div><small>'+esc(t.rarity||'Standard')+' · '+esc(t.family||'Original')+' · '+esc(t.statsOrigin||'Original gameplay world')+'</small><h3>'+esc(t.name)+'</h3><p>'+esc(t.lore)+'</p><div class="planet-survey-stats">'+[['Fleet ETA',(t.travelEtaBonus||0)+' ticks'],['Bonus salvage',(t.salvageBonusPercent||0)+'%'],['Habitability',t.habitability+'%'],['Biodiversity',t.biodiversity+'%'],['Moisture',t.moisture+'%'],['Rockiness',t.rockiness+'%'],['Starting residents',nfmt(t.basePopulation)],['Population growth', (t.growthPercent>=0?'+':'')+t.growthPercent+'%']].map(([k,v])=>'<span><small>'+k+'</small><b>'+v+'</b></span>').join('')+'</div><p class="meta">'+populationGrowthRate().toFixed(2)+' residents / tick · '+(state.buildings.biodome||0)+' Biodomes × research '+(1+populationGrowthBonus()/100).toFixed(2)+' × environment '+(1+t.growthPercent/100).toFixed(2)+'</p></div></div></section>';}
function populationDetailHTML(){const cap=populationCapacity(),population=state.population,free=Math.max(0,cap-population),growth=Math.min(free,Math.floor(populationGrowthRate()+(state.populationGrowthCarry||0)+1e-9)),assigned=Object.values(state.workforce).reduce((a,b)=>a+b,0),rows=[['Residents',nfmt(population),'Base colony: '+nfmt(planetBasePopulation(state))],['Housing capacity',nfmt(cap),nfmt(state.buildings.biodome||0)+' Biodomes · +50 each'],['Free housing',nfmt(free),'Growth pauses when full'],['Growth research',nfmt(state.research.demography||0)+' / 5','+20% per level · fractions carried forward'],['Next tick growth','+'+nfmt(growth),populationGrowthRate().toFixed(1)+' residents / tick · +'+populationGrowthBonus()+'% research'],['Population mining bonus','+'+populationIncomeBonus().toFixed(3)+'%','0.001% per resident'],['Population work bonus','+'+populationProductionBonus()+' CU / RP','1 each per full 100 residents'],['Workforce pool',assigned+'% / '+workforceAllocationLimit()+'%','Research '+(state.research.population||0)+' / 5']];return planetTypeHTML()+'<section class="panel population-detail"><div class="ph"><div class="pt">CIVIL POPULATION · COLONY REGISTER</div><span class="meta">LIVE ECONOMY</span></div><div class="population-kpis">'+rows.map(([title,value,note])=>'<article><small>'+title+'</small><b>'+value+'</b><span>'+note+'</span></article>').join('')+'</div><div class="population-housing"><img src="/assets/biodome.svg" alt="Green Ark habitat artwork"><p><b>Green Arks of the Vesper Reach</b><br>Radiation-shielded gardens turn barren ground into living neighbourhoods. Build Biodomes under Construction to house new settlers and expand your mining workforce.</p></div></section>';}

function populationDamageLabel(ship){return ['Cruiser','Battleship'].includes(ship.class)?Number(ship.populationDamage??0.1).toLocaleString('en-US',{maximumFractionDigits:3})+'%':'';}

function havocShipMatrixHTML(){const races=['Terran','Cathaar','Xandathrii','Zikonian','Eitraides'],catalog=Object.fromEntries(races.map(r=>[r,Object.entries(SHIPS).filter(([,d])=>d.race===r).slice(0,10)])),own=catalog[state.race]||catalog.Terran;return '<section class="panel havoc-ship-matrix"><div class="ph"><div class="pt">BASE FLEET · TEN-SHIP RACE MATRIX</div><span class="meta">ONE QUANTITY PER ROW</span></div><div class="table-wrap"><table class="table"><colgroup><col style="width:5%"><col style="width:12%">'+races.map(()=>'<col style="width:16.6%">').join('')+'</colgroup><thead><tr><th>#</th><th>Ships</th>'+races.map(r=>'<th data-ship-race="'+esc(r)+'">'+esc(r)+'</th>').join('')+'</tr></thead><tbody>'+Array.from({length:10},(_,i)=>'<tr><td>'+(i+1)+'</td><td><input id="havocShipSlot-'+i+'" data-havoc-ship-slot="'+i+'" type="number" min="0" max="1000000000" step="1" value="'+(state.fleets.base[own[i]?.[0]]||0)+'" aria-label="Ship quantity for slot '+(i+1)+'"></td>'+races.map(r=>{const d=catalog[r][i]?.[1];return '<td data-ship-race="'+esc(r)+'">'+(d?'<b>'+esc(d.name)+'</b><small>'+esc(d.class)+'</small>':'')+'</td>';}).join('')+'</tr>').join('')+'</tbody></table></div><div class="controls"><button class="btn primary" data-confirm-havoc-setup>CONFIRM SETUP</button><span id="havocConfirmationStatus" class="meta" role="status">Confirmation required before Apply to all.</span></div><div class="note">Each amount creates the corresponding ship shown for that planet’s race in its Base fleet. Other fleet slots and active missions retain their ships.</div></section>';}

document.addEventListener('change',e=>{if(e.target.dataset?.field!=='class'||!e.target.dataset.shipstat)return;const input=document.querySelector('[data-shipstat="'+e.target.dataset.shipstat+'"][data-field="populationDamage"]');if(!input)return;const enabled=['Cruiser','Battleship'].includes(e.target.value);input.disabled=!enabled;if(!enabled)input.value='';else if(input.value==='')input.value='0.1';});

function havocMatrixPresent(){return !!document.getElementById('havocShipSlot-0')?.hasAttribute?.('data-havoc-ship-slot');}
function validateHavocShipMatrix(amounts=Array.from({length:10},(_,i)=>Number(document.getElementById('havocShipSlot-'+i)?.value||0)),planets=state.galaxy){if(amounts.length!==10||amounts.some(n=>!Number.isSafeInteger(n)||n<0||n>1000000000))return {ok:false,error:'Enter whole ship quantities between 0 and 1,000,000,000 in all ten rows.'};const races=[...new Set(planets.map(p=>p.player?state.race:p.race))];for(const race of races){const ships=Object.values(SHIPS).filter(d=>d.race===race);for(let i=0;i<10;i++)if(amounts[i]>0&&!ships[i])return {ok:false,error:race+' has no matching ship for row '+(i+1)+'. Nothing was applied.'};}return {ok:true,amounts};}
function havocFormValues(){const allowed=/^(havocTickMinutes|havocPopulation|havocBiodomeDamage|havocResource-(metal|crystal|eonium)|havocRoids-(metal|crystal|eonium)|havocShipSlot-[0-9]|admTech-[a-zA-Z0-9]+|admBuild-[a-zA-Z0-9]+)$/;return Object.fromEntries([...document.querySelectorAll('#adminContent input[id]')].filter(el=>allowed.test(el.id)).map(el=>[el.id,el.value]).sort(([a],[b])=>a.localeCompare(b)));}
function havocSetupSignature(){return JSON.stringify({values:havocFormValues(),planets:state.galaxy.map(p=>[p.id,p.player?state.race:p.race]).sort(([a],[b])=>String(a).localeCompare(String(b)))});}
function havocPresetKey(){return 'starfall-havoc-presets:'+String(state.centralPlayerId||'local');}
function havocSavedSetups(){try{const data=JSON.parse(localStorage.getItem(havocPresetKey())||'[]');return Array.isArray(data)?data.filter(x=>x&&typeof x.id==='string'&&x.values&&typeof x.values==='object').slice(0,5):[];}catch{return [];}}
function havocPresetOptions(){const list=havocSavedSetups();return '<option value="">Choose a previous setup</option>'+list.map((p,i)=>'<option value="'+esc(p.id)+'">'+(i===0?'Latest':'Previous '+i)+' · '+esc(new Date(p.at).toLocaleString())+'</option>').join('');}
function havocPresetControlsHTML(){return '<section class="panel havoc-preset-panel"><div class="ph"><div class="pt">PREVIOUS HAVOC SETUPS</div><span class="meta">LATEST 5 CONFIRMATIONS</span></div><div class="controls"><label class="field" for="havocPresetSelect">Saved setup<select id="havocPresetSelect">'+havocPresetOptions()+'</select></label><button class="btn" data-load-havoc-setup>LOAD SETUP</button><button class="btn primary" data-confirm-havoc-setup>CONFIRM SETUP</button></div><p class="note">Confirm validates the fleet matrix and saves all current controls. The sixth confirmation replaces the oldest of five. Loading only fills the form; confirm and Apply to all to make changes.</p></section>';}
function confirmHavocSetup(){const check=validateHavocShipMatrix();if(!check.ok){state.havocConfirmedSetup='';const status=document.getElementById('havocConfirmationStatus');if(status)status.textContent=check.error;return notify(check.error,true);}const invalid=[...document.querySelectorAll('#adminContent input[id]')].find(el=>el.type==='number'&&el.checkValidity&&!el.checkValidity());if(invalid)return notify('Check the value for '+(invalid.id||'this field')+'. Nothing was applied.',true);const values=havocFormValues(),at=Date.now(),preset={id:'havoc-'+at+'-'+Math.random().toString(36).slice(2,8),at,values},saved=[preset,...havocSavedSetups()].slice(0,5);localStorage.setItem(havocPresetKey(),JSON.stringify(saved));state.havocConfirmedSetup=havocSetupSignature();save();const select=document.getElementById('havocPresetSelect');if(select){select.innerHTML=havocPresetOptions();select.value=preset.id;}const status=document.getElementById('havocConfirmationStatus');if(status)status.textContent='Confirmed · setup saved · ready to Apply to all.';notify('Setup confirmed and saved ('+saved.length+' / 5).');}
function loadHavocSetup(){const selected=document.getElementById('havocPresetSelect')?.value,preset=havocSavedSetups().find(x=>x.id===selected);if(!preset)return notify('Select a previous Havoc setup.',true);for(const [id,value] of Object.entries(preset.values)){const el=document.getElementById(id);if(el&&Object.prototype.hasOwnProperty.call(havocFormValues(),id))el.value=String(value);}for(const el of document.querySelectorAll('[data-havoc-research]')){const t=TECH_TREE.find(t=>t.id===el.dataset.havocResearch);if(t)el.checked=Number(document.getElementById('admTech-'+t.id)?.value)===t.max;}state.havocConfirmedSetup='';const status=document.getElementById('havocConfirmationStatus');if(status)status.textContent='Saved setup loaded · confirm before applying.';notify('Previous setup loaded. Review and confirm before Apply to all.');}
document.addEventListener('click',e=>{if(e.target.closest('[data-confirm-havoc-setup]'))confirmHavocSetup();if(e.target.closest('[data-load-havoc-setup]'))loadHavocSetup();});
document.addEventListener('input',e=>{if(e.target.closest?.('.havoc-board')&&e.target.id!=='havocPresetSelect'){state.havocConfirmedSetup='';const status=document.getElementById('havocConfirmationStatus');if(status)status.textContent='Changed · confirm this setup again before applying.';}});

function shipRaceLegendHTML(){return '<div class="ship-race-legend" aria-label="Race colour key">'+['Terran','Cathaar','Xandathrii','Zikonian','Eitraides'].map(r=>'<span class="race-code-badge" data-ship-race="'+r+'">'+esc(r)+'</span>').join('')+'</div>';}

document.addEventListener('change',e=>{if(e.target.matches?.('[data-havoc-research]')){state.havocConfirmedSetup='';const status=document.getElementById('havocConfirmationStatus');if(status)status.textContent='Changed · confirm this setup again before applying.';}});

function earthBattleSalvage(report,target){const home=state.galaxy.find(p=>p.player);if(planetTypeFor(state).name!=="Earth"&&planetTypeFor(target).name!=="Earth")return null;const award={metal:0,crystal:0,eonium:0};for(const [arrived,left] of [[report.attacker,report.survivorsA],[report.defender,report.survivorsD]])for(const [id,n] of Object.entries(arrived||{}))for(const k of Object.keys(award))award[k]+=(n-(left[id]||0))*(SHIP_BASELINE[id]?.cost[k]||0);for(const k of Object.keys(award))award[k]=Math.floor(award[k]*.2);return {award,recipient:planetTypeFor(state).name==="Earth"?home?.id:target.id,status:"Pending central settlement"};}

function bonusBuildingAvailable(id){const gates={lightFactory:['fighter',1],mediumFactory:['frigate',1],heavyFactory:['siege',1],metalRefinery:['core',1],crystalRefinery:['core',1],eoniumRefinery:['core',1],financeCenter:['core',2],waveAmplifier:['scans',1],waveDistorter:['scans',2],structureDefense:['siege',1]};const gate=gates[id];return !!BUILDINGS[id]&&(!gate||(state.research[gate[0]]||0)>=gate[1]);}
function resolveQuestReward(raw){const r={metal:0,crystal:0,eonium:0,research:0,construction:0,population:0,roids:{metal:0,crystal:0,eonium:0},...copy(raw),structures:{}};let slots=Math.max(0,buildingLimit()-Object.values(state.buildings).reduce((a,b)=>a+b,0)-(state.construction?1:0)-(state.constructionQueue?.length||0));for(const [id,n] of Object.entries(raw.structures||{})){const count=bonusBuildingAvailable(id)?Math.min(n,slots):0;if(count)r.structures[id]=count;slots-=count;r.construction+=(n-count)*(BUILDINGS[id]?.cu||0);}return r;}
function applyExtraQuestReward(r,bank){bank.population=(bank.population||0)+(r.population||0);for(const [id,n] of Object.entries(r.structures||{}))state.buildings[id]=(state.buildings[id]||0)+n;}
function initialiseQuestArcs(){const specs={education:['Founding Academy','research:population',[1,2,3,4,5],'Complete workforce training level','researchLab'],defense:['Shield of the Reach','research:corvette',[1,2,3,4,5],'Certify corvette defence level','lightFactory'],treasury:['Reclaim the Trade Lanes','resourcesTotal',[30000,60000,100000,200000,400000,700000,1000000,1500000,2000000,3000000,5000000,7500000,10000000,15000000,20000000],'Hold combined resource reserves of','financeCenter'],development:['Colonial Renewal','population',[1100,1200,1400,1600,1800,2200,2500,3500,4000,5000,6000,7500,9000,12000,15000],'Grow the colony to','biodome'],security:['The Watchful Citadel','guards',[5,10,15,25,40,60,80,100,150,200,300,400,600,800,1000],'Maintain security guards','structureDefense'],chiefs:['Command of the Frontier','xp',[100,250,500,750,1000,1500,2500,4000,6500,10000,15000,20000,30000,45000,60000],'Earn command experience','heavyFactory'],veterans:['Names in the Beacon','xp',[1000,2000,4000,6000,8000,12000,16000,22000,28000,35000,45000,60000,80000,100000,125000],'Record veteran experience','structureDefense'],fleet:['The Far Horizon','shipvalue',[10000,25000,50000,100000,150000,250000,350000,600000,900000,1250000,1750000,2500000,3500000,5000000,7500000],'Commission total fleet value','mediumFactory'],clandestine:['Whispers Beyond the Gate','agents',[5,10,15,25,40,60,80,100,150,200,300,400,600,800,1000],'Maintain covert agents','waveDistorter'],intelligence:['The Listening Constellation','scans',[5,10,20,40,75,125,200,350,600,900,1250,1750,2500,3500,5000],'Archive completed scans','waveAmplifier'],counter:['No Signal Unchallenged','building:waveDistorter',[1,2,3,4,6,8,10,12,20,30,40,60,80,120,150],'Maintain Wave Distorters','waveDistorter'],civilCovert:['Quiet Picket & Glassfall','covert:strike',[2,3,4,7,10,12,20,25,35,50,75,100,150,200,300],'Complete worker bribery operations','waveDistorter'],habitats:['Gardens Against the Void','building:biodome',[2,3,4,7,10,12,20,30,40,60,75,100,150,200,300],'Construct Green Ark habitats','biodome'],alliance:['The Shared Charter','forum:alliance',[1,2,3,5,8,12,18,25,35,50,75,100,150,200,300],'Publish alliance forum dispatches','researchLab'],ticker:['The Beacon Clock','tick',[2,3,6,12,24,48,72,96,120,168,240,336,400,500,600],'Reach active round tick','researchLab']};
for(const c of QUEST_CATEGORIES){for(const q of c.quests){if(q[2]===0&&q[3]!=='offsite')q[2]=Number(q[0].match(/\d+/)?.[0])||1;if(q[3]==='offsite'){const metric=c.id==='security'?'guards':c.id==='veterans'?'xp':c.id==='education'?'forum:galaxy':'mission:Attack';q[3]=metric;q[2]=c.id==='veterans'?Math.max(100,Number(q[0].match(/\d+/)?.[0])||100)*100:c.id==='security'?Math.max(5,Number(q[0].match(/\d+/)?.[0])||5):1;q[1]=c.id==='security'?'Build a security watch of '+q[2]+' guards':c.id==='veterans'?'Honour veterans with '+q[2]+' XP':c.id==='education'?'Publish a founding galaxy dispatch':'Launch an attack to defend the frontier';}}
const [arc,metric,targets,label,structure]=specs[c.id];let stage=0;for(const target of targets){if(c.quests.length>=15)break;if(c.quests.some(q=>q[2]===target&&q[3]===metric))continue;stage++;const tier=Math.min(5,Math.ceil(stage/3)),r={metal:200*tier,crystal:150*tier,eonium:100*tier,research:['education','intelligence','clandestine','counter','civilCovert'].includes(c.id)?100*tier:50*tier,construction:50*tier,roids:{metal:0,crystal:0,eonium:0}};if(['development','habitats','alliance','veterans'].includes(c.id))r.population=5*tier;if(stage%5===0)r.structures={[structure]:1};c.quests.push(['arc-'+c.id+'-'+target,label+' '+target.toLocaleString('en-US'),target,metric,{arc,reward:r,lore:arc+' · Chapter '+stage+'. '+({education:'The academy recovers a sealed curriculum and trains the next generation of colonial specialists.',defense:'Escort beacons reconnect the defence line as shipwrights certify a stronger shield.',treasury:'The treasury restores a lost supply lane and releases a measured recovery warrant.',development:'Civil planners open another district, balancing settlement growth with available housing.',security:'The night watch registers new personnel and protects the colony’s life-support corridors.',chiefs:'Fleet command records the campaign and honours disciplined service to the frontier.',veterans:'A memorial beacon preserves the names of those who held the gates open.',fleet:'Navigation crews extend the command’s reach through newly commissioned vessels.',clandestine:'Encrypted field reports trace a quiet route through hostile intelligence networks.',intelligence:'Listening arrays recover another fragment of the lost Miday transmission.',counter:'The signal bureau closes a compromised channel and strengthens its interference lattice.',civilCovert:'Field organisers report the outcome of their campaign among the industrial districts.',habitats:'A Green Ark district brings sheltered gardens and room for new settlers.',alliance:'Shared dispatches turn isolated commands into a coordinated frontier coalition.',ticker:'The timing bureau marks another interval in the recovery of the Vesper network.'})[c.id]}]);}
if(c.quests.length<15)throw Error('Quest arc incomplete: '+c.id);c.arc=arc;c.shortName=({education:'Education',defense:'Defence',treasury:'Treasury',development:'Development',security:'Planetary Security',chiefs:'Joint Chiefs',veterans:'Veterans',fleet:'Fleet',clandestine:'Clandestine Services',intelligence:'Intelligence',counter:'Counter Intelligence',civilCovert:'Covert Civil Operations',habitats:'Habitat Development',alliance:'Alliance Cooperation',ticker:'Temporal Command'})[c.id];}
const order=['education','development','habitats','treasury','defense','security','fleet','chiefs','veterans','intelligence','counter','clandestine','civilCovert','alliance','ticker'];QUEST_CATEGORIES.sort((a,b)=>order.indexOf(a.id)-order.indexOf(b.id));}
initialiseQuestArcs();

setTimeout(renderQuests,0);

function displayPlanetName(name){return String(name||'').replace(/^\s*of\s+/i,'');}

function rollAvailableLocalWorld(){const used=new Set(state.galaxy.map(p=>p.planetType));const pool=PLANET_TYPES.filter(t=>!t.uniquePerRound||!used.has(t.id));return pool[Math.floor(Math.random()*pool.length)];}
